INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C1','sci',5,1,'u3',1,'물질의 변신 — 거품 목욕제·발포 바이타민처럼 물에 넣으면 거품을 내며 녹는 물질, 고체 치약처럼 천천히 풀어지는 물질이 있음 · 물질마다 물에서 변하는 모습이 서로 다름 · 직접 넣어 보기 전에는 알기 어려움',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C2','sci',5,1,'u3',1,'촬영 활동 — 모둠별로 물질 한 가지 고르기 → 빵 끈으로 묶어 나무 막대에 연결(물속 한자리에 두고 잘 보려고) → 물이 담긴 비커에 넣기 → 변하는 모습을 스마트 기기로 동영상 촬영(변하는 순간은 금방 지나가므로 처음부터) → 편집해 제목과 자막을 넣고 함께 보며 이야기',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C3','sci',5,1,'u3',1,'실험 안전 — 실험복·보안경·실험용 장갑을 갖춤 · 유리 기구가 깨지지 않도록 조심 · 실험에 사용하는 물질은 맛보지 않음 · 끝나면 주변을 깨끗이 정리하고 폐기물을 올바르게 처리',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C4','sci',5,1,'u3',2,'세 물질 실험 결과 — 설탕과 가루 바이타민은 물에 녹아 보이지 않게 되고, 탄산 칼슘(석회석 등에서 얻는 흰색 물질)은 녹지 않고 그대로 남음 · 소금은 저으면 보이지 않게 되지만 후춧가루는 저어도 떠다님 · 물에 넣으면 어떤 물질은 녹지만 어떤 물질은 녹지 않음',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C5','sci',5,1,'u3',2,'네 낱말 — 용해: 어떤 물질이 다른 물질에 녹아 골고루 섞이는 현상(일어나는 일) · 용매: 다른 물질을 녹이는 물질(설탕물의 물) · 용질: 용매에 녹는 물질(설탕물의 설탕) · 용액: 용매와 용질이 골고루 섞여 있는 물질(설탕물)',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C6','sci',5,1,'u3',2,'용액의 성질 — 색깔이나 맛 등의 성질이 어느 부분이나 일정하고, 오래 두어도 뜨거나 가라앉는 것이 없음 · 설탕물·소금물은 용액 · 흙탕물·후춧가루를 넣은 물은 섞여 있기만 할 뿐 가라앉거나 떠 있는 것이 있어 용액이 아님 · 그냥 섞여 있는 것과 녹아 골고루 섞인 것은 다름',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C7','sci',5,1,'u3',2,'세 물질 실험 — 결과를 예상 → 유리병 세 개에 물을 같은 양씩(삼분의 이) 넣음 → 설탕·가루 바이타민·탄산 칼슘을 한 숟가락씩 넣음(담는 양을 최대한 같게, 약숟가락을 구분해 써서 섞이지 않게) → 뚜껑을 닫고 흔든 뒤 평평한 곳에서 5분 정도 지나 관찰 → 비교 · 물이 튀지 않게 살살 넣기',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C8','sci',5,1,'u3',3,'용해되는 과정 — 각설탕(용질)을 물(용매)에 넣으면 크기가 점점 작아지며 녹음 → 눈에 보이지 않을 정도로 작아짐 → 물에 골고루 섞이며 설탕물(용액)이 됨 · 녹아서 보이지 않게 되었을 뿐 없어진 것이 아님',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C9','sci',5,1,'u3',3,'무게 비교 — 각설탕이 용해되기 전과 용해된 후의 무게는 같음 · 같은 양의 물에 용질을 많이 녹일수록 용액은 더 무거움(분말주스 열 숟가락 > 한 숟가락)',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C10','sci',5,1,'u3',3,'까닭 — 완전히 용해된 용질은 사라진 것이 아니라 용액 속에 그대로 있음 · 그래서 용해되기 전과 후의 무게가 같음 · 설탕물에서 단맛이 나는 것도 설탕이 그대로 있다는 증거',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C11','sci',5,1,'u3',3,'무게 실험 — 예상 → 유리병에 물을 절반 정도 넣고 뚜껑을 닫음 → 물이 든 유리병과 각설탕 한 개를 담은 페트리 접시를 전자저울에 함께 올려 잼(용해되기 전) → 핀셋으로 각설탕을 넣고 용해되는 모습 관찰 → 다 용해되면 설탕물이 담긴 유리병과 빈 페트리 접시를 함께 올려 잼(용해된 후) · 탐구 결과는 예상과 달라도 사실대로 기록',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C12','sci',5,1,'u3',4,'용질의 종류 — 같은 온도, 같은 양의 물에 용해되는 용질의 양은 용질의 종류에 따라 다름 · 설탕은 모두 용해되고, 소금은 일부가 용해되지 않고 바닥에 남으며, 백반(봉숭아 물들이는 데 쓰는 흰색 물질)은 가장 적게 용해됨 · 같은 조건에서 설탕 > 소금 > 백반 · 어떤 용질이든 끝없이 녹지는 않음',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C13','sci',5,1,'u3',4,'공정한 비교 — 알아보려는 조건 하나만 다르게 하고 나머지는 모두 같게 해야 결과가 그 조건 때문이라고 말할 수 있음 · 용질의 종류를 비교할 때: 물의 온도(상온)·물의 양(50 mL)·약숟가락에 담는 양·젓는 정도는 같게, 용질의 종류만 다르게',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C14','sci',5,1,'u3',4,'실험 방법 — 예상 → 눈금실린더로 비커 세 개에 상온의 물을 50 mL씩 넣음 → 설탕·소금·백반을 한 숟가락씩 넣고 유리 막대로 충분히 저으며 관찰 → 되풀이하며 비교 · 이름 붙임딱지로 비커 표시 · 용질이 바닥에 남으면 더 넣지 않음 · 백반이 피부에 닿지 않게 조심, 맛보지 않기',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C15','sci',5,1,'u3',5,'물의 온도 — 같은 용질이라도 물의 온도에 따라 용해되는 양이 다름 · 물의 양이 같을 때 대체로 물의 온도가 높을수록 용질이 더 많이 용해됨(따뜻한 물에서 백반이 더 많이 녹음) · 용해되는 양에 영향을 주는 두 요인 = 용질의 종류와 물의 온도',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C16','sci',5,1,'u3',5,'더 녹이기 — 바닥에 남아 있는 용질은 물의 온도를 높여 더 녹일 수 있음 · 분말주스는 찬물보다 따뜻한 물에서 더 잘 녹음 · 옷이나 신발에 가루 세제가 남으면 헹구는 물의 온도를 높임 · 용질을 더 넣거나 물을 차갑게 하면 더 녹지 않음',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C17','sci',5,1,'u3',5,'탐구 계획 — 예상 → 다르게 해야 할 조건 정하기(물의 온도 하나: 차가운 물과 따뜻한 물) → 같게 해야 할 조건 정하기(용질의 종류(백반)·물의 양·약숟가락에 담는 양) → 실험 과정 정하기 → 결과를 견주어 탐구 보고서에 적기(탐구 주제·조건·결과·알게 된 점·더 알고 싶은 점) · 다르게 할 조건은 딱 하나',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C18','sci',5,1,'u3',6,'용액의 진하기 — 같은 양의 용매에 용해된 용질의 양이 많고 적은 정도 · 두 용액을 견주어 어느 쪽이 더 진한지 말함(상대적) · 용매의 양을 같게 해야 용질의 양만으로 견줄 수 있음',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C19','sci',5,1,'u3',6,'진한 용액 — 용매의 양이 같을 때 용질이 많이 녹아 있을수록 진한 용액 · 용질의 양이 같을 때 용매가 적을수록 진한 용액 · 물을 더 넣으면 묽어짐',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C20','sci',5,1,'u3',6,'색깔로 비교 — 황설탕 용액은 진할수록 색깔이 더 진함 · 흰 종이를 비커 뒤에 대면 색깔을 더 정확하게 봄 · 백설탕 용액은 색깔이 거의 같아 색깔로는 가리기 어려움',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C21','sci',5,1,'u3',6,'뜨는 정도로 비교 — 크기와 무게가 같은 방울토마토를 넣으면 진한 용액일수록 더 높이 떠오름 · 쓴 방울토마토는 핀셋으로 꺼내 수건으로 닦아 다시 씀 · 사해는 소금이 많이 녹아 있어 몸이 쉽게 떠오름 · 디지털 염도계는 진할수록 수치가 커짐 · 떠 있는 메추리알을 낮추려면 물을 더 넣어 묽게 함 · 맛·색깔·뜨는 정도 등으로 비교(실험에서는 맛보지 않음)',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C22','sci',5,1,'u3',7,'생활 속 용액 — 손 소독제·손 세정제(세균·오염 물질 제거), 구강 청결제(입안을 청결하게), 식물 영양제(양분이 녹아 식물 성장을 도움), 식초(신맛·음식 맛 조절), 간장(짠맛·간 맞추기), 링거액(수액, 포도당 등이 녹아 있어 병 치료), 스포츠 음료, 유리 세정제 · 용액은 실험실에만 있는 것이 아니라 우리 주변에 많고, 상황과 용도에 맞게 이용함 · 모든 용액을 마셔도 되는 것은 아님',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C23','sci',5,1,'u3',7,'조사·공유 — 용액 그림 카드로 경험 이야기 → 용액 한 가지 고르기 → 스마트 기기로 쓰임새·이용 장소·성질을 중심으로 검색 → 표에 정리 → 공유 플랫폼에 올리기 → 알게 된 점 이야기 · 자료의 출처를 밝힘 · 다른 사람의 얼굴이 드러나는 사진은 허락 없이 쓰지 않음 · 기기에서 냄새나 열이 나면 즉시 중지하고 선생님께 알림',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C24','sci',5,1,'u3',8,'디지털 자료 — 소개할 용액 정하기 → 필요한 상황 토의(용액이 없을 때 불편한 점을 떠올려 필요성과 연관 짓기) → 제작 계획 → 종류(포스터·동영상·카드 뉴스)와 제목 정하기 → 디자인 플랫폼으로 만들기(필요한 내용을 요약) → 누리망·사회 관계망 서비스에 공유 → 필요성 소개 → 다른 모둠 자료에 잘한 점을 바르고 고운 말로 댓글 · 크고 화려하게 꾸미는 것보다 필요성을 옳게 설명하는 것이 중요 · 예: 「비눗물이 사라진다면?」',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u3-C25','sci',5,1,'u3',8,'용액과 직업 — 도시 농업 관리사: 수경 재배에 쓰는 배양액(흙처럼 양분을 공급)을 개발 · 식품 공학 기술자: 녹이는 물질의 종류·순서·물의 온도·용액의 진하기를 확인해 원하는 맛과 영양의 음료를 만듦 · 해양학 연구원: 바다는 여러 물질이 녹아 있는 용액, 바닷물의 온도·염분을 조사해 해양 생태계에 미치는 영향을 분석 · 농업·식품·해양 등 여러 분야에서 용액을 연구',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X01','sci',5,'u3',ARRAY['SC5-1-u3-C1']::text[],'물에 넣은 물질은 모두 똑같이 변하거나, 어떤 물질도 물에서 변하지 않는다고 여긴다','물질마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X02','sci',5,'u3',ARRAY['SC5-1-u3-C2']::text[],'물질의 변신을 촬영하는 차례나 도구의 쓰임을 잘못 안다(물질을 굽거나 얼리기, 막대 없이 넣기, 촬영 뒤에 물질 고르기 등)','고르기 → 묶기 → 넣기 → 찍기 → 편집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X03','sci',5,'u3',ARRAY['SC5-1-u3-C3','SC5-1-u3-C7','SC5-1-u3-C11','SC5-1-u3-C14']::text[],'실험할 때의 안전과 정리를 잘못 안다(물질 맛보기, 보안경 벗기, 남은 물질 아무 데나 버리기 등)','맛보지 않고 정리해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X04','sci',5,'u3',ARRAY['SC5-1-u3-C4']::text[],'물에 넣은 물질은 무엇이든 다 녹는다고 여긴다','녹지 않는 물질도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X05','sci',5,'u3',ARRAY['SC5-1-u3-C4','SC5-1-u3-C12']::text[],'녹지 않거나 바닥에 남는 것은 언제나 물이 부족하거나 덜 저었기 때문이라고 여긴다','물질마다 녹는 성질이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X06','sci',5,'u3',ARRAY['SC5-1-u3-C5']::text[],'용해·용매·용질·용액의 뜻을 서로 바꾸어 안다(용해를 물질로, 용액을 현상으로 등)','현상은 용해, 물질은 용액') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X07','sci',5,'u3',ARRAY['SC5-1-u3-C5']::text[],'용매와 용질을 뒤바꾼다(설탕물에서 설탕이 용매, 물이 용질)','녹이는 쪽이 용매') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X08','sci',5,'u3',ARRAY['SC5-1-u3-C6']::text[],'물과 섞여 있기만 하면 흙탕물·후춧가루를 넣은 물도 용액이라고 여긴다','녹아 골고루 섞여야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X09','sci',5,'u3',ARRAY['SC5-1-u3-C6']::text[],'용액의 성질을 잘못 안다(부분마다 맛·색이 달라도, 가라앉는 것이 있어도 용액, 색깔이 있으면 용액이 아님 등)','어느 부분이나 같고 가라앉지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X10','sci',5,'u3',ARRAY['SC5-1-u3-C7']::text[],'세 물질 실험의 조건이나 방법을 잘못 안다(물·물질의 양을 다르게, 약숟가락 하나로 번갈아, 흔들자마자 관찰 등)','같은 양 · 따로 쓰기 · 기다리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X11','sci',5,'u3',ARRAY['SC5-1-u3-C8','SC5-1-u3-C10']::text[],'물에 녹아 보이지 않게 된 용질은 없어진 것이라고 여긴다','용액 속에 그대로 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X12','sci',5,'u3',ARRAY['SC5-1-u3-C9']::text[],'용질이 용해되면 전체 무게가 줄어들거나 늘어난다고 여긴다','용해 전과 후의 무게는 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X13','sci',5,'u3',ARRAY['SC5-1-u3-C8']::text[],'용질이 용해되는 과정을 잘못 안다(크기 그대로 가라앉음, 점점 커짐, 곧바로 물로 변함 등)','점점 작아지며 골고루 섞여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X14','sci',5,'u3',ARRAY['SC5-1-u3-C11']::text[],'무게를 비교하는 실험 방법이나 기록을 잘못 안다(접시를 빼고 재기, 결과를 예상에 맞게 고치기 등)','함께 올리고 사실대로 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X15','sci',5,'u3',ARRAY['SC5-1-u3-C9']::text[],'같은 양의 물에 용질을 많이 녹여도 용액의 무게는 같다고 여긴다','녹인 만큼 무거워져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X16','sci',5,'u3',ARRAY['SC5-1-u3-C12']::text[],'같은 조건의 물에는 모든 용질이 같은 양만큼 녹는다고 여기거나 녹는 양의 차례를 뒤바꾼다','설탕 > 소금 > 백반') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X17','sci',5,'u3',ARRAY['SC5-1-u3-C12']::text[],'용질이 바닥에 남은 것은 덜 넣었거나 실험을 잘못했기 때문이고, 오래 저으면 끝없이 녹는다고 여긴다','녹는 양은 용질마다 정해져 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X18','sci',5,'u3',ARRAY['SC5-1-u3-C13']::text[],'공정하게 비교하는 조건을 잘못 안다(물의 양·온도도 함께 바꾸기, 붙임딱지 색처럼 관계없는 것만 맞추기 등)','하나만 다르게, 나머지는 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X19','sci',5,'u3',ARRAY['SC5-1-u3-C14']::text[],'실험 도구의 쓰임을 서로 바꾸어 안다(눈금실린더로 젓기, 유리 막대로 물의 양 재기 등)','재는 것 · 젓는 것 · 넣는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X20','sci',5,'u3',ARRAY['SC5-1-u3-C14']::text[],'용질이 바닥에 남아도 계속 더 넣거나, 남은 것을 무시하고 다 녹았다고 기록한다','남으면 더 넣지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X21','sci',5,'u3',ARRAY['SC5-1-u3-C15']::text[],'물의 온도는 용질이 용해되는 양과 관계없다고 여긴다','온도도 요인이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X22','sci',5,'u3',ARRAY['SC5-1-u3-C15','SC5-1-u3-C16']::text[],'물의 온도가 낮을수록(차가울수록) 용질이 더 많이 용해된다고 여긴다','따뜻할수록 더 많이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X23','sci',5,'u3',ARRAY['SC5-1-u3-C16']::text[],'바닥에 남은 용질을 녹이려고 용질을 더 넣거나 물을 줄인다','물의 온도를 높여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X24','sci',5,'u3',ARRAY['SC5-1-u3-C17']::text[],'탐구 계획에서 다르게 해야 할 조건을 잘못 정한다(약숟가락 크기·용질의 종류로 정하기, 여러 개일수록 좋다 등)','알아보려는 것 딱 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X25','sci',5,'u3',ARRAY['SC5-1-u3-C18']::text[],'용액의 진하기를 무게·온도·녹인 시간처럼 다른 것으로 안다','같은 용매에 녹은 용질의 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X26','sci',5,'u3',ARRAY['SC5-1-u3-C19']::text[],'진한 용액과 묽은 용액을 뒤바꾼다(물이 많을수록 진하다, 용질이 적을수록 진하다 등)','용질은 많을수록, 용매는 적을수록 진해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X27','sci',5,'u3',ARRAY['SC5-1-u3-C20','SC5-1-u3-C21']::text[],'진한 용액과 묽은 용액은 겉으로 어떤 방법으로도 가릴 수 없다고 여긴다','색깔 · 뜨는 정도로 가려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X28','sci',5,'u3',ARRAY['SC5-1-u3-C21']::text[],'용액이 진할수록 넣은 물체가 더 깊이 가라앉는다고 여긴다','진할수록 높이 떠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X29','sci',5,'u3',ARRAY['SC5-1-u3-C20','SC5-1-u3-C21']::text[],'진하기를 비교하는 방법을 잘못 안다(맛보기, 크기·무게가 다른 방울토마토, 녹인 시간이나 비커 크기 견주기 등)','같은 물체 · 흰 종이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X30','sci',5,'u3',ARRAY['SC5-1-u3-C20']::text[],'백설탕 용액처럼 색깔이 거의 없는 용액도 색깔만 보고 진하기를 쉽게 가릴 수 있다고 여긴다','색이 거의 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X31','sci',5,'u3',ARRAY['SC5-1-u3-C21']::text[],'떠 있는 물체를 낮추려고 용질을 더 넣거나, 높이려고 물을 더 넣는다','물을 더 넣으면 묽어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X32','sci',5,'u3',ARRAY['SC5-1-u3-C22']::text[],'용액은 과학실에서만 볼 수 있다고 여긴다','우리 주변에 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X33','sci',5,'u3',ARRAY['SC5-1-u3-C22']::text[],'생활 속 용액과 그 쓰임을 잘못 짝짓는다(손 소독제로 간 맞추기, 식초로 세균 없애기 등)','상황과 용도에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X34','sci',5,'u3',ARRAY['SC5-1-u3-C22','SC5-1-u3-C23']::text[],'모든 용액은 마시거나 맛보아도 된다고 여긴다','마시면 안 되는 용액이 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X35','sci',5,'u3',ARRAY['SC5-1-u3-C23']::text[],'조사하고 공유하는 방법이나 태도를 잘못 안다(출처 빼기, 베끼기, 얼굴 사진 허락 없이 올리기, 기기에서 열이 나도 계속 쓰기 등)','출처 · 허락 · 안전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X36','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'디지털 자료는 크고 화려하게 꾸밀수록 좋은 자료라고 여긴다','필요성을 옳게 설명했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X37','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'자료에 용액의 필요성 대신 이름만 쓰거나 관계없는 내용(값·포장 색·위험만 등)을 담는다','없을 때의 불편함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X38','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'다른 모둠 자료에 비방하거나 불쾌하게 하는 댓글을 단다','바르고 고운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X39','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'디지털 자료를 만들고 나누는 차례를 잘못 안다(용액도 정하지 않고 공유부터, 댓글부터 등)','계획 → 만들기 → 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X40','sci',5,'u3',ARRAY['SC5-1-u3-C25']::text[],'용액을 연구하는 직업과 하는 일을 잘못 짝짓거나, 바닷물은 용액이 아니라고 여긴다','배양액 · 음료 · 바닷물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u3-X41','sci',5,'u3',ARRAY['SC5-1-u3-C25']::text[],'용액을 연구하는 일은 과학자만 할 수 있거나 우리 생활과 관계없다고 여긴다','여러 분야에서 연구해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#1','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',1,'mc','auto','고른 물질을 물에 넣기 전에 무엇을 하나요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C2","difficulty":1,"kind":"mc","stem":"고른 물질을 물에 넣기 전에 무엇을 하나요?","options":[{"t":"빵 끈으로 묶어 나무 막대에 연결한다","correct":true},{"t":"불에 살짝 구워 둔다","mis":"SC5-1-u3-X02"},{"t":"잘게 부수어 가루로 만든다","mis":"SC5-1-u3-X02"},{"t":"얼음처럼 차갑게 얼린다","mis":"SC5-1-u3-X02"}],"explanation":["준비물을 떠올려요.","빵 끈과 나무 막대예요.","묶어서 막대에 연결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#2','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C3',1,'ox','auto','실험에 사용하는 물질은 맛보지 않아요.',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C3","difficulty":1,"kind":"ox","stem":"실험에 사용하는 물질은 맛보지 않아요.","answer":"O","reason_options":[{"t":"어떤 물질인지 모르고 맛보면 몸에 해로울 수 있기 때문에","correct":true},{"t":"맛을 보면 물질이 변하는 모습이 더 잘 보이기 때문에","mis":"SC5-1-u3-X03"}],"mis":"SC5-1-u3-X03","explanation":["안전을 떠올려요.","몸에 해로울 수 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#3','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',1,'sa','auto','「물질이 변하는 모습을 스마트 기기로 □□□으로 촬영합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C2","difficulty":1,"kind":"sa","stem":"「물질이 변하는 모습을 스마트 기기로 □□□으로 촬영합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["동영상"],"explanation":["움직이는 모습을 남겨요.","세 글자예요.","동영상이에요."],"mis":"SC5-1-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#4','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C1',1,'mc','auto','거품 목욕제를 물에 넣으면 어떻게 되나요?',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C1","difficulty":1,"kind":"mc","stem":"거품 목욕제를 물에 넣으면 어떻게 되나요?","options":[{"t":"거품을 내며 녹는다","correct":true},{"t":"아무 변화가 없다","mis":"SC5-1-u3-X01"},{"t":"더 단단해진다","mis":"SC5-1-u3-X01"},{"t":"물이 모두 사라진다","mis":"SC5-1-u3-X01"}],"explanation":["목욕할 때를 떠올려요.","거품이 나요.","거품을 내며 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#5','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',2,'match','auto','물질의 변신 촬영에 쓰는 준비물과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C2","difficulty":2,"kind":"match","stem":"물질의 변신 촬영에 쓰는 준비물과 하는 일을 알맞게 이으세요.","pairs":[{"l":"빵 끈","r":"고른 물질을 묶는다"},{"l":"나무 막대","r":"빵 끈을 연결해 손으로 잡는다"},{"l":"물이 담긴 비커","r":"물질을 넣는 곳이다"},{"l":"스마트 기기","r":"변하는 모습을 촬영한다"}],"mis":"SC5-1-u3-X02","explanation":["하나씩 떠올려요.","묶고, 잡고, 넣고, 찍어요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#6','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C3',2,'mc','auto','실험이 끝난 뒤 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C3","difficulty":2,"kind":"mc","stem":"실험이 끝난 뒤 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"주변을 깨끗이 정리하고 폐기물을 올바르게 처리한다","correct":true},{"t":"남은 물질을 아무 데나 버린다","mis":"SC5-1-u3-X03"},{"t":"비커를 그대로 두고 자리를 떠난다","mis":"SC5-1-u3-X03"},{"t":"남은 물질을 맛본다","mis":"SC5-1-u3-X03"}],"explanation":["끝난 뒤를 떠올려요.","깨끗이 정리해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#7','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C1',2,'mc','auto','물질을 물에 넣었을 때 변하는 모습에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C1","difficulty":2,"kind":"mc","stem":"물질을 물에 넣었을 때 변하는 모습에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"물질마다 변하는 모습이 서로 다르다","correct":true},{"t":"모든 물질이 똑같이 거품을 낸다","mis":"SC5-1-u3-X01"},{"t":"모든 물질이 똑같이 천천히 풀어진다","mis":"SC5-1-u3-X01"},{"t":"어떤 물질도 물에서 변하지 않는다","mis":"SC5-1-u3-X01"}],"explanation":["여러 모둠의 영상을 떠올려요.","거품도, 풀어짐도 있어요.","물질마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#8','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C3',2,'error','auto','실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C3","difficulty":2,"kind":"error","stem":"실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「보안경은 불편하니까 벗고 하자.」","correct":true,"mis_target":"SC5-1-u3-X03"},{"t":"수아 — 「유리 기구가 깨지지 않게 조심하자.」","mis":"SC5-1-u3-X03"},{"t":"민재 — 「실험복과 실험용 장갑을 갖추자.」","mis":"SC5-1-u3-X03"}],"explanation":["눈을 지키는 도구예요.","보안경은 써야 해요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#9','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',2,'blank','auto','「고른 물질을 (    )(으)로 묶고, 나무 막대에 연결합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C2","difficulty":2,"kind":"blank","stem":"「고른 물질을 (    )(으)로 묶고, 나무 막대에 연결합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"빵 끈","correct":true},{"t":"유리병","mis":"SC5-1-u3-X02"},{"t":"스마트 기기","mis":"SC5-1-u3-X02"},{"t":"비커","mis":"SC5-1-u3-X02"}],"explanation":["묶는 데 쓰는 것이에요.","끈이에요.","빵 끈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_basic#10','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',3,'mc','auto','물질을 나무 막대에 매달아 물에 넣는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X02','SC5-1-u3-X01']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C2","difficulty":3,"kind":"mc","stem":"물질을 나무 막대에 매달아 물에 넣는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"변하는 모습을 한자리에서 잘 볼 수 있게 하려고","correct":true},{"t":"물질을 더 무겁게 만들려고","mis":"SC5-1-u3-X02"},{"t":"물이 넘치지 않게 하려고","mis":"SC5-1-u3-X02"},{"t":"물질이 변하지 않게 막으려고","mis":"SC5-1-u3-X01"}],"explanation":["막대를 잡고 있어요.","물질이 한자리에 있어요.","잘 보고 잘 찍으려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#1','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C2',2,'mc','auto','물질의 변신을 촬영하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C2","difficulty":2,"kind":"mc","stem":"물질의 변신을 촬영하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉤ → ㉢","correct":true},{"t":"㉡ → ㉠ → ㉣ → ㉤ → ㉢","mis":"SC5-1-u3-X02"},{"t":"㉤ → ㉡ → ㉣ → ㉠ → ㉢","mis":"SC5-1-u3-X02"},{"t":"㉡ → ㉣ → ㉠ → ㉢ → ㉤","mis":"SC5-1-u3-X02"}],"explanation":["먼저 물질을 골라요.","묶고 넣은 다음 찍어요.","편집은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 나무 막대에 연결한 물질을 물에 넣는다.","㉡ 모둠별로 여러 가지 물질 가운데 한 가지를 고른다.","㉢ 영상을 편집해 제목과 자막을 넣고 함께 본다.","㉣ 고른 물질을 빵 끈으로 묶어 나무 막대에 연결한다.","㉤ 물질이 변하는 모습을 동영상으로 촬영한다."],"title":"물질의 변신 촬영하기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#2','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C1',2,'ox','auto','물질을 직접 물에 넣어 보기 전에는 어떻게 변할지 알기 어려워요.',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C1","difficulty":2,"kind":"ox","stem":"물질을 직접 물에 넣어 보기 전에는 어떻게 변할지 알기 어려워요.","answer":"O","reason_options":[{"t":"물질마다 물에서 변하는 모습이 다르기 때문에","correct":true},{"t":"모든 물질은 물에 넣으면 똑같이 변하기 때문에","mis":"SC5-1-u3-X01"}],"mis":"SC5-1-u3-X01","explanation":["여러 물질을 떠올려요.","모습이 달랐어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#3','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C2',3,'mc','auto','물질을 물에 넣는 처음 순간부터 촬영하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X02','SC5-1-u3-X01']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C2","difficulty":3,"kind":"mc","stem":"물질을 물에 넣는 처음 순간부터 촬영하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"변하는 순간은 금방 지나가기 때문에","correct":true},{"t":"처음 장면만 영상에 쓰기 때문에","mis":"SC5-1-u3-X02"},{"t":"나중에 찍으면 물질이 처음 모습으로 돌아오기 때문에","mis":"SC5-1-u3-X01"},{"t":"처음에 찍어야 물이 넘치지 않기 때문에","mis":"SC5-1-u3-X02"}],"explanation":["발포 바이타민을 떠올려요.","빠르게 변해요.","놓치지 않으려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#4','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C2',3,'mc','auto','촬영을 마친 뒤에 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C2","difficulty":3,"kind":"mc","stem":"촬영을 마친 뒤에 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"제목과 자막을 넣어 영상을 편집한다","correct":true},{"t":"넣어 볼 물질을 고른다","mis":"SC5-1-u3-X02"},{"t":"물질을 빵 끈으로 묶는다","mis":"SC5-1-u3-X02"},{"t":"나무 막대에 연결한 물질을 물에 넣는다","mis":"SC5-1-u3-X02"}],"explanation":["찍기 전과 뒤를 나눠요.","찍은 다음에는 다듬어요.","편집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#5','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C1',3,'error','auto','영상을 함께 보고 알게 된 점을 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C1","difficulty":3,"kind":"error","stem":"영상을 함께 보고 알게 된 점을 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「어떤 물질이든 물에 넣으면 똑같이 변해.」","correct":true,"mis_target":"SC5-1-u3-X01"},{"t":"지호 — 「거품을 내며 변하는 물질도 있어.」","mis":"SC5-1-u3-X01"},{"t":"예서 — 「천천히 풀어지는 물질도 있어.」","mis":"SC5-1-u3-X01"}],"explanation":["영상마다 달랐나요?","모습이 서로 달라요.","하린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#6','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C3',3,'mc','auto','친구가 발포 바이타민이 어떤 맛인지 궁금하다며 맛보려고 해요. 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C3","difficulty":3,"kind":"mc","stem":"친구가 발포 바이타민이 어떤 맛인지 궁금하다며 맛보려고 해요. 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"실험에 쓰는 물질은 맛보지 않아야 한다고 말해 준다","correct":true},{"t":"조금만 맛보면 괜찮다고 말해 준다","mis":"SC5-1-u3-X03"},{"t":"맛을 보아야 변한 모습을 알 수 있다고 말해 준다","mis":"SC5-1-u3-X03"},{"t":"물에 넣은 뒤에 맛보라고 말해 준다","mis":"SC5-1-u3-X03"}],"explanation":["실험 약속이에요.","맛보지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#7','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C1',3,'mc','auto','모둠별 관찰 기록을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C1","difficulty":3,"kind":"mc","stem":"모둠별 관찰 기록을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"물질마다 물에서 변하는 모습이 다르다","correct":true},{"t":"세 물질이 똑같이 변했다","mis":"SC5-1-u3-X01"},{"t":"거품을 내는 물질만 물에서 변한다","mis":"SC5-1-u3-X01"},{"t":"물에 넣으면 물질이 변하지 않는다","mis":"SC5-1-u3-X01"}],"explanation":["세 모둠을 견줘요.","거품, 풀어짐, 부서짐이에요.","서로 달라요."],"asset":{"type":"passage","lines":["1모둠 발포 바이타민 — 거품을 많이 내며 빠르게 작아졌다.","2모둠 고체 치약 — 천천히 풀어지며 뿌옇게 퍼졌다.","3모둠 알약 — 조금씩 부서지며 작아졌다."],"title":"모둠별 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#8','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C2',4,'mc','auto','2모둠의 고체 치약은 천천히 풀어져서 영상이 아주 길어졌어요. 친구들과 함께 보기 좋게 하려면 어떻게 하면 좋을까요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C2","difficulty":4,"kind":"mc","stem":"2모둠의 고체 치약은 천천히 풀어져서 영상이 아주 길어졌어요. 친구들과 함께 보기 좋게 하려면 어떻게 하면 좋을까요?","options":[{"t":"변하는 장면이 잘 드러나게 영상을 다듬고 제목과 자막을 넣는다","correct":true},{"t":"다시 찍지 않고 말로만 설명한다","mis":"SC5-1-u3-X02"},{"t":"영상을 지우고 기억해 두었다가 나중에 그린다","mis":"SC5-1-u3-X02"},{"t":"고체 치약을 불에 구워 다시 찍는다","mis":"SC5-1-u3-X02"}],"explanation":["찍은 영상을 살려요.","편집할 수 있어요.","다듬고 자막을 넣어요."],"asset":{"type":"passage","lines":["1모둠 발포 바이타민 — 거품을 많이 내며 빠르게 작아졌다.","2모둠 고체 치약 — 천천히 풀어지며 뿌옇게 퍼졌다.","3모둠 알약 — 조금씩 부서지며 작아졌다."],"title":"모둠별 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#9','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C3',4,'mc','auto','실험을 마쳤더니 비커에 물질이 녹은 물이 남았어요. 가장 알맞은 처리 방법은 어느 것인가요?',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C3","difficulty":4,"kind":"mc","stem":"실험을 마쳤더니 비커에 물질이 녹은 물이 남았어요. 가장 알맞은 처리 방법은 어느 것인가요?","options":[{"t":"선생님이 알려 준 방법대로 폐기물을 올바르게 처리하고 주변을 정리한다","correct":true},{"t":"가까운 화분에 아무렇게나 쏟아 버린다","mis":"SC5-1-u3-X03"},{"t":"그대로 두고 다음 반이 치우게 한다","mis":"SC5-1-u3-X03"},{"t":"맛을 보고 버릴지 정한다","mis":"SC5-1-u3-X03"}],"explanation":["남은 것도 실험의 일부예요.","올바르게 처리해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L01_challenge#10','sci',5,1,'u3','L01','g5_1_sci_u3_L01_challenge','lesson_challenge','SC5-1-u3-C1',4,'essay','teacher','물질의 변신을 촬영한 활동을 떠올려, 알게 된 점 두 가지와 실험할 때 지켜야 할 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C1","difficulty":4,"kind":"essay","stem":"물질의 변신을 촬영한 활동을 떠올려, 알게 된 점 두 가지와 실험할 때 지켜야 할 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 물에 넣으면 모습이 변하는 물질이 있고, 물질마다 변하는 모습이 다르다. 발포 바이타민은 거품을 내며 빠르게 작아졌고, 고체 치약은 천천히 풀어졌다. 실험할 때에는 실험에 쓰는 물질을 맛보지 않고 보안경과 실험용 장갑을 갖춘다. 끝나면 주변을 정리하고 폐기물을 올바르게 처리한다.","scoring_points":["물질마다 변하는 모습이 다르다고 썼는가","변한 모습의 예를 들었는가","지킬 점 두 가지를 바르게 썼는가"]},"explanation":["영상을 떠올려요.","안전을 떠올려요.","두 가지씩 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#1','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C5',1,'mc','auto','어떤 물질이 다른 물질에 녹아 골고루 섞이는 현상을 무엇이라고 하나요?',ARRAY['SC5-1-u3-X06']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C5","difficulty":1,"kind":"mc","stem":"어떤 물질이 다른 물질에 녹아 골고루 섞이는 현상을 무엇이라고 하나요?","options":[{"t":"용해","correct":true},{"t":"용액","mis":"SC5-1-u3-X06"},{"t":"용매","mis":"SC5-1-u3-X06"},{"t":"용질","mis":"SC5-1-u3-X06"}],"explanation":["일어나는 일을 가리켜요.","현상의 이름이에요.","용해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#2','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C5',1,'sa','auto','「설탕물에서 설탕처럼 용매에 녹는 물질을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C5","difficulty":1,"kind":"sa","stem":"「설탕물에서 설탕처럼 용매에 녹는 물질을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["용질"],"explanation":["녹는 쪽이에요.","두 글자예요.","용질이에요."],"mis":"SC5-1-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#3','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C4',1,'ox','auto','탄산 칼슘은 물에 넣고 흔들어도 녹지 않아요.',ARRAY['SC5-1-u3-X04']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C4","difficulty":1,"kind":"ox","stem":"탄산 칼슘은 물에 넣고 흔들어도 녹지 않아요.","answer":"O","reason_options":[{"t":"흔든 뒤 5분 정도 지나도 녹지 않고 그대로 남았기 때문에","correct":true},{"t":"물에 넣은 물질은 무엇이든 다 녹기 때문에","mis":"SC5-1-u3-X04"}],"mis":"SC5-1-u3-X04","explanation":["세 물질 실험을 떠올려요.","탄산 칼슘은 남았어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#4','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C4',1,'mc','auto','물에 넣고 섞었을 때 녹는 물질은 어느 것인가요?',ARRAY['SC5-1-u3-X04']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C4","difficulty":1,"kind":"mc","stem":"물에 넣고 섞었을 때 녹는 물질은 어느 것인가요?","options":[{"t":"설탕","correct":true},{"t":"탄산 칼슘","mis":"SC5-1-u3-X04"},{"t":"후춧가루","mis":"SC5-1-u3-X04"},{"t":"흙","mis":"SC5-1-u3-X04"}],"explanation":["설탕물을 떠올려요.","보이지 않게 돼요.","설탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#5','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C5',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C5","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"용해","r":"녹아 골고루 섞이는 현상"},{"l":"용매","r":"다른 물질을 녹이는 물질"},{"l":"용질","r":"용매에 녹는 물질"},{"l":"용액","r":"용매와 용질이 골고루 섞여 있는 물질"}],"mis":"SC5-1-u3-X06","explanation":["하나는 현상이에요.","녹이는 쪽과 녹는 쪽이 있어요.","섞인 물질이 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#6','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C6',2,'mc','auto','다음 가운데 용액인 것은 어느 것인가요?',ARRAY['SC5-1-u3-X08']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C6","difficulty":2,"kind":"mc","stem":"다음 가운데 용액인 것은 어느 것인가요?","options":[{"t":"설탕물","correct":true},{"t":"흙탕물","mis":"SC5-1-u3-X08"},{"t":"후춧가루를 넣은 물","mis":"SC5-1-u3-X08"},{"t":"탄산 칼슘을 넣고 흔든 물","mis":"SC5-1-u3-X08"}],"explanation":["녹아 골고루 섞였나요?","가라앉는 것이 없어요.","설탕물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#7','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C7',2,'mc','auto','세 물질을 물에 넣어 보는 실험에서 지켜야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X10','SC5-1-u3-X03']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C7","difficulty":2,"kind":"mc","stem":"세 물질을 물에 넣어 보는 실험에서 지켜야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"약숟가락에 담는 물질의 양을 최대한 같게 한다","correct":true},{"t":"세 물질을 약숟가락 하나로 번갈아 뜬다","mis":"SC5-1-u3-X10"},{"t":"흔들자마자 바로 관찰한다","mis":"SC5-1-u3-X10"},{"t":"어떤 물질인지 맛을 보아 확인한다","mis":"SC5-1-u3-X03"}],"explanation":["공정하게 견줘요.","양을 같게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#8','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C5',2,'blank','auto','「설탕물에서 물처럼 다른 물질을 녹이는 물질을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X07','SC5-1-u3-X06']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C5","difficulty":2,"kind":"blank","stem":"「설탕물에서 물처럼 다른 물질을 녹이는 물질을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"용매","correct":true},{"t":"용질","mis":"SC5-1-u3-X07"},{"t":"용액","mis":"SC5-1-u3-X06"},{"t":"용해","mis":"SC5-1-u3-X06"}],"explanation":["녹이는 쪽이에요.","물이에요.","용매예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#9','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C6',2,'error','auto','용액인 것과 아닌 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X08','SC5-1-u3-X09']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C6","difficulty":2,"kind":"error","stem":"용액인 것과 아닌 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「흙탕물도 흙과 물이 섞여 있으니까 용액이야.」","correct":true,"mis_target":"SC5-1-u3-X08"},{"t":"나은 — 「설탕물은 어느 부분이나 맛이 같아.」","mis":"SC5-1-u3-X09"},{"t":"도현 — 「용액에는 뜨거나 가라앉는 것이 없어.」","mis":"SC5-1-u3-X09"}],"explanation":["흙은 녹았나요?","흙은 가라앉아요.","준서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_basic#10','sci',5,1,'u3','L02','g5_1_sci_u3_L02_basic','lesson_basic','SC5-1-u3-C6',3,'mc','auto','비가 온 뒤 고인 흙탕물이 용액이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X08','SC5-1-u3-X09']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C6","difficulty":3,"kind":"mc","stem":"비가 온 뒤 고인 흙탕물이 용액이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"흙이 녹지 않고 가라앉기 때문에","correct":true},{"t":"흙과 물이 섞여 있기 때문에","mis":"SC5-1-u3-X08"},{"t":"맛이 나지 않기 때문에","mis":"SC5-1-u3-X09"},{"t":"색깔이 있기 때문에","mis":"SC5-1-u3-X09"}],"explanation":["오래 두면 어떻게 되나요?","흙이 가라앉아요.","녹지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#1','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C7',2,'mc','auto','세 물질을 물에 넣어 보는 실험의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X10']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C7","difficulty":2,"kind":"mc","stem":"세 물질을 물에 넣어 보는 실험의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉣ → ㉠","correct":true},{"t":"㉢ → ㉡ → ㉠ → ㉣","mis":"SC5-1-u3-X10"},{"t":"㉡ → ㉣ → ㉢ → ㉠","mis":"SC5-1-u3-X10"},{"t":"㉣ → ㉢ → ㉡ → ㉠","mis":"SC5-1-u3-X10"}],"explanation":["예상이 먼저예요.","물을 넣고 물질을 넣어요.","흔들고 기다려 관찰해요."],"asset":{"type":"passage","lines":["㉠ 뚜껑을 닫고 흔든 뒤 평평한 곳에 두고 5분 정도 지나 관찰한다.","㉡ 세 물질을 물에 넣으면 어떻게 될지 예상한다.","㉢ 유리병 세 개에 물을 같은 양씩 넣는다.","㉣ 설탕, 가루 바이타민, 탄산 칼슘을 한 숟가락씩 넣는다."],"title":"세 물질 넣어 보기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#2','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C5',2,'sa','auto','「용매와 용질이 골고루 섞여 있는 물질을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C5","difficulty":2,"kind":"sa","stem":"「용매와 용질이 골고루 섞여 있는 물질을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["용액"],"explanation":["섞여 있는 물질이에요.","설탕물 같은 것이에요.","용액이에요."],"mis":"SC5-1-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#3','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C5',3,'mc','auto','소금물에서 용매와 용질을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X07','SC5-1-u3-X06']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C5","difficulty":3,"kind":"mc","stem":"소금물에서 용매와 용질을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"용매 — 물, 용질 — 소금","correct":true},{"t":"용매 — 소금, 용질 — 물","mis":"SC5-1-u3-X07"},{"t":"용매 — 소금물, 용질 — 소금","mis":"SC5-1-u3-X06"},{"t":"용매 — 물, 용질 — 소금물","mis":"SC5-1-u3-X06"}],"explanation":["녹이는 것은 무엇인가요?","물이 소금을 녹여요.","용매는 물, 용질은 소금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#4','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C4',3,'ox','auto','후춧가루를 넣은 물을 아주 오래 저으면 후춧가루도 모두 녹아요.',ARRAY['SC5-1-u3-X05']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C4","difficulty":3,"kind":"ox","stem":"후춧가루를 넣은 물을 아주 오래 저으면 후춧가루도 모두 녹아요.","answer":"X","reason_options":[{"t":"후춧가루는 물에 녹지 않는 물질이어서 저어도 그대로 떠다니기 때문에","correct":true},{"t":"녹지 않는 것은 모두 덜 저었기 때문이므로 오래 저으면 녹기 때문에","mis":"SC5-1-u3-X05"}],"mis":"SC5-1-u3-X05","explanation":["후춧가루를 넣은 물을 떠올려요.","저어도 떠다녀요.","녹지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#5','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C6',3,'mc','auto','용액의 성질로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X09','SC5-1-u3-X08']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C6","difficulty":3,"kind":"mc","stem":"용액의 성질로 알맞은 것은 어느 것인가요?","options":[{"t":"색깔이나 맛 등의 성질이 어느 부분이나 일정하다","correct":true},{"t":"아래쪽으로 갈수록 더 달다","mis":"SC5-1-u3-X09"},{"t":"시간이 지나면 녹은 물질이 바닥에 가라앉는다","mis":"SC5-1-u3-X09"},{"t":"섞여 있기만 하면 가라앉는 것이 있어도 된다","mis":"SC5-1-u3-X08"}],"explanation":["설탕물을 떠올려요.","어디나 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#6','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C4',3,'mc','auto','5분 뒤 관찰 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X04','SC5-1-u3-X05','SC5-1-u3-X11']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C4","difficulty":3,"kind":"mc","stem":"5분 뒤 관찰 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"어떤 물질은 물에 녹고, 어떤 물질은 녹지 않는다","correct":true},{"t":"물에 넣은 물질은 모두 녹는다","mis":"SC5-1-u3-X04"},{"t":"탄산 칼슘은 물이 부족해서 녹지 않았다","mis":"SC5-1-u3-X05"},{"t":"보이지 않게 된 물질은 물속에서 없어졌다","mis":"SC5-1-u3-X11"}],"explanation":["세 물질을 견줘요.","탄산 칼슘은 가라앉았어요.","녹는 것과 녹지 않는 것이 있어요."],"asset":{"type":"passage","lines":["설탕 — 보이지 않게 되었다.","가루 바이타민 — 보이지 않게 되었다.","탄산 칼슘 — 뿌옇게 흐려졌다가 바닥에 가라앉았다."],"title":"5분 뒤 관찰 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#7','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C7',3,'error','auto','세 물질 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X10','SC5-1-u3-X03']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C7","difficulty":3,"kind":"error","stem":"세 물질 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「약숟가락 하나로 세 물질을 번갈아 뜨자.」","correct":true,"mis_target":"SC5-1-u3-X10"},{"t":"채원 — 「물이 튀지 않도록 살살 넣자.」","mis":"SC5-1-u3-X03"},{"t":"시우 — 「유리병마다 이름 붙임딱지를 붙이자.」","mis":"SC5-1-u3-X10"}],"explanation":["물질이 섞이면 어떨까요?","약숟가락을 구분해요.","윤호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#8','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C6',4,'mc','auto','투명한 유리병 두 개를 관찰했어요. 용액인 것과 그 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u3-X08','SC5-1-u3-X09']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C6","difficulty":4,"kind":"mc","stem":"투명한 유리병 두 개를 관찰했어요. 용액인 것과 그 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"㉮ — 뜨거나 가라앉는 것 없이 골고루 섞여 있기 때문에","correct":true},{"t":"㉯ — 두 물질이 섞여 있기 때문에","mis":"SC5-1-u3-X08"},{"t":"㉮ — 색깔이 있는 것은 용액이 아니기 때문에","mis":"SC5-1-u3-X09"},{"t":"㉮와 ㉯ 모두 — 물에 무엇인가를 넣었기 때문에","mis":"SC5-1-u3-X08"}],"explanation":["용액의 성질을 떠올려요.","가라앉는 것이 있나요?","㉮가 용액이에요."],"asset":{"type":"passage","lines":["㉮ — 오래 두어도 뜨거나 가라앉는 것 없이 어느 부분이나 색깔이 같다.","㉯ — 저으면 뿌옇다가 시간이 지나면 바닥에 가라앉는 것이 생긴다."],"title":"투명한 유리병 두 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#9','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C4',4,'mc','auto','「물에 넣으면 어떤 가루든 다 녹을 것이다.」라고 예상했는데 탄산 칼슘이 녹지 않았어요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC5-1-u3-X14','SC5-1-u3-X05','SC5-1-u3-X04']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C4","difficulty":4,"kind":"mc","stem":"「물에 넣으면 어떤 가루든 다 녹을 것이다.」라고 예상했는데 탄산 칼슘이 녹지 않았어요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"결과를 사실대로 기록하고 예상과 견주어 본다","correct":true},{"t":"예상에 맞게 「탄산 칼슘도 녹았다」고 고쳐 적는다","mis":"SC5-1-u3-X14"},{"t":"탄산 칼슘을 더 흔들면 녹으니 녹았다고 적는다","mis":"SC5-1-u3-X05"},{"t":"탄산 칼슘은 물에 녹는 물질이라고 적는다","mis":"SC5-1-u3-X04"}],"explanation":["예상은 틀릴 수 있어요.","결과는 고치지 않아요.","사실대로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L02_challenge#10','sci',5,1,'u3','L02','g5_1_sci_u3_L02_challenge','lesson_challenge','SC5-1-u3-C5',4,'essay','teacher','설탕물을 예로 들어 용해, 용매, 용질, 용액의 뜻을 설명하고, 흙탕물이 용액이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C5","difficulty":4,"kind":"essay","stem":"설탕물을 예로 들어 용해, 용매, 용질, 용액의 뜻을 설명하고, 흙탕물이 용액이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 설탕이 물에 녹아 골고루 섞이는 현상을 용해라고 한다. 이때 설탕을 녹이는 물은 용매, 물에 녹는 설탕은 용질이고, 물과 설탕이 골고루 섞여 있는 설탕물은 용액이다. 흙탕물은 흙이 물에 녹지 않고 가라앉기 때문에 용액이 아니다.","scoring_points":["용해를 현상으로 설명했는가","용매·용질·용액을 설탕물로 바르게 짝지었는가","흙탕물이 가라앉는 것이 있어 용액이 아니라고 썼는가"]},"explanation":["설탕물에서 찾아요.","녹이는 것과 녹는 것이에요.","흙탕물은 가라앉아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#1','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C9',1,'mc','auto','각설탕이 물에 용해되기 전과 용해된 후의 무게는 어떠한가요?',ARRAY['SC5-1-u3-X12']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C9","difficulty":1,"kind":"mc","stem":"각설탕이 물에 용해되기 전과 용해된 후의 무게는 어떠한가요?","options":[{"t":"같다","correct":true},{"t":"용해된 후가 더 가볍다","mis":"SC5-1-u3-X12"},{"t":"용해된 후가 더 무겁다","mis":"SC5-1-u3-X12"},{"t":"잴 때마다 달라진다","mis":"SC5-1-u3-X12"}],"explanation":["저울 눈금을 떠올려요.","눈금이 그대로였어요.","같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#2','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C8',1,'mc','auto','각설탕을 물에 넣으면 어떻게 되나요?',ARRAY['SC5-1-u3-X13','SC5-1-u3-X11']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C8","difficulty":1,"kind":"mc","stem":"각설탕을 물에 넣으면 어떻게 되나요?","options":[{"t":"크기가 점점 작아지며 물에 녹는다","correct":true},{"t":"크기가 그대로인 채 가라앉는다","mis":"SC5-1-u3-X13"},{"t":"크기가 점점 커지며 떠오른다","mis":"SC5-1-u3-X13"},{"t":"곧바로 물로 변해 없어진다","mis":"SC5-1-u3-X11"}],"explanation":["녹는 모습을 떠올려요.","점점 작아져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#3','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C11',1,'sa','auto','「무게를 잴 때 쓰는 기구는 전자□□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C11","difficulty":1,"kind":"sa","stem":"「무게를 잴 때 쓰는 기구는 전자□□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["저울"],"explanation":["눈금이 나와요.","두 글자예요.","전자저울이에요."],"mis":"SC5-1-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#4','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C10',1,'ox','auto','각설탕이 다 녹아 보이지 않아도 설탕은 설탕물 속에 그대로 있어요.',ARRAY['SC5-1-u3-X11']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C10","difficulty":1,"kind":"ox","stem":"각설탕이 다 녹아 보이지 않아도 설탕은 설탕물 속에 그대로 있어요.","answer":"O","reason_options":[{"t":"설탕물에서 단맛이 나고 무게도 그대로이기 때문에","correct":true},{"t":"눈에 보이지 않으면 없어진 것이기 때문에","mis":"SC5-1-u3-X11"}],"mis":"SC5-1-u3-X11","explanation":["설탕물의 맛을 떠올려요.","단맛이 나요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#5','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C11',2,'mc','auto','용해되기 전의 무게를 잴 때 전자저울에 함께 올려놓는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X14']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C11","difficulty":2,"kind":"mc","stem":"용해되기 전의 무게를 잴 때 전자저울에 함께 올려놓는 것은 어느 것인가요?","options":[{"t":"물이 든 유리병과 각설탕 한 개를 담은 페트리 접시","correct":true},{"t":"물이 든 유리병만","mis":"SC5-1-u3-X14"},{"t":"각설탕 한 개만","mis":"SC5-1-u3-X14"},{"t":"빈 유리병과 빈 페트리 접시","mis":"SC5-1-u3-X14"}],"explanation":["모두 함께 올려요.","물과 각설탕이 다 있어야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#6','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C11',2,'mc','auto','각설탕이 모두 용해된 뒤 무게를 잴 때 전자저울에 함께 올려놓는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X14']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C11","difficulty":2,"kind":"mc","stem":"각설탕이 모두 용해된 뒤 무게를 잴 때 전자저울에 함께 올려놓는 것은 어느 것인가요?","options":[{"t":"설탕물이 담긴 유리병과 빈 페트리 접시","correct":true},{"t":"설탕물이 담긴 유리병만","mis":"SC5-1-u3-X14"},{"t":"빈 페트리 접시만","mis":"SC5-1-u3-X14"},{"t":"설탕물이 담긴 유리병과 각설탕을 하나 더 담은 접시","mis":"SC5-1-u3-X14"}],"explanation":["처음과 같은 것을 올려요.","접시도 함께예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#7','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C10',2,'blank','auto','「완전히 용해된 용질은 사라진 것이 아니라 (    ) 속에 그대로 있습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X14']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C10","difficulty":2,"kind":"blank","stem":"「완전히 용해된 용질은 사라진 것이 아니라 (    ) 속에 그대로 있습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"용액","correct":true},{"t":"공기","mis":"SC5-1-u3-X11"},{"t":"저울","mis":"SC5-1-u3-X14"},{"t":"페트리 접시","mis":"SC5-1-u3-X14"}],"explanation":["설탕은 어디에 있을까요?","설탕물 속이에요.","용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#8','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C11',2,'match','auto','무게 비교 실험의 준비물과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SC5-1-u3-C11","difficulty":2,"kind":"match","stem":"무게 비교 실험의 준비물과 하는 일을 알맞게 이으세요.","pairs":[{"l":"핀셋","r":"각설탕을 집어 넣는다"},{"l":"페트리 접시","r":"각설탕을 담아 둔다"},{"l":"전자저울","r":"무게를 잰다"},{"l":"유리병","r":"물을 절반 정도 담는다"}],"mis":"SC5-1-u3-X14","explanation":["하나씩 떠올려요.","집고, 담고, 재요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#9','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C9',2,'sa','auto','용해되기 전에 함께 잰 무게가 128 g이었어요. 각설탕이 모두 용해된 뒤 같은 것들을 함께 재면 몇 g일까요?','{}'::text[],false,'{"seq":9,"concept":"SC5-1-u3-C9","difficulty":2,"kind":"sa","stem":"용해되기 전에 함께 잰 무게가 128 g이었어요. 각설탕이 모두 용해된 뒤 같은 것들을 함께 재면 몇 g일까요?","answer":["128","128 g","128g"],"explanation":["무게가 변할까요?","용해 전과 후는 같아요.","128 g이에요."],"mis":"SC5-1-u3-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_basic#10','sci',5,1,'u3','L03','g5_1_sci_u3_L03_basic','lesson_basic','SC5-1-u3-C8',3,'mc','auto','각설탕이 용해되는 과정을 차례대로 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u3-X13','SC5-1-u3-X12']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C8","difficulty":3,"kind":"mc","stem":"각설탕이 용해되는 과정을 차례대로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"크기가 작아짐 → 보이지 않을 만큼 작아짐 → 물에 골고루 섞여 용액이 됨","correct":true},{"t":"물에 골고루 섞임 → 크기가 작아짐 → 보이지 않게 됨","mis":"SC5-1-u3-X13"},{"t":"크기 그대로 가라앉음 → 물로 변함 → 사라짐","mis":"SC5-1-u3-X13"},{"t":"보이지 않게 됨 → 사라짐 → 무게가 줄어듦","mis":"SC5-1-u3-X12"}],"explanation":["녹는 모습을 떠올려요.","작아지고, 안 보이고, 섞여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#1','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C11',2,'mc','auto','무게 비교 실험의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X14']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C11","difficulty":2,"kind":"mc","stem":"무게 비교 실험의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉣ → ㉤ → ㉠","correct":true},{"t":"㉢ → ㉤ → ㉣ → ㉡ → ㉠","mis":"SC5-1-u3-X14"},{"t":"㉡ → ㉢ → ㉤ → ㉣ → ㉠","mis":"SC5-1-u3-X14"},{"t":"㉡ → ㉣ → ㉢ → ㉠ → ㉤","mis":"SC5-1-u3-X14"}],"explanation":["예상이 먼저예요.","넣기 전에 먼저 재요.","녹은 뒤에 다시 재요."],"asset":{"type":"passage","lines":["㉠ 다 용해되면 설탕물 유리병과 빈 페트리 접시를 함께 올려 잰다.","㉡ 용해되기 전과 후의 무게가 어떠할지 예상한다.","㉢ 유리병에 물을 절반 정도 넣고 뚜껑을 닫는다.","㉣ 물이 든 유리병과 각설탕을 담은 페트리 접시를 함께 올려 잰다.","㉤ 핀셋으로 각설탕을 넣고 용해되는 모습을 관찰한다."],"title":"무게 비교 실험(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#2','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C9',2,'ox','auto','각설탕이 모두 용해되면 저울에 함께 올린 유리병과 접시의 무게가 처음보다 줄어들어요.',ARRAY['SC5-1-u3-X12']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C9","difficulty":2,"kind":"ox","stem":"각설탕이 모두 용해되면 저울에 함께 올린 유리병과 접시의 무게가 처음보다 줄어들어요.","answer":"X","reason_options":[{"t":"용해된 설탕이 용액 속에 그대로 있어 무게가 같기 때문에","correct":true},{"t":"녹은 설탕은 사라져 무게가 줄어들기 때문에","mis":"SC5-1-u3-X12"}],"mis":"SC5-1-u3-X12","explanation":["저울 눈금을 떠올려요.","그대로였어요.","줄어들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#3','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C9',3,'mc','auto','우리 모둠 저울 기록에서 각설탕이 모두 용해된 뒤 설탕물 유리병만의 무게는 몇 g일까요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X14','SC5-1-u3-X12']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C9","difficulty":3,"kind":"mc","stem":"우리 모둠 저울 기록에서 각설탕이 모두 용해된 뒤 설탕물 유리병만의 무게는 몇 g일까요?","options":[{"t":"123 g","correct":true},{"t":"120 g","mis":"SC5-1-u3-X11"},{"t":"128 g","mis":"SC5-1-u3-X14"},{"t":"131 g","mis":"SC5-1-u3-X12"}],"explanation":["함께 잰 무게는 그대로 128 g이에요.","빈 접시 5 g을 빼요.","123 g이에요."],"asset":{"type":"passage","lines":["물이 든 유리병 — 120 g","각설탕 한 개를 담은 페트리 접시 — 8 g (빈 접시만 5 g)","용해되기 전 함께 잰 무게 — 128 g","각설탕이 모두 용해된 뒤 설탕물 유리병과 빈 접시를 함께 잼"],"title":"우리 모둠 저울 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#4','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C10',3,'mc','auto','용해되기 전과 후의 무게가 같은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X12','SC5-1-u3-X14']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C10","difficulty":3,"kind":"mc","stem":"용해되기 전과 후의 무게가 같은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"용해된 용질이 용액 속에 그대로 있기 때문에","correct":true},{"t":"설탕이 녹아 없어진 만큼 물이 늘어나기 때문에","mis":"SC5-1-u3-X11"},{"t":"눈에 보이지 않는 것은 무게가 없기 때문에","mis":"SC5-1-u3-X12"},{"t":"녹는 동안 저울이 멈추기 때문에","mis":"SC5-1-u3-X14"}],"explanation":["설탕은 어디로 갔을까요?","용액 속에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#5','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C11',3,'error','auto','무게 비교 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X14','SC5-1-u3-X03']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C11","difficulty":3,"kind":"error","stem":"무게 비교 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「예상과 다르게 나왔으니 결과를 예상에 맞게 고쳐 적자.」","correct":true,"mis_target":"SC5-1-u3-X14"},{"t":"건우 — 「핀셋으로 각설탕을 넣자.」","mis":"SC5-1-u3-X14"},{"t":"하율 — 「물이 튀지 않도록 살살 넣자.」","mis":"SC5-1-u3-X03"}],"explanation":["결과는 어떻게 적나요?","사실대로 적어요.","서윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#6','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C9',3,'mc','auto','같은 양의 물에 분말주스를 한 숟가락 녹인 용액과 열 숟가락 녹인 용액 가운데 더 무거운 것은 어느 것인가요?',ARRAY['SC5-1-u3-X15','SC5-1-u3-X11']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C9","difficulty":3,"kind":"mc","stem":"같은 양의 물에 분말주스를 한 숟가락 녹인 용액과 열 숟가락 녹인 용액 가운데 더 무거운 것은 어느 것인가요?","options":[{"t":"열 숟가락을 녹인 용액","correct":true},{"t":"한 숟가락을 녹인 용액","mis":"SC5-1-u3-X15"},{"t":"물의 양이 같으므로 두 용액의 무게가 같다","mis":"SC5-1-u3-X15"},{"t":"녹으면 없어지므로 둘 다 물의 무게와 같다","mis":"SC5-1-u3-X11"}],"explanation":["녹인 용질은 어디 있나요?","용액 속에 그대로 있어요.","많이 녹일수록 무거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#7','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C8',3,'mc','auto','솜사탕을 물에 넣었더니 금방 보이지 않게 되었어요. 알맞은 설명은 어느 것인가요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X13']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C8","difficulty":3,"kind":"mc","stem":"솜사탕을 물에 넣었더니 금방 보이지 않게 되었어요. 알맞은 설명은 어느 것인가요?","options":[{"t":"솜사탕이 아주 작게 녹아 물에 골고루 섞여 있다","correct":true},{"t":"솜사탕이 물속에서 사라졌다","mis":"SC5-1-u3-X11"},{"t":"솜사탕이 모두 물로 변했다","mis":"SC5-1-u3-X13"},{"t":"솜사탕이 크기 그대로 바닥에 숨어 있다","mis":"SC5-1-u3-X13"}],"explanation":["각설탕을 떠올려요.","작아져 섞여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#8','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C10',4,'mc','auto','「설탕물 속에 설탕이 그대로 있다는 증거를 대 봐.」라는 친구에게 들 수 있는 증거로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X12','SC5-1-u3-X13']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C10","difficulty":4,"kind":"mc","stem":"「설탕물 속에 설탕이 그대로 있다는 증거를 대 봐.」라는 친구에게 들 수 있는 증거로 알맞은 것은 어느 것인가요?","options":[{"t":"용해되기 전과 후의 무게가 같고, 설탕물에서 단맛이 난다","correct":true},{"t":"설탕물이 투명하게 보인다","mis":"SC5-1-u3-X11"},{"t":"용해된 뒤 저울 눈금이 줄었다","mis":"SC5-1-u3-X12"},{"t":"각설탕이 바닥에 크기 그대로 보인다","mis":"SC5-1-u3-X13"}],"explanation":["무게와 맛을 떠올려요.","두 가지 증거예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#9','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C9',4,'mc','auto','같은 양의 물(100 g)이 든 유리병 ㉮에 각설탕 2개, ㉯에 각설탕 5개를 넣어 모두 녹였어요. 각설탕 한 개가 3 g일 때 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X15','SC5-1-u3-X11']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C9","difficulty":4,"kind":"mc","stem":"같은 양의 물(100 g)이 든 유리병 ㉮에 각설탕 2개, ㉯에 각설탕 5개를 넣어 모두 녹였어요. 각설탕 한 개가 3 g일 때 알맞은 것은 어느 것인가요?","options":[{"t":"㉯ 용액이 ㉮ 용액보다 9 g 더 무겁다","correct":true},{"t":"두 용액의 무게는 같다","mis":"SC5-1-u3-X15"},{"t":"두 용액 모두 100 g이다","mis":"SC5-1-u3-X11"},{"t":"㉮ 용액이 ㉯ 용액보다 더 무겁다","mis":"SC5-1-u3-X15"}],"explanation":["㉮는 106 g이에요.","㉯는 115 g이에요.","9 g 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L03_challenge#10','sci',5,1,'u3','L03','g5_1_sci_u3_L03_challenge','lesson_challenge','SC5-1-u3-C10',4,'essay','teacher','각설탕이 용해되기 전과 후의 무게를 비교한 결과와 그 까닭을 쓰고, 「녹아서 안 보이면 설탕은 없어진 거야.」라고 말한 친구의 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C10","difficulty":4,"kind":"essay","stem":"각설탕이 용해되기 전과 후의 무게를 비교한 결과와 그 까닭을 쓰고, 「녹아서 안 보이면 설탕은 없어진 거야.」라고 말한 친구의 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: 각설탕이 용해되기 전과 용해된 후의 무게는 같았다. 각설탕은 크기가 점점 작아져 눈에 보이지 않을 정도로 작아진 다음 물에 골고루 섞였을 뿐, 사라진 것이 아니라 용액 속에 그대로 있기 때문이다. 그래서 친구에게 설탕물에서 단맛이 나고 무게도 그대로이니 설탕은 없어진 것이 아니라고 말해 준다.","scoring_points":["무게가 같다고 썼는가","용액 속에 그대로 있다는 까닭을 썼는가","단맛이나 무게를 근거로 바로잡았는가"]},"explanation":["결과부터 써요.","까닭을 이어요.","근거를 들어 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#1','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C12',1,'mc','auto','물의 온도와 양이 같을 때, 용질이 물에 용해되는 양은 용질의 종류에 따라 어떠한가요?',ARRAY['SC5-1-u3-X16']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C12","difficulty":1,"kind":"mc","stem":"물의 온도와 양이 같을 때, 용질이 물에 용해되는 양은 용질의 종류에 따라 어떠한가요?","options":[{"t":"다르다","correct":true},{"t":"언제나 같다","mis":"SC5-1-u3-X16"},{"t":"알 수 없다","mis":"SC5-1-u3-X16"},{"t":"넣는 순서에 따라서만 달라진다","mis":"SC5-1-u3-X16"}],"explanation":["세 비커를 떠올려요.","남은 것이 달랐어요.","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#2','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C14',1,'mc','auto','물 50 mL를 정확히 재려면 무엇을 쓰나요?',ARRAY['SC5-1-u3-X19']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C14","difficulty":1,"kind":"mc","stem":"물 50 mL를 정확히 재려면 무엇을 쓰나요?","options":[{"t":"눈금실린더","correct":true},{"t":"약숟가락","mis":"SC5-1-u3-X19"},{"t":"유리 막대","mis":"SC5-1-u3-X19"},{"t":"이름 붙임딱지","mis":"SC5-1-u3-X19"}],"explanation":["눈금이 있어요.","물의 양을 재요.","눈금실린더예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#3','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C12',1,'sa','auto','「같은 온도, 같은 양의 물에 설탕, 소금, 백반을 넣었을 때 가장 적게 용해된 용질은 □□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C12","difficulty":1,"kind":"sa","stem":"「같은 온도, 같은 양의 물에 설탕, 소금, 백반을 넣었을 때 가장 적게 용해된 용질은 □□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["백반"],"explanation":["가장 먼저 바닥에 남았어요.","두 글자예요.","백반이에요."],"mis":"SC5-1-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#4','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C14',1,'ox','auto','백반이 피부에 닿지 않도록 조심해요.',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C14","difficulty":1,"kind":"ox","stem":"백반이 피부에 닿지 않도록 조심해요.","answer":"O","reason_options":[{"t":"실험에 쓰는 물질은 몸에 닿거나 먹으면 해로울 수 있기 때문에","correct":true},{"t":"백반은 손에 닿으면 바로 사라지기 때문에","mis":"SC5-1-u3-X03"}],"mis":"SC5-1-u3-X03","explanation":["안전을 떠올려요.","피부를 지켜요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#5','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C14',2,'match','auto','용질의 종류 실험의 준비물과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C14","difficulty":2,"kind":"match","stem":"용질의 종류 실험의 준비물과 하는 일을 알맞게 이으세요.","pairs":[{"l":"눈금실린더","r":"물의 양을 정확히 잰다"},{"l":"유리 막대","r":"충분히 저어 준다"},{"l":"약숟가락","r":"용질을 한 숟가락씩 넣는다"},{"l":"이름 붙임딱지","r":"비커에 용질 이름을 표시한다"}],"mis":"SC5-1-u3-X19","explanation":["하나씩 떠올려요.","재고, 젓고, 넣고, 표시해요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#6','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C13',2,'mc','auto','세 용질을 공정하게 비교할 때 다르게 하는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X18']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C13","difficulty":2,"kind":"mc","stem":"세 용질을 공정하게 비교할 때 다르게 하는 것은 어느 것인가요?","options":[{"t":"용질의 종류","correct":true},{"t":"물의 양","mis":"SC5-1-u3-X18"},{"t":"물의 온도","mis":"SC5-1-u3-X18"},{"t":"약숟가락에 담는 양","mis":"SC5-1-u3-X18"}],"explanation":["무엇을 알아보나요?","용질마다 견줘요.","용질의 종류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#7','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C12',2,'mc','auto','같은 온도, 같은 양의 물에 세 용질을 넣은 결과로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X16']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C12","difficulty":2,"kind":"mc","stem":"같은 온도, 같은 양의 물에 세 용질을 넣은 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"설탕은 모두 용해되고 소금은 일부가 바닥에 남았다","correct":true},{"t":"세 용질이 모두 똑같이 녹았다","mis":"SC5-1-u3-X16"},{"t":"백반이 가장 많이 녹았다","mis":"SC5-1-u3-X16"},{"t":"소금이 설탕보다 더 많이 녹았다","mis":"SC5-1-u3-X16"}],"explanation":["설탕부터 떠올려요.","소금은 남았어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#8','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C14',2,'blank','auto','「용질이 용해되지 않고 바닥에 남으면 (    ).」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X20','SC5-1-u3-X03']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C14","difficulty":2,"kind":"blank","stem":"「용질이 용해되지 않고 바닥에 남으면 (    ).」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"용질을 더 넣지 않는다","correct":true},{"t":"용질을 계속 더 넣는다","mis":"SC5-1-u3-X20"},{"t":"맛을 보아 확인한다","mis":"SC5-1-u3-X03"},{"t":"모두 녹았다고 적는다","mis":"SC5-1-u3-X20"}],"explanation":["남았다는 것은?","그만 넣어요.","더 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#9','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C13',2,'error','auto','공정하게 비교하려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X18']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C13","difficulty":2,"kind":"error","stem":"공정하게 비교하려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「설탕 비커에는 물을 더 많이 넣자.」","correct":true,"mis_target":"SC5-1-u3-X18"},{"t":"로운 — 「세 비커의 물을 50 mL로 똑같이 하자.」","mis":"SC5-1-u3-X18"},{"t":"다인 — 「약숟가락에 담는 양을 최대한 같게 하자.」","mis":"SC5-1-u3-X18"}],"explanation":["물의 양은 같아야 해요.","하나만 달라야 해요.","지안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_basic#10','sci',5,1,'u3','L04','g5_1_sci_u3_L04_basic','lesson_basic','SC5-1-u3-C12',3,'mc','auto','같은 조건에서 설탕은 다 녹았는데 소금이 바닥에 남았어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X17']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C12","difficulty":3,"kind":"mc","stem":"같은 조건에서 설탕은 다 녹았는데 소금이 바닥에 남았어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 양의 물에 녹는 양이 용질마다 다르기 때문에","correct":true},{"t":"설탕보다 소금을 적게 넣었기 때문에","mis":"SC5-1-u3-X17"},{"t":"조금 더 저었다면 남김없이 다 녹았기 때문에","mis":"SC5-1-u3-X17"},{"t":"실험을 잘못했기 때문에","mis":"SC5-1-u3-X17"}],"explanation":["조건은 같았어요.","용질만 달랐어요.","용질마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#1','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C14',2,'mc','auto','용질의 종류에 따라 용해되는 양을 비교하는 실험의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X19']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C14","difficulty":2,"kind":"mc","stem":"용질의 종류에 따라 용해되는 양을 비교하는 실험의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉣ → ㉠","correct":true},{"t":"㉢ → ㉡ → ㉠ → ㉣","mis":"SC5-1-u3-X19"},{"t":"㉡ → ㉣ → ㉢ → ㉠","mis":"SC5-1-u3-X19"},{"t":"㉣ → ㉢ → ㉡ → ㉠","mis":"SC5-1-u3-X19"}],"explanation":["예상이 먼저예요.","물을 재어 넣어요.","넣고 젓기를 되풀이해요."],"asset":{"type":"passage","lines":["㉠ 한 숟가락씩 넣고 젓기를 되풀이하며 용해되는 양을 비교한다.","㉡ 세 용질이 용해되는 양을 예상한다.","㉢ 눈금실린더로 비커 세 개에 상온의 물을 50 mL씩 넣는다.","㉣ 설탕, 소금, 백반을 한 숟가락씩 넣고 유리 막대로 충분히 저으며 관찰한다."],"title":"용질의 종류 실험(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#2','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C12',2,'sa','auto','우리 모둠 용질 비교 기록에서 소금은 몇 숟가락까지 모두 용해되었는지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C12","difficulty":2,"kind":"sa","stem":"우리 모둠 용질 비교 기록에서 소금은 몇 숟가락까지 모두 용해되었는지 쓰세요.","answer":["5","5숟가락","5 숟가락","다섯 숟가락","다섯"],"explanation":["여섯째부터 남았어요.","그 앞까지예요.","다섯 숟가락이에요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 여섯째 숟가락부터 바닥에 남았다.","백반 — 둘째 숟가락부터 바닥에 남았다."],"title":"우리 모둠 용질 비교 기록"},"mis":"SC5-1-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#3','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C12',3,'mc','auto','우리 모둠 기록에서 용해된 양이 많은 것부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['SC5-1-u3-X16']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C12","difficulty":3,"kind":"mc","stem":"우리 모둠 기록에서 용해된 양이 많은 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"설탕 > 소금 > 백반","correct":true},{"t":"백반 > 소금 > 설탕","mis":"SC5-1-u3-X16"},{"t":"소금 > 설탕 > 백반","mis":"SC5-1-u3-X16"},{"t":"설탕 = 소금 = 백반","mis":"SC5-1-u3-X16"}],"explanation":["늦게 남을수록 많이 녹았어요.","백반이 가장 먼저 남았어요.","설탕 > 소금 > 백반이에요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 여섯째 숟가락부터 바닥에 남았다.","백반 — 둘째 숟가락부터 바닥에 남았다."],"title":"우리 모둠 용질 비교 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#4','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C13',3,'mc','auto','세 용질을 공정하게 비교하려고 같게 해야 할 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X18']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C13","difficulty":3,"kind":"mc","stem":"세 용질을 공정하게 비교하려고 같게 해야 할 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"물의 온도, 물의 양, 약숟가락에 담는 양","correct":true},{"t":"용질의 종류, 물의 양","mis":"SC5-1-u3-X18"},{"t":"이름 붙임딱지의 색깔, 비커의 모양","mis":"SC5-1-u3-X18"},{"t":"용질의 종류만","mis":"SC5-1-u3-X18"}],"explanation":["다르게 할 것은 하나예요.","나머지는 같게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#5','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C12',3,'ox','auto','소금이 바닥에 남았으니 우리 모둠 실험은 잘못된 거예요.',ARRAY['SC5-1-u3-X17']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C12","difficulty":3,"kind":"ox","stem":"소금이 바닥에 남았으니 우리 모둠 실험은 잘못된 거예요.","answer":"X","reason_options":[{"t":"같은 양의 물에 녹는 양은 용질의 종류에 따라 달라 일부가 남을 수 있기 때문에","correct":true},{"t":"물에 넣은 용질은 모두 녹아야 바르게 한 실험이기 때문에","mis":"SC5-1-u3-X17"}],"mis":"SC5-1-u3-X17","explanation":["바닥에 남는 것도 결과예요.","용질마다 달라요.","잘못된 실험이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#6','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C14',3,'error','auto','실험 도구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X19']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C14","difficulty":3,"kind":"error","stem":"실험 도구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「눈금실린더로 비커 속 소금을 저어 녹이자.」","correct":true,"mis_target":"SC5-1-u3-X19"},{"t":"가온 — 「유리 막대는 비커마다 따로 쓰자.」","mis":"SC5-1-u3-X19"},{"t":"보라 — 「물질이 섞이지 않게 약숟가락을 구분하자.」","mis":"SC5-1-u3-X19"}],"explanation":["젓는 도구는 무엇인가요?","유리 막대예요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#7','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C13',3,'mc','auto','하나만 다르게 하고 나머지를 모두 같게 해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X18']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C13","difficulty":3,"kind":"mc","stem":"하나만 다르게 하고 나머지를 모두 같게 해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"결과가 그 한 가지 때문이라고 말할 수 있기 때문에","correct":true},{"t":"실험이 빨리 끝나기 때문에","mis":"SC5-1-u3-X18"},{"t":"같게 할 것이 많을수록 용질이 더 많이 녹기 때문에","mis":"SC5-1-u3-X18"},{"t":"비커를 덜 써도 되기 때문에","mis":"SC5-1-u3-X18"}],"explanation":["무엇 때문인지 알아야 해요.","원인을 하나로 좁혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#8','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C12',4,'mc','auto','같은 온도의 물 한 컵에 소금을 넣다 보니 바닥에 남기 시작했어요. 같은 컵에 같은 온도, 같은 양의 물을 담고 설탕을 넣으면 어떻게 될까요?',ARRAY['SC5-1-u3-X16','SC5-1-u3-X17']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C12","difficulty":4,"kind":"mc","stem":"같은 온도의 물 한 컵에 소금을 넣다 보니 바닥에 남기 시작했어요. 같은 컵에 같은 온도, 같은 양의 물을 담고 설탕을 넣으면 어떻게 될까요?","options":[{"t":"설탕은 소금보다 더 많이 녹을 것이다","correct":true},{"t":"소금과 똑같은 양에서 바닥에 남을 것이다","mis":"SC5-1-u3-X16"},{"t":"설탕은 한 숟가락도 녹지 않을 것이다","mis":"SC5-1-u3-X16"},{"t":"오래 저으면 소금도 설탕도 끝없이 녹을 것이다","mis":"SC5-1-u3-X17"}],"explanation":["세 비커 실험을 떠올려요.","설탕이 소금보다 많이 녹았어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#9','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C14',4,'mc','auto','옆 모둠의 기록에서 고쳐야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X20','SC5-1-u3-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C14","difficulty":4,"kind":"mc","stem":"옆 모둠의 기록에서 고쳐야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"바닥에 남기 시작하면 더 넣지 않고, 녹은 양만 사실대로 적어야 한다","correct":true},{"t":"백반을 열 숟가락보다 더 많이 넣어야 했다","mis":"SC5-1-u3-X20"},{"t":"전자저울로 백반의 무게를 재었어야 했다","mis":"SC5-1-u3-X19"},{"t":"고칠 점이 없다","mis":"SC5-1-u3-X20"}],"explanation":["둘째부터 남았어요.","남으면 그만 넣어요.","첫 번째예요."],"asset":{"type":"passage","lines":["백반이 둘째 숟가락부터 바닥에 남았다.","그래도 계속 넣어 열 숟가락까지 넣었다.","기록장 — 「백반 열 숟가락이 녹았다.」"],"title":"옆 모둠의 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L04_challenge#10','sci',5,1,'u3','L04','g5_1_sci_u3_L04_challenge','lesson_challenge','SC5-1-u3-C13',4,'essay','teacher','설탕, 소금, 백반이 용해되는 양을 비교하는 실험에서 같게 할 것과 다르게 할 것을 쓰고, 실험 결과로 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C13","difficulty":4,"kind":"essay","stem":"설탕, 소금, 백반이 용해되는 양을 비교하는 실험에서 같게 할 것과 다르게 할 것을 쓰고, 실험 결과로 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 물의 온도, 물의 양, 약숟가락에 담는 양은 같게 하고, 용질의 종류만 다르게 한다. 같은 온도, 같은 양의 물에 넣었을 때 설탕은 모두 용해되었지만 소금은 일부가 바닥에 남았고 백반은 가장 적게 용해되었다. 이것으로 물에 용해되는 용질의 양은 용질의 종류에 따라 다르다는 것을 알 수 있다.","scoring_points":["같게 할 것을 바르게 썼는가","다르게 할 것을 용질의 종류 하나로 썼는가","용질의 종류에 따라 녹는 양이 다르다고 썼는가"]},"explanation":["같게 할 것부터 써요.","다르게 할 것은 하나예요.","결과로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#1','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C15',1,'mc','auto','물의 양이 같을 때, 백반이 물에 용해되는 양은 물의 온도에 따라 어떠한가요?',ARRAY['SC5-1-u3-X21']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C15","difficulty":1,"kind":"mc","stem":"물의 양이 같을 때, 백반이 물에 용해되는 양은 물의 온도에 따라 어떠한가요?","options":[{"t":"다르다","correct":true},{"t":"언제나 같다","mis":"SC5-1-u3-X21"},{"t":"알 수 없다","mis":"SC5-1-u3-X21"},{"t":"넣는 시간에 따라서만 달라진다","mis":"SC5-1-u3-X21"}],"explanation":["두 비커를 떠올려요.","따뜻한 물에서 더 녹았어요.","달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#2','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C15',1,'mc','auto','물의 양이 같을 때, 물의 온도가 높을수록 용질은 어떻게 되나요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X21','SC5-1-u3-X11']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C15","difficulty":1,"kind":"mc","stem":"물의 양이 같을 때, 물의 온도가 높을수록 용질은 어떻게 되나요?","options":[{"t":"더 많이 용해된다","correct":true},{"t":"더 적게 용해된다","mis":"SC5-1-u3-X22"},{"t":"용해되는 양이 달라지지 않는다","mis":"SC5-1-u3-X21"},{"t":"용해된 용질이 사라진다","mis":"SC5-1-u3-X11"}],"explanation":["따뜻한 물을 떠올려요.","더 많이 녹았어요.","더 많이 용해돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#3','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C16',1,'sa','auto','「바닥에 남은 백반을 더 녹이려면 물의 □□를 높입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C16","difficulty":1,"kind":"sa","stem":"「바닥에 남은 백반을 더 녹이려면 물의 □□를 높입니다.」 □□에 알맞은 말을 쓰세요.","answer":["온도"],"explanation":["왼쪽 물을 데웠어요.","두 글자예요.","온도예요."],"mis":"SC5-1-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#4','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C16',1,'ox','auto','분말주스는 찬물보다 따뜻한 물에서 더 잘 녹아요.',ARRAY['SC5-1-u3-X22']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C16","difficulty":1,"kind":"ox","stem":"분말주스는 찬물보다 따뜻한 물에서 더 잘 녹아요.","answer":"O","reason_options":[{"t":"물의 온도가 높을수록 용질이 더 많이 용해되기 때문에","correct":true},{"t":"차가운 물일수록 용질이 더 많이 녹기 때문에","mis":"SC5-1-u3-X22"}],"mis":"SC5-1-u3-X22","explanation":["온도를 떠올려요.","높을수록 많이 녹아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#5','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C17',2,'match','auto','탐구 보고서 항목과 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C17","difficulty":2,"kind":"match","stem":"탐구 보고서 항목과 내용을 알맞게 이으세요.","pairs":[{"l":"탐구 주제","r":"온도 요인 알아보기"},{"l":"다르게 해야 할 조건","r":"물의 온도"},{"l":"같게 해야 할 조건","r":"용질의 종류와 물의 양"},{"l":"실험 결과","r":"따뜻한 물에서 백반이 더 많이 용해됨"}],"mis":"SC5-1-u3-X24","explanation":["항목 이름을 읽어요.","다르게 할 것은 온도예요.","결과는 관찰한 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#6','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C17',2,'mc','auto','물의 온도에 따라 백반이 용해되는 양을 알아볼 때 다르게 해야 할 조건은 어느 것인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C17","difficulty":2,"kind":"mc","stem":"물의 온도에 따라 백반이 용해되는 양을 알아볼 때 다르게 해야 할 조건은 어느 것인가요?","options":[{"t":"물의 온도","correct":true},{"t":"물의 양","mis":"SC5-1-u3-X24"},{"t":"용질의 종류","mis":"SC5-1-u3-X24"},{"t":"약숟가락에 담는 백반의 양","mis":"SC5-1-u3-X24"}],"explanation":["무엇을 알아보나요?","온도예요.","물의 온도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#7','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C16',2,'mc','auto','바닥에 남은 백반을 더 녹이는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X23','SC5-1-u3-X22']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C16","difficulty":2,"kind":"mc","stem":"바닥에 남은 백반을 더 녹이는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"따뜻한 물이 든 비커에 녹인다","correct":true},{"t":"백반을 한 숟가락 더 넣는다","mis":"SC5-1-u3-X23"},{"t":"물을 더 차갑게 만든다","mis":"SC5-1-u3-X22"},{"t":"물을 조금 덜어 낸다","mis":"SC5-1-u3-X23"}],"explanation":["온도를 떠올려요.","높이면 더 녹아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#8','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C17',2,'blank','auto','「다르게 해야 할 조건은 (    )이어야 결과가 온도 때문이라고 말할 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C17","difficulty":2,"kind":"blank","stem":"「다르게 해야 할 조건은 (    )이어야 결과가 온도 때문이라고 말할 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"딱 하나","correct":true},{"t":"둘 이상","mis":"SC5-1-u3-X24"},{"t":"많을수록 좋은 것","mis":"SC5-1-u3-X24"},{"t":"아무것도 없는 것","mis":"SC5-1-u3-X24"}],"explanation":["공정한 비교를 떠올려요.","하나만 달라야 해요.","딱 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#9','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C15',2,'error','auto','실험 결과를 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X21','SC5-1-u3-X16']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C15","difficulty":2,"kind":"error","stem":"실험 결과를 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「물을 차갑게 할수록 용질이 더 많이 녹아.」","correct":true,"mis_target":"SC5-1-u3-X22"},{"t":"준우 — 「물의 온도에 따라 녹는 양이 달라.」","mis":"SC5-1-u3-X21"},{"t":"라희 — 「용질의 종류도 녹는 양에 영향을 줘.」","mis":"SC5-1-u3-X16"}],"explanation":["차가운 물과 따뜻한 물을 견줘요.","따뜻할수록 더 녹아요.","세아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_basic#10','sci',5,1,'u3','L05','g5_1_sci_u3_L05_basic','lesson_basic','SC5-1-u3-C16',3,'mc','auto','세탁을 마친 옷에 가루 세제가 남아 있어요. 모두 녹이려면 어떻게 하는 것이 알맞은가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X23']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C16","difficulty":3,"kind":"mc","stem":"세탁을 마친 옷에 가루 세제가 남아 있어요. 모두 녹이려면 어떻게 하는 것이 알맞은가요?","options":[{"t":"헹구는 물의 온도를 높인다","correct":true},{"t":"더 차가운 물에 오래 담가 둔다","mis":"SC5-1-u3-X22"},{"t":"가루 세제를 더 넣는다","mis":"SC5-1-u3-X23"},{"t":"헹구는 물의 양을 줄인다","mis":"SC5-1-u3-X23"}],"explanation":["남은 용질을 떠올려요.","온도를 높여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#1','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C17',2,'mc','auto','온도 요인을 알아보는 탐구의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C17","difficulty":2,"kind":"mc","stem":"온도 요인을 알아보는 탐구의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉢ → ㉣ → ㉠ → ㉤ → ㉡","correct":true},{"t":"㉤ → ㉢ → ㉣ → ㉠ → ㉡","mis":"SC5-1-u3-X24"},{"t":"㉢ → ㉡ → ㉣ → ㉠ → ㉤","mis":"SC5-1-u3-X24"},{"t":"㉣ → ㉠ → ㉢ → ㉡ → ㉤","mis":"SC5-1-u3-X24"}],"explanation":["예상이 먼저예요.","조건을 정한 다음 실험해요.","보고서는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 같게 해야 할 조건을 정한다.","㉡ 결과를 견주어 탐구 보고서에 적는다.","㉢ 물의 온도에 따라 용해되는 양을 예상한다.","㉣ 다르게 해야 할 조건을 정한다.","㉤ 실험 과정을 정하고 관찰한다."],"title":"온도 요인 탐구(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#2','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C17',2,'ox','auto','차가운 물 비커와 따뜻한 물 비커의 물의 양을 서로 다르게 해도 온도 때문인지 알 수 있어요.',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C17","difficulty":2,"kind":"ox","stem":"차가운 물 비커와 따뜻한 물 비커의 물의 양을 서로 다르게 해도 온도 때문인지 알 수 있어요.","answer":"X","reason_options":[{"t":"물의 양이 다르면 결과가 온도 때문인지 물의 양 때문인지 알 수 없기 때문에","correct":true},{"t":"다르게 할 조건은 많을수록 더 정확하기 때문에","mis":"SC5-1-u3-X24"}],"mis":"SC5-1-u3-X24","explanation":["다르게 한 것이 몇 개인가요?","둘이 달라요.","알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#3','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C15',3,'sa','auto','우리 모둠 온도 비교 기록에서 따뜻한 물에서는 차가운 물보다 백반이 몇 숟가락 더 용해되었는지 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C15","difficulty":3,"kind":"sa","stem":"우리 모둠 온도 비교 기록에서 따뜻한 물에서는 차가운 물보다 백반이 몇 숟가락 더 용해되었는지 쓰세요.","answer":["3","3숟가락","3 숟가락","세 숟가락","셋"],"explanation":["차가운 물은 한 숟가락이에요.","따뜻한 물은 네 숟가락이에요.","세 숟가락 더예요."],"asset":{"type":"passage","lines":["같은 양의 물이 든 비커 두 개에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 첫째 숟가락은 모두 용해, 둘째 숟가락부터 바닥에 남음","따뜻한 물 — 넷째 숟가락까지 모두 용해, 다섯째 숟가락부터 바닥에 남음"],"title":"우리 모둠 온도 비교 기록"},"mis":"SC5-1-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#4','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C15',3,'mc','auto','우리 모둠 온도 비교 기록으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X21']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C15","difficulty":3,"kind":"mc","stem":"우리 모둠 온도 비교 기록으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"물의 양이 같을 때 물의 온도가 높을수록 백반이 더 많이 용해된다","correct":true},{"t":"물의 온도가 낮을수록 백반이 더 많이 용해된다","mis":"SC5-1-u3-X22"},{"t":"물의 온도는 녹는 양과 관계없다","mis":"SC5-1-u3-X21"},{"t":"백반은 따뜻한 물에서만 녹는다","mis":"SC5-1-u3-X21"}],"explanation":["두 비커를 견줘요.","따뜻한 물에서 더 녹았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 양의 물이 든 비커 두 개에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 첫째 숟가락은 모두 용해, 둘째 숟가락부터 바닥에 남음","따뜻한 물 — 넷째 숟가락까지 모두 용해, 다섯째 숟가락부터 바닥에 남음"],"title":"우리 모둠 온도 비교 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#5','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C17',3,'mc','auto','친구의 탐구 계획에서 잘못된 곳을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C17","difficulty":3,"kind":"mc","stem":"친구의 탐구 계획에서 잘못된 곳을 바르게 고친 것은 어느 것인가요?","options":[{"t":"다르게 해야 할 조건을 물의 온도로 고친다","correct":true},{"t":"다르게 해야 할 조건을 용질의 종류로 고친다","mis":"SC5-1-u3-X24"},{"t":"같게 해야 할 조건에서 물의 양을 뺀다","mis":"SC5-1-u3-X24"},{"t":"준비물에서 백반을 뺀다","mis":"SC5-1-u3-X24"}],"explanation":["탐구 주제를 읽어요.","온도를 알아보아요.","다르게 할 것은 온도예요."],"asset":{"type":"passage","lines":["탐구 주제 — 물에 녹는 용질의 양에 영향을 주는 온도 요인","준비물 — 차가운 물, 따뜻한 물, 백반, 비커 두 개, 눈금실린더, 유리 막대","같게 해야 할 조건 — 물의 양, 용질의 종류와 양","다르게 해야 할 조건 — 약숟가락 크기"],"title":"친구의 탐구 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#6','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C16',3,'error','auto','바닥에 남은 백반을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X23','SC5-1-u3-X22']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C16","difficulty":3,"kind":"error","stem":"바닥에 남은 백반을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「바닥에 남은 백반을 녹이려면 백반을 한 숟가락 더 넣자.」","correct":true,"mis_target":"SC5-1-u3-X23"},{"t":"소윤 — 「물의 온도를 높여 보자.」","mis":"SC5-1-u3-X23"},{"t":"태린 — 「따뜻한 물이 든 비커로 해 보자.」","mis":"SC5-1-u3-X22"}],"explanation":["더 넣으면 녹을까요?","온도를 높여야 해요.","하준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#7','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C15',3,'mc','auto','물에 용해되는 용질의 양에 영향을 주는 두 가지 요인을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X18','SC5-1-u3-X21']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C15","difficulty":3,"kind":"mc","stem":"물에 용해되는 용질의 양에 영향을 주는 두 가지 요인을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"용질의 종류와 물의 온도","correct":true},{"t":"이름 붙임딱지와 유리 막대의 색깔","mis":"SC5-1-u3-X18"},{"t":"비커의 모양과 실험하는 사람","mis":"SC5-1-u3-X18"},{"t":"용질의 종류뿐이고 물의 온도는 관계없다","mis":"SC5-1-u3-X21"}],"explanation":["두 차시를 떠올려요.","종류, 그리고 온도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#8','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C16',4,'mc','auto','찬물에 분말주스를 타다 보니 바닥에 가루가 남았어요. 남은 가루를 녹이려면 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X23','SC5-1-u3-X04']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C16","difficulty":4,"kind":"mc","stem":"찬물에 분말주스를 타다 보니 바닥에 가루가 남았어요. 남은 가루를 녹이려면 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"따뜻한 물을 써서 다시 녹여 본다","correct":true},{"t":"얼음을 더 넣어 차갑게 한다","mis":"SC5-1-u3-X22"},{"t":"분말주스 가루를 더 넣는다","mis":"SC5-1-u3-X23"},{"t":"남은 가루는 물에 녹지 않는 물질이니 그냥 둔다","mis":"SC5-1-u3-X04"}],"explanation":["남은 용질을 떠올려요.","온도를 높여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#9','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C17',4,'mc','auto','차가운 물 50 mL와 따뜻한 물 100 mL에 백반을 넣었더니 따뜻한 물에서 더 많이 녹았어요. 이 결과만으로 「온도가 높을수록 더 많이 녹는다」고 말하기 어려운 까닭은 어느 것인가요?',ARRAY['SC5-1-u3-X21','SC5-1-u3-X24','SC5-1-u3-X22']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C17","difficulty":4,"kind":"mc","stem":"차가운 물 50 mL와 따뜻한 물 100 mL에 백반을 넣었더니 따뜻한 물에서 더 많이 녹았어요. 이 결과만으로 「온도가 높을수록 더 많이 녹는다」고 말하기 어려운 까닭은 어느 것인가요?","options":[{"t":"물의 양도 달라 온도 때문인지 물의 양 때문인지 가를 수 없기 때문에","correct":true},{"t":"백반은 물의 온도와 관계없이 녹기 때문에","mis":"SC5-1-u3-X21"},{"t":"다르게 한 조건이 둘이라 오히려 더 정확하기 때문에","mis":"SC5-1-u3-X24"},{"t":"차가운 물에서 더 많이 녹아야 맞기 때문에","mis":"SC5-1-u3-X22"}],"explanation":["다르게 한 것을 세어요.","온도와 물의 양이에요.","하나만 달라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L05_challenge#10','sci',5,1,'u3','L05','g5_1_sci_u3_L05_challenge','lesson_challenge','SC5-1-u3-C17',4,'essay','teacher','물의 온도에 따라 백반이 용해되는 양을 알아보는 탐구 계획을 같게 해야 할 조건과 다르게 해야 할 조건으로 나누어 쓰고, 결과와 그것을 생활에 이용하는 예를 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C17","difficulty":4,"kind":"essay","stem":"물의 온도에 따라 백반이 용해되는 양을 알아보는 탐구 계획을 같게 해야 할 조건과 다르게 해야 할 조건으로 나누어 쓰고, 결과와 그것을 생활에 이용하는 예를 하나 쓰세요.","answer_guide":{"answer":"예: 같게 해야 할 조건은 용질의 종류(백반), 물의 양, 약숟가락에 담는 백반의 양이고, 다르게 해야 할 조건은 물의 온도 하나이다. 실험해 보면 물의 양이 같을 때 따뜻한 물에서 백반이 더 많이 용해된다. 그래서 옷에 가루 세제가 남으면 헹구는 물의 온도를 높여 녹인다.","scoring_points":["같게 해야 할 조건을 바르게 썼는가","다르게 해야 할 조건을 물의 온도 하나로 썼는가","결과와 생활 속 예를 썼는가"]},"explanation":["조건부터 나눠요.","결과를 써요.","생활 속 예를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#1','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C18',1,'mc','auto','같은 양의 용매에 용해된 용질의 양이 많고 적은 정도를 무엇이라고 하나요?',ARRAY['SC5-1-u3-X25']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C18","difficulty":1,"kind":"mc","stem":"같은 양의 용매에 용해된 용질의 양이 많고 적은 정도를 무엇이라고 하나요?","options":[{"t":"용액의 진하기","correct":true},{"t":"용액의 무게","mis":"SC5-1-u3-X25"},{"t":"물의 온도","mis":"SC5-1-u3-X25"},{"t":"용질의 종류","mis":"SC5-1-u3-X25"}],"explanation":["많고 적은 정도예요.","진하고 묽음이에요.","용액의 진하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#2','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C21',1,'mc','auto','크기와 무게가 같은 방울토마토를 넣었을 때 가장 높이 떠오르는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X26','SC5-1-u3-X27']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C21","difficulty":1,"kind":"mc","stem":"크기와 무게가 같은 방울토마토를 넣었을 때 가장 높이 떠오르는 용액은 어느 것인가요?","options":[{"t":"가장 진한 용액","correct":true},{"t":"가장 묽은 용액","mis":"SC5-1-u3-X28"},{"t":"물의 양이 가장 많은 용액","mis":"SC5-1-u3-X26"},{"t":"어느 용액이든 높이가 같다","mis":"SC5-1-u3-X27"}],"explanation":["진하기를 떠올려요.","진할수록 높이 떠요.","가장 진한 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#3','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C19',1,'sa','auto','「같은 양의 물에 설탕을 열 숟가락 녹인 용액은 한 숟가락 녹인 용액보다 □□ 용액입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C19","difficulty":1,"kind":"sa","stem":"「같은 양의 물에 설탕을 열 숟가락 녹인 용액은 한 숟가락 녹인 용액보다 □□ 용액입니다.」 □□에 알맞은 말을 쓰세요.","answer":["진한"],"explanation":["용질이 더 많아요.","두 글자예요.","진한 용액이에요."],"mis":"SC5-1-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#4','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C20',1,'ox','auto','황설탕 용액은 진할수록 색깔이 더 진해요.',ARRAY['SC5-1-u3-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C20","difficulty":1,"kind":"ox","stem":"황설탕 용액은 진할수록 색깔이 더 진해요.","answer":"O","reason_options":[{"t":"같은 양의 물에 황설탕이 많이 녹아 있을수록 색깔이 진하기 때문에","correct":true},{"t":"황설탕 용액은 진하기와 관계없이 색깔이 늘 같기 때문에","mis":"SC5-1-u3-X27"}],"mis":"SC5-1-u3-X27","explanation":["두 비커를 떠올려요.","많이 넣은 쪽이 진했어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#5','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C21',2,'match','auto','알맞은 설명끼리 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C21","difficulty":2,"kind":"match","stem":"알맞은 설명끼리 이으세요.","pairs":[{"l":"흰 종이","r":"비커 뒤에 대어 색깔을 정확하게 본다"},{"l":"방울토마토","r":"뜨는 높이로 진하기를 비교한다"},{"l":"사해","r":"소금이 많이 녹아 있어 몸이 쉽게 뜨는 호수"},{"l":"디지털 염도계","r":"진할수록 수치가 커진다"}],"mis":"SC5-1-u3-X29","explanation":["하나씩 떠올려요.","색깔, 높이, 몸, 수치예요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#6','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C19',2,'mc','auto','진한 용액이 되는 경우는 어느 것인가요?',ARRAY['SC5-1-u3-X26']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C19","difficulty":2,"kind":"mc","stem":"진한 용액이 되는 경우는 어느 것인가요?","options":[{"t":"같은 양의 설탕을 더 적은 물에 녹인다","correct":true},{"t":"같은 양의 설탕을 더 많은 물에 녹인다","mis":"SC5-1-u3-X26"},{"t":"같은 양의 물에 설탕을 더 적게 녹인다","mis":"SC5-1-u3-X26"},{"t":"설탕물에 물을 더 부어 섞는다","mis":"SC5-1-u3-X26"}],"explanation":["용매와 용질을 봐요.","물이 적을수록 진해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#7','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C20',2,'mc','auto','백설탕 용액처럼 색깔로 진하기를 가리기 어려운 용액은 어떻게 비교하나요?',ARRAY['SC5-1-u3-X29']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C20","difficulty":2,"kind":"mc","stem":"백설탕 용액처럼 색깔로 진하기를 가리기 어려운 용액은 어떻게 비교하나요?","options":[{"t":"물체를 넣어 떠오르는 정도로 비교한다","correct":true},{"t":"녹이는 데 걸린 시간을 잰다","mis":"SC5-1-u3-X29"},{"t":"비커의 크기를 비교한다","mis":"SC5-1-u3-X29"},{"t":"맛을 보아 비교한다","mis":"SC5-1-u3-X29"}],"explanation":["방울토마토를 떠올려요.","뜨는 정도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#8','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C20',2,'blank','auto','「색깔이 있는 용액의 진하기를 더 정확하게 보려면 비커 뒤에 (    )를 댑니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X29']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C20","difficulty":2,"kind":"blank","stem":"「색깔이 있는 용액의 진하기를 더 정확하게 보려면 비커 뒤에 (    )를 댑니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"흰 종이","correct":true},{"t":"검은 종이","mis":"SC5-1-u3-X29"},{"t":"투명한 비닐","mis":"SC5-1-u3-X29"},{"t":"젖은 수건","mis":"SC5-1-u3-X29"}],"explanation":["색깔이 잘 보여야 해요.","하얀 바탕이에요.","흰 종이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#9','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C21',2,'error','auto','진하기를 비교하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X29']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C21","difficulty":2,"kind":"error","stem":"진하기를 비교하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「용액이 진할수록 방울토마토가 더 깊이 가라앉아.」","correct":true,"mis_target":"SC5-1-u3-X28"},{"t":"지성 — 「크기와 무게가 같은 방울토마토를 쓰자.」","mis":"SC5-1-u3-X29"},{"t":"아린 — 「쓴 방울토마토는 핀셋으로 꺼내 닦아서 다시 쓰자.」","mis":"SC5-1-u3-X29"}],"explanation":["진할수록 어떻게 되었나요?","높이 떠올랐어요.","하늘이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_basic#10','sci',5,1,'u3','L06','g5_1_sci_u3_L06_basic','lesson_basic','SC5-1-u3-C21',3,'mc','auto','소금물에 떠 있는 메추리알의 높이를 낮추려면 어떻게 해야 하나요?',ARRAY['SC5-1-u3-X31']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C21","difficulty":3,"kind":"mc","stem":"소금물에 떠 있는 메추리알의 높이를 낮추려면 어떻게 해야 하나요?","options":[{"t":"물을 더 넣어 묽게 만든다","correct":true},{"t":"소금을 더 넣어 녹인다","mis":"SC5-1-u3-X31"},{"t":"메추리알을 하나 더 넣는다","mis":"SC5-1-u3-X31"},{"t":"소금물을 오래 저어 둔다","mis":"SC5-1-u3-X31"}],"explanation":["묽을수록 낮게 떠요.","물을 더 넣어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#1','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C21',2,'mc','auto','크기와 무게가 같은 방울토마토를 진하기가 다른 세 용액에 넣었어요. 가장 진한 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X27']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C21","difficulty":2,"kind":"mc","stem":"크기와 무게가 같은 방울토마토를 진하기가 다른 세 용액에 넣었어요. 가장 진한 용액은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"SC5-1-u3-X28"},{"t":"㉯","mis":"SC5-1-u3-X28"},{"t":"뜨는 정도만으로는 알 수 없다","mis":"SC5-1-u3-X27"}],"explanation":["높이를 견줘요.","가장 높이 뜬 것이에요.","㉰예요."],"asset":{"type":"geo","items":[{"w":320,"h":192,"seg":[[[20,40],[20,170]],[[20,170],[100,170]],[[100,170],[100,40]],[[20,62],[100,62]],[[120,40],[120,170]],[[120,170],[200,170]],[[200,170],[200,40]],[[120,62],[200,62]],[[220,40],[220,170]],[[220,170],[300,170]],[[300,170],[300,40]],[[220,62],[300,62]]],"lab":[[[60,184],"㉮"],[[160,184],"㉯"],[[260,184],"㉰"]],"oval":[[60,156,13,11],[160,112,13,11],[260,74,13,11]],"cap":"진하기가 다른 세 용액에 넣은 방울토마토"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#2','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C19',2,'sa','auto','같은 양의 물에 백설탕을 ㉮에는 두 숟가락, ㉯에는 여섯 숟가락 녹였어요. 더 진한 용액의 기호를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C19","difficulty":2,"kind":"sa","stem":"같은 양의 물에 백설탕을 ㉮에는 두 숟가락, ㉯에는 여섯 숟가락 녹였어요. 더 진한 용액의 기호를 쓰세요.","answer":["㉯","나"],"explanation":["물의 양은 같아요.","용질이 많은 쪽이에요.","㉯예요."],"mis":"SC5-1-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#3','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C19',3,'mc','auto','설탕 용액 세 가지 가운데 가장 진한 것은 어느 것인가요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X25']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C19","difficulty":3,"kind":"mc","stem":"설탕 용액 세 가지 가운데 가장 진한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SC5-1-u3-X26"},{"t":"㉢","mis":"SC5-1-u3-X26"},{"t":"셋 다 같다","mis":"SC5-1-u3-X25"}],"explanation":["㉠과 ㉡은 설탕 양이 같아요.","물이 적은 ㉡이 더 진해요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 물 100 mL에 설탕 네 숟가락을 녹인 용액","㉡ 물 50 mL에 설탕 네 숟가락을 녹인 용액","㉢ 물 100 mL에 설탕 두 숟가락을 녹인 용액"],"title":"설탕 용액 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#4','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C21',3,'mc','auto','그림의 ㉮ 용액에 든 방울토마토를 ㉰처럼 높이 떠오르게 하려면 어떻게 해야 하나요?',ARRAY['SC5-1-u3-X31','SC5-1-u3-X29']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C21","difficulty":3,"kind":"mc","stem":"그림의 ㉮ 용액에 든 방울토마토를 ㉰처럼 높이 떠오르게 하려면 어떻게 해야 하나요?","options":[{"t":"같은 용질을 더 넣어 녹인다","correct":true},{"t":"물을 더 넣는다","mis":"SC5-1-u3-X31"},{"t":"방울토마토를 더 큰 것으로 바꾼다","mis":"SC5-1-u3-X29"},{"t":"용액을 맛보며 조금씩 덜어 낸다","mis":"SC5-1-u3-X29"}],"explanation":["진하게 만들어야 해요.","용질을 더해요.","첫 번째예요."],"asset":{"type":"geo","items":[{"w":320,"h":192,"seg":[[[20,40],[20,170]],[[20,170],[100,170]],[[100,170],[100,40]],[[20,62],[100,62]],[[120,40],[120,170]],[[120,170],[200,170]],[[200,170],[200,40]],[[120,62],[200,62]],[[220,40],[220,170]],[[220,170],[300,170]],[[300,170],[300,40]],[[220,62],[300,62]]],"lab":[[[60,184],"㉮"],[[160,184],"㉯"],[[260,184],"㉰"]],"oval":[[60,156,13,11],[160,112,13,11],[260,74,13,11]],"cap":"진하기가 다른 세 용액에 넣은 방울토마토"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#5','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C20',3,'ox','auto','백설탕 용액 두 개는 색깔만 보아도 어느 쪽이 진한지 쉽게 가릴 수 있어요.',ARRAY['SC5-1-u3-X30']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C20","difficulty":3,"kind":"ox","stem":"백설탕 용액 두 개는 색깔만 보아도 어느 쪽이 진한지 쉽게 가릴 수 있어요.","answer":"X","reason_options":[{"t":"백설탕 용액은 색깔이 거의 같아 물체가 뜨는 정도 등으로 비교해야 하기 때문에","correct":true},{"t":"진한 용액은 언제나 색깔이 더 진하기 때문에","mis":"SC5-1-u3-X30"}],"mis":"SC5-1-u3-X30","explanation":["백설탕 용액을 떠올려요.","색이 거의 같아요.","쉽게 가릴 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#6','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C21',3,'error','auto','진하기 비교 실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X29']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C21","difficulty":3,"kind":"error","stem":"진하기 비교 실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「크기가 다른 방울토마토를 넣어도 괜찮아.」","correct":true,"mis_target":"SC5-1-u3-X29"},{"t":"도윤 — 「비커 두 개에 같은 온도의 물을 같은 양씩 담자.」","mis":"SC5-1-u3-X29"},{"t":"예린 — 「흰 종이를 비커 뒤에 대고 색깔을 보자.」","mis":"SC5-1-u3-X29"}],"explanation":["물체가 달라도 될까요?","크기와 무게가 같아야 해요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#7','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C18',3,'mc','auto','두 용액의 진하기를 비교할 때 용매의 양을 같게 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X25','SC5-1-u3-X28']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C18","difficulty":3,"kind":"mc","stem":"두 용액의 진하기를 비교할 때 용매의 양을 같게 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"용질의 양만으로 진하기를 견줄 수 있게 하려고","correct":true},{"t":"용액을 더 무겁게 만들려고","mis":"SC5-1-u3-X25"},{"t":"방울토마토를 가라앉히려고","mis":"SC5-1-u3-X28"},{"t":"물의 온도를 높이려고","mis":"SC5-1-u3-X25"}],"explanation":["진하기의 뜻을 떠올려요.","같은 양의 용매예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#8','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C21',4,'mc','auto','바닷물보다 훨씬 진한 소금물로 채운 수영장에 들어가면 어떤 일이 일어날까요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X11','SC5-1-u3-X25']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C21","difficulty":4,"kind":"mc","stem":"바닷물보다 훨씬 진한 소금물로 채운 수영장에 들어가면 어떤 일이 일어날까요?","options":[{"t":"몸이 잘 떠올라서 가라앉기 어렵다","correct":true},{"t":"몸이 훨씬 무거워져 바닥까지 가라앉는다","mis":"SC5-1-u3-X28"},{"t":"소금이 다 녹았으므로 맹물과 똑같다","mis":"SC5-1-u3-X11"},{"t":"물의 온도가 저절로 높아진다","mis":"SC5-1-u3-X25"}],"explanation":["사해를 떠올려요.","진할수록 잘 떠요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#9','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C19',4,'mc','auto','물 100 mL에 황설탕 세 숟가락을 녹인 용액보다 더 진한 용액을 만들려면 어떻게 해야 하나요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X25']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C19","difficulty":4,"kind":"mc","stem":"물 100 mL에 황설탕 세 숟가락을 녹인 용액보다 더 진한 용액을 만들려면 어떻게 해야 하나요?","options":[{"t":"물 50 mL에 황설탕 세 숟가락을 녹인다","correct":true},{"t":"물 200 mL에 황설탕 세 숟가락을 녹인다","mis":"SC5-1-u3-X26"},{"t":"물 100 mL에 황설탕 한 숟가락을 녹인다","mis":"SC5-1-u3-X26"},{"t":"물 100 mL에 황설탕 세 숟가락을 더 오래 저어 녹인다","mis":"SC5-1-u3-X25"}],"explanation":["용질은 그대로, 용매는?","물이 적을수록 진해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L06_challenge#10','sci',5,1,'u3','L06','g5_1_sci_u3_L06_challenge','lesson_challenge','SC5-1-u3-C21',4,'essay','teacher','겉보기로 똑같아 보이는 백설탕 용액 두 개의 진하기를 비교하는 방법을 쓰고, 결과를 보고 어느 쪽이 진한지 판단하는 방법과 실험할 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C21","difficulty":4,"kind":"essay","stem":"겉보기로 똑같아 보이는 백설탕 용액 두 개의 진하기를 비교하는 방법을 쓰고, 결과를 보고 어느 쪽이 진한지 판단하는 방법과 실험할 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 백설탕 용액은 색깔이 거의 같아 색깔로는 가리기 어려우므로 크기와 무게가 같은 방울토마토를 두 용액에 넣고 뜨는 정도를 비교한다. 방울토마토가 더 높이 떠오른 쪽이 더 진한 용액이다. 실험할 때에는 용액을 맛보지 않고, 쓴 방울토마토는 핀셋으로 꺼내 수건으로 닦아 다시 쓴다.","scoring_points":["뜨는 정도로 비교한다고 썼는가","높이 떠오른 쪽이 진하다고 썼는가","같은 물체·맛보지 않기 등 지킬 점을 썼는가"]},"explanation":["색깔로는 어려워요.","뜨는 높이를 봐요.","지킬 점을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#1','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',1,'mc','auto','손에 묻은 세균을 없애려고 쓰는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X33']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C22","difficulty":1,"kind":"mc","stem":"손에 묻은 세균을 없애려고 쓰는 용액은 어느 것인가요?","options":[{"t":"손 소독제","correct":true},{"t":"간장","mis":"SC5-1-u3-X33"},{"t":"식초","mis":"SC5-1-u3-X33"},{"t":"식물 영양제","mis":"SC5-1-u3-X33"}],"explanation":["밖에 나갔다 온 뒤를 떠올려요.","손을 소독해요.","손 소독제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#2','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',1,'mc','auto','음식에 신맛을 더할 때 넣는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X33']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C22","difficulty":1,"kind":"mc","stem":"음식에 신맛을 더할 때 넣는 용액은 어느 것인가요?","options":[{"t":"식초","correct":true},{"t":"손 소독제","mis":"SC5-1-u3-X33"},{"t":"구강 청결제","mis":"SC5-1-u3-X33"},{"t":"링거액","mis":"SC5-1-u3-X33"}],"explanation":["신맛이에요.","요리할 때 넣어요.","식초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#3','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',1,'sa','auto','「자기 전에 입안을 헹궈 청결하게 유지하는 용액은 구강 □□□입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C22","difficulty":1,"kind":"sa","stem":"「자기 전에 입안을 헹궈 청결하게 유지하는 용액은 구강 □□□입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["청결제"],"explanation":["입안을 깨끗하게 해요.","세 글자예요.","구강 청결제예요."],"mis":"SC5-1-u3-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#4','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',1,'ox','auto','용액은 과학실에서만 볼 수 있어요.',ARRAY['SC5-1-u3-X32']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C22","difficulty":1,"kind":"ox","stem":"용액은 과학실에서만 볼 수 있어요.","answer":"X","reason_options":[{"t":"손 소독제, 식초처럼 우리 주변에서 쉽게 찾아볼 수 있기 때문에","correct":true},{"t":"용액은 실험할 때만 만들어지기 때문에","mis":"SC5-1-u3-X32"}],"mis":"SC5-1-u3-X32","explanation":["집과 학교를 떠올려요.","용액이 많아요.","과학실에만 있지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#5','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',2,'match','auto','용액과 이용 사례를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C22","difficulty":2,"kind":"match","stem":"용액과 이용 사례를 알맞게 이으세요.","pairs":[{"l":"손 소독제","r":"손에 묻은 세균을 제거한다"},{"l":"식물 영양제","r":"양분이 녹아 있어 식물의 성장을 돕는다"},{"l":"간장","r":"음식의 간을 맞춘다"},{"l":"링거액","r":"병을 치료하는 데 이용한다"}],"mis":"SC5-1-u3-X33","explanation":["하나씩 떠올려요.","손, 식물, 음식, 병원이에요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#6','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C23',2,'mc','auto','고른 용액을 스마트 기기로 조사할 때 무엇을 중심으로 검색하면 좋은가요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"mc","stem":"고른 용액을 스마트 기기로 조사할 때 무엇을 중심으로 검색하면 좋은가요?","options":[{"t":"쓰임새, 이용 장소, 성질","correct":true},{"t":"값이 가장 비싼 상품","mis":"SC5-1-u3-X35"},{"t":"광고에 나온 사람","mis":"SC5-1-u3-X35"},{"t":"친구가 쓴 글 그대로","mis":"SC5-1-u3-X35"}],"explanation":["용액에 대해 알고 싶어요.","어디에, 어떻게 쓰나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#7','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C23',2,'mc','auto','조사하던 중 스마트 기기에서 열이 나요. 어떻게 해야 하나요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"mc","stem":"조사하던 중 스마트 기기에서 열이 나요. 어떻게 해야 하나요?","options":[{"t":"즉시 사용을 멈추고 선생님께 알린다","correct":true},{"t":"조사가 끝날 때까지 계속 쓴다","mis":"SC5-1-u3-X35"},{"t":"물을 부어 식힌다","mis":"SC5-1-u3-X35"},{"t":"세게 흔들어 열을 뺀다","mis":"SC5-1-u3-X35"}],"explanation":["안전이 먼저예요.","멈추고 알려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#8','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C23',2,'blank','auto','「조사한 자료를 공유할 때는 자료의 (    )를 밝힙니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"blank","stem":"「조사한 자료를 공유할 때는 자료의 (    )를 밝힙니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"출처","correct":true},{"t":"값","mis":"SC5-1-u3-X35"},{"t":"무게","mis":"SC5-1-u3-X35"},{"t":"색깔","mis":"SC5-1-u3-X35"}],"explanation":["어디에서 가져왔나요?","자료가 나온 곳이에요.","출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#9','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',2,'error','auto','생활 속 용액을 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X34','SC5-1-u3-X33']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C22","difficulty":2,"kind":"error","stem":"생활 속 용액을 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「용액이니까 모두 마셔도 괜찮아.」","correct":true,"mis_target":"SC5-1-u3-X34"},{"t":"수빈 — 「손 소독제는 손을 깨끗하게 하는 데 써.」","mis":"SC5-1-u3-X33"},{"t":"주원 — 「식초는 음식의 맛을 조절하는 데 써.」","mis":"SC5-1-u3-X33"}],"explanation":["손 소독제를 마실 수 있나요?","마시면 안 되는 용액이 많아요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_basic#10','sci',5,1,'u3','L07','g5_1_sci_u3_L07_basic','lesson_basic','SC5-1-u3-C22',3,'mc','auto','학교에서 볼 수 있는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X32']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C22","difficulty":3,"kind":"mc","stem":"학교에서 볼 수 있는 용액은 어느 것인가요?","options":[{"t":"교실 앞에 놓인 손 소독제","correct":true},{"t":"나무로 만든 책상","mis":"SC5-1-u3-X32"},{"t":"필통 속 연필","mis":"SC5-1-u3-X32"},{"t":"칠판을 닦는 지우개","mis":"SC5-1-u3-X32"}],"explanation":["녹아 골고루 섞인 것이에요.","액체를 찾아요.","손 소독제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#1','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C23',2,'mc','auto','생활 속 용액을 조사하고 공유하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"mc","stem":"생활 속 용액을 조사하고 공유하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢ → ㉤","correct":true},{"t":"㉣ → ㉡ → ㉤ → ㉠ → ㉢","mis":"SC5-1-u3-X35"},{"t":"㉡ → ㉠ → ㉣ → ㉤ → ㉢","mis":"SC5-1-u3-X35"},{"t":"㉤ → ㉡ → ㉣ → ㉠ → ㉢","mis":"SC5-1-u3-X35"}],"explanation":["경험 이야기가 먼저예요.","고르고 조사해요.","정리한 다음 공유해요."],"asset":{"type":"passage","lines":["㉠ 고른 용액의 성질과 이용 사례를 스마트 기기로 조사한다.","㉡ 용액 그림 카드를 보며 용액과 관련된 경험을 이야기한다.","㉢ 조사한 내용을 표에 정리한다.","㉣ 용액을 한 가지 고른다.","㉤ 정리한 내용을 공유 플랫폼에 올린다."],"title":"생활 속 용액 조사(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#2','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C23',2,'ox','auto','친구 얼굴이 나온 사진을 허락 없이 공유 플랫폼에 올려도 돼요.',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"ox","stem":"친구 얼굴이 나온 사진을 허락 없이 공유 플랫폼에 올려도 돼요.","answer":"X","reason_options":[{"t":"다른 사람의 얼굴이 드러나는 사진은 허락 없이 쓰면 안 되기 때문에","correct":true},{"t":"공유 플랫폼은 우리 반만 보니 괜찮기 때문에","mis":"SC5-1-u3-X35"}],"mis":"SC5-1-u3-X35","explanation":["친구의 마음을 생각해요.","허락이 필요해요.","올리면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#3','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C22',3,'mc','auto','화분의 식물이 잘 자라지 않을 때 쓰는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X33']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C22","difficulty":3,"kind":"mc","stem":"화분의 식물이 잘 자라지 않을 때 쓰는 용액은 어느 것인가요?","options":[{"t":"식물 영양제","correct":true},{"t":"손 소독제","mis":"SC5-1-u3-X33"},{"t":"구강 청결제","mis":"SC5-1-u3-X33"},{"t":"식초","mis":"SC5-1-u3-X33"}],"explanation":["식물에 양분이 필요해요.","화분에 꽂아요.","식물 영양제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#4','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C22',3,'mc','auto','링거액에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X33','SC5-1-u3-X34']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C22","difficulty":3,"kind":"mc","stem":"링거액에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"포도당 등이 녹아 있어 병을 치료하는 데 이용한다","correct":true},{"t":"짠맛이 나서 음식의 간을 맞춘다","mis":"SC5-1-u3-X33"},{"t":"손에 묻은 세균을 제거한다","mis":"SC5-1-u3-X33"},{"t":"누구나 음료처럼 마셔도 된다","mis":"SC5-1-u3-X34"}],"explanation":["수액이라고도 해요.","병원에서 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#5','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C23',3,'error','auto','조사를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C23","difficulty":3,"kind":"error","stem":"조사를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「친구가 조사한 내용을 그대로 베껴 쓰면 빨라.」","correct":true,"mis_target":"SC5-1-u3-X35"},{"t":"나윤 — 「조사한 자료의 출처를 밝히자.」","mis":"SC5-1-u3-X35"},{"t":"지후 — 「간장의 쓰임새와 성질을 중심으로 검색하자.」","mis":"SC5-1-u3-X35"}],"explanation":["스스로 조사해야 해요.","베끼면 안 돼요.","태윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#6','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C22',3,'mc','auto','용액을 상황과 용도에 맞게 이용한 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X33','SC5-1-u3-X34']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C22","difficulty":3,"kind":"mc","stem":"용액을 상황과 용도에 맞게 이용한 예로 알맞은 것은 어느 것인가요?","options":[{"t":"요리할 때 간장으로 간을 맞춘다","correct":true},{"t":"손에 묻은 세균을 없애려고 간장을 바른다","mis":"SC5-1-u3-X33"},{"t":"화분에 식초를 꽂아 양분을 준다","mis":"SC5-1-u3-X33"},{"t":"구강 청결제를 음료처럼 마신다","mis":"SC5-1-u3-X34"}],"explanation":["상황과 용액을 짝지어요.","간장은 요리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#7','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C23',3,'mc','auto','우리 모둠 조사표에서 고쳐야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X35','SC5-1-u3-X34']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C23","difficulty":3,"kind":"mc","stem":"우리 모둠 조사표에서 고쳐야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료의 출처를 밝혀 적는다","correct":true},{"t":"이용 사례 칸을 지운다","mis":"SC5-1-u3-X35"},{"t":"성질 칸을 비워 둔다","mis":"SC5-1-u3-X35"},{"t":"직접 맛본 느낌을 적는다","mis":"SC5-1-u3-X34"}],"explanation":["빈칸을 찾아요.","어디서 가져왔나요?","출처를 적어요."],"asset":{"type":"passage","lines":["용액 — 유리 세정제","성질 — 오염 물질을 없애는 성분이 녹아 있다.","이용 사례 — 창문이나 거울을 닦을 때 쓴다.","자료의 출처 — (비어 있음)"],"title":"우리 모둠 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#8','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C22',4,'mc','auto','「용액은 실험실에만 있어.」라고 생각하는 친구를 설득하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X32','SC5-1-u3-X34']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C22","difficulty":4,"kind":"mc","stem":"「용액은 실험실에만 있어.」라고 생각하는 친구를 설득하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"집과 학교에서 쓰는 손 소독제, 식초, 간장 같은 용액을 찾아 보여 준다","correct":true},{"t":"과학실의 비커만 모아 보여 준다","mis":"SC5-1-u3-X32"},{"t":"여러 용액을 맛보게 한다","mis":"SC5-1-u3-X34"},{"t":"용액이 아닌 물건만 모아 보여 준다","mis":"SC5-1-u3-X32"}],"explanation":["주변에서 찾아요.","생활 속 용액이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#9','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C22',4,'mc','auto','스포츠 음료가 용액인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X08','SC5-1-u3-X34','SC5-1-u3-X32']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C22","difficulty":4,"kind":"mc","stem":"스포츠 음료가 용액인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 물질이 물에 녹아 골고루 섞여 있어 뜨거나 가라앉는 것이 없기 때문에","correct":true},{"t":"병에 담겨 섞여 있기 때문에","mis":"SC5-1-u3-X08"},{"t":"마실 수 있기 때문에","mis":"SC5-1-u3-X34"},{"t":"가게에서 팔기 때문에","mis":"SC5-1-u3-X32"}],"explanation":["용액의 뜻을 떠올려요.","녹아 골고루 섞였어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L07_challenge#10','sci',5,1,'u3','L07','g5_1_sci_u3_L07_challenge','lesson_challenge','SC5-1-u3-C22',4,'essay','teacher','일상생활에서 이용하는 용액 두 가지를 골라 각각 어떤 상황에서 이용하는지 쓰고, 용액을 조사하고 공유할 때 지켜야 할 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C22","difficulty":4,"kind":"essay","stem":"일상생활에서 이용하는 용액 두 가지를 골라 각각 어떤 상황에서 이용하는지 쓰고, 용액을 조사하고 공유할 때 지켜야 할 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 손 소독제는 밖에 나갔다 온 뒤 손에 묻은 세균을 없앨 때 이용한다. 식초는 음식에 넣어 신맛을 더하거나 맛을 조절할 때 이용한다. 조사한 자료는 출처를 밝히고, 다른 사람의 얼굴이 드러나는 사진은 허락 없이 쓰지 않는다.","scoring_points":["용액 두 가지와 이용 상황을 바르게 짝지었는가","출처 밝히기를 썼는가","사진 허락·기기 안전 등 다른 지킬 점을 썼는가"]},"explanation":["주변 용액을 떠올려요.","상황을 함께 써요.","지킬 점을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#1','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',1,'mc','auto','디지털 자료를 만들 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SC5-1-u3-X39']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C24","difficulty":1,"kind":"mc","stem":"디지털 자료를 만들 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"모둠에서 소개할 용액을 한 가지 정한다","correct":true},{"t":"다른 모둠의 자료에 댓글을 단다","mis":"SC5-1-u3-X39"},{"t":"누리망에 자료를 올려 공유한다","mis":"SC5-1-u3-X39"},{"t":"우리 모둠의 자료로 필요성을 소개한다","mis":"SC5-1-u3-X39"}],"explanation":["무엇을 알릴지 정해요.","계획이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#2','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',1,'mc','auto','디지털 자료를 만들 때 가장 중요한 것은 어느 것인가요?',ARRAY['SC5-1-u3-X36','SC5-1-u3-X37']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C24","difficulty":1,"kind":"mc","stem":"디지털 자료를 만들 때 가장 중요한 것은 어느 것인가요?","options":[{"t":"용액의 필요성이 드러나도록 만든다","correct":true},{"t":"화면을 최대한 화려하게 꾸민다","mis":"SC5-1-u3-X36"},{"t":"조사한 내용을 하나도 빠짐없이 모두 적는다","mis":"SC5-1-u3-X37"},{"t":"다른 모둠보다 무조건 빨리 만든다","mis":"SC5-1-u3-X36"}],"explanation":["무엇을 알리는 자료인가요?","필요성이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#3','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',1,'sa','auto','「다른 모둠 자료에 댓글을 쓸 때는 바르고 □□ 말을 씁니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C24","difficulty":1,"kind":"sa","stem":"「다른 모둠 자료에 댓글을 쓸 때는 바르고 □□ 말을 씁니다.」 □□에 알맞은 말을 쓰세요.","answer":["고운"],"explanation":["듣기 좋은 말이에요.","두 글자예요.","바르고 고운 말이에요."],"mis":"SC5-1-u3-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#4','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C25',1,'ox','auto','해양학 연구원은 바닷물의 온도나 염분을 조사해요.',ARRAY['SC5-1-u3-X40']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C25","difficulty":1,"kind":"ox","stem":"해양학 연구원은 바닷물의 온도나 염분을 조사해요.","answer":"O","reason_options":[{"t":"바다는 여러 가지 물질이 녹아 있는 용액이기 때문에","correct":true},{"t":"해양학 연구원은 용액과 관계없는 일만 하기 때문에","mis":"SC5-1-u3-X40"}],"mis":"SC5-1-u3-X40","explanation":["바다를 떠올려요.","바닷물도 용액이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#5','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C25',2,'match','auto','직업과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C25","difficulty":2,"kind":"match","stem":"직업과 하는 일을 알맞게 이으세요.","pairs":[{"l":"도시 농업 관리사","r":"수경 재배에 쓰는 배양액을 개발한다"},{"l":"식품 공학 기술자","r":"원하는 맛과 영양의 음료를 연구한다"},{"l":"해양학 연구원","r":"바닷물의 온도와 염분을 조사한다"}],"mis":"SC5-1-u3-X40","explanation":["직업 이름에 힌트가 있어요.","농업, 식품, 해양이에요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#6','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',2,'mc','auto','「비눗물이 사라진다면?」 자료가 전하려는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"mc","stem":"「비눗물이 사라진다면?」 자료가 전하려는 것은 어느 것인가요?","options":[{"t":"비눗물이 없으면 불편해지므로 우리 생활에 꼭 필요하다는 것","correct":true},{"t":"비눗물이 다른 용액보다 값이 비싸다는 것","mis":"SC5-1-u3-X37"},{"t":"비눗물은 위험하므로 쓰지 말아야 한다는 것","mis":"SC5-1-u3-X37"},{"t":"비눗방울 놀이를 더 자주 해야 한다는 것","mis":"SC5-1-u3-X37"}],"explanation":["사라진다면 어떨까요?","불편해져요.","필요하다는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#7','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',2,'mc','auto','용액의 필요성이 잘 드러나게 하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X36','SC5-1-u3-X38']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"mc","stem":"용액의 필요성이 잘 드러나게 하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"용액이 없을 경우 불편한 점을 보여 준다","correct":true},{"t":"용액 이름만 크게 쓴다","mis":"SC5-1-u3-X37"},{"t":"화려한 무늬로 화면을 가득 채운다","mis":"SC5-1-u3-X36"},{"t":"다른 모둠 자료를 깎아내린다","mis":"SC5-1-u3-X38"}],"explanation":["없다면 어떨지 떠올려요.","불편함을 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#8','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',2,'blank','auto','「디지털 자료에는 필요한 내용을 (    )하여 넣습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X36']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"blank","stem":"「디지털 자료에는 필요한 내용을 (    )하여 넣습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"요약","correct":true},{"t":"모두 복사","mis":"SC5-1-u3-X37"},{"t":"화려하게 장식","mis":"SC5-1-u3-X36"},{"t":"아무렇게나 배치","mis":"SC5-1-u3-X37"}],"explanation":["한눈에 들어오게 해요.","짧게 줄여요.","요약이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#9','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C24',2,'error','auto','자료를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X38']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"error","stem":"자료를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규민 — 「다른 모둠 자료는 별로라고 댓글을 달자.」","correct":true,"mis_target":"SC5-1-u3-X38"},{"t":"연서 — 「잘한 점을 댓글로 전하자.」","mis":"SC5-1-u3-X38"},{"t":"하람 — 「모둠원의 의견을 존중하자.」","mis":"SC5-1-u3-X38"}],"explanation":["댓글은 어떻게 쓰나요?","바르고 고운 말이에요.","규민이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_basic#10','sci',5,1,'u3','L08','g5_1_sci_u3_L08_basic','lesson_basic','SC5-1-u3-C25',3,'mc','auto','식품 공학 기술자가 음료를 만들 때 확인하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X40','SC5-1-u3-X41']::text[],false,'{"seq":10,"concept":"SC5-1-u3-C25","difficulty":3,"kind":"mc","stem":"식품 공학 기술자가 음료를 만들 때 확인하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"녹이는 물질의 종류와 순서, 물의 온도, 용액의 진하기","correct":true},{"t":"바닷물의 염분과 바다 생물","mis":"SC5-1-u3-X40"},{"t":"수경 재배에 쓰는 배양액만","mis":"SC5-1-u3-X40"},{"t":"용액과 관계없는 것만","mis":"SC5-1-u3-X41"}],"explanation":["음료도 용액이에요.","녹이는 것을 확인해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#1','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',2,'mc','auto','디지털 자료를 만들고 나누는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X39']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"mc","stem":"디지털 자료를 만들고 나누는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢ → ㉤","correct":true},{"t":"㉠ → ㉡ → ㉣ → ㉤ → ㉢","mis":"SC5-1-u3-X39"},{"t":"㉢ → ㉡ → ㉣ → ㉠ → ㉤","mis":"SC5-1-u3-X39"},{"t":"㉡ → ㉠ → ㉤ → ㉣ → ㉢","mis":"SC5-1-u3-X39"}],"explanation":["계획하기가 먼저예요.","만든 다음 공유해요.","댓글은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 디자인 플랫폼으로 디지털 자료를 만든다.","㉡ 모둠에서 소개할 용액을 한 가지 정한다.","㉢ 완성한 자료를 누리망에 올려 공유한다.","㉣ 그 용액이 필요한 상황을 토의한다.","㉤ 다른 모둠 자료를 보고 잘한 점을 댓글로 단다."],"title":"디지털 자료 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#2','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',2,'ox','auto','디지털 자료는 크고 화려하게 꾸밀수록 좋은 자료예요.',ARRAY['SC5-1-u3-X36']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"ox","stem":"디지털 자료는 크고 화려하게 꾸밀수록 좋은 자료예요.","answer":"X","reason_options":[{"t":"꾸미는 것보다 용액의 필요성을 옳게 설명하는 것이 더 중요하기 때문에","correct":true},{"t":"눈에 띄는 자료가 가장 좋은 자료이기 때문에","mis":"SC5-1-u3-X36"}],"mis":"SC5-1-u3-X36","explanation":["무엇이 중요한가요?","필요성이에요.","화려함이 먼저가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#3','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',3,'mc','auto','모둠별 자료 계획에서 고쳐야 할 계획끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X35']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C24","difficulty":3,"kind":"mc","stem":"모둠별 자료 계획에서 고쳐야 할 계획끼리 묶은 것은 어느 것인가요?","options":[{"t":"②, ④","correct":true},{"t":"①, ③","mis":"SC5-1-u3-X37"},{"t":"①, ②","mis":"SC5-1-u3-X37"},{"t":"③, ④","mis":"SC5-1-u3-X35"}],"explanation":["필요성이 빠진 것을 찾아요.","허락 없는 사진도 찾아요.","②와 ④예요."],"asset":{"type":"passage","lines":["① 손 소독제가 사라진다면 어떤 일이 생길지 그림으로 보여 준다.","② 용액 이름만 크게 쓰고 왜 필요한지는 넣지 않는다.","③ 식초가 음식의 맛을 조절한다는 성질을 자료에 담는다.","④ 친구 얼굴이 나온 사진을 허락 없이 자료에 넣는다."],"title":"모둠별 자료 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#4','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C25',3,'mc','auto','수경 재배에서 배양액이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X40']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C25","difficulty":3,"kind":"mc","stem":"수경 재배에서 배양액이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"흙처럼 식물에 필요한 양분을 공급한다","correct":true},{"t":"식물에 묻은 세균을 소독한다","mis":"SC5-1-u3-X40"},{"t":"바닷물의 염분을 잰다","mis":"SC5-1-u3-X40"},{"t":"음료의 맛을 낸다","mis":"SC5-1-u3-X40"}],"explanation":["물에서 식물을 키워요.","흙 대신이에요.","양분을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#5','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C25',3,'error','auto','용액을 연구하는 사람들에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X41','SC5-1-u3-X40']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C25","difficulty":3,"kind":"error","stem":"용액을 연구하는 사람들에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시윤 — 「용액을 연구하는 일은 과학자만 할 수 있어.」","correct":true,"mis_target":"SC5-1-u3-X41"},{"t":"다현 — 「농업, 식품, 해양 등 여러 분야에서 용액을 연구해.」","mis":"SC5-1-u3-X41"},{"t":"우진 — 「도시 농업 관리사는 배양액을 개발해.」","mis":"SC5-1-u3-X40"}],"explanation":["여러 직업을 떠올려요.","분야가 다양해요.","시윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#6','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',3,'mc','auto','구강 청결제를 알리는 자료의 제목으로 필요성이 가장 잘 드러나는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X36','SC5-1-u3-X38']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C24","difficulty":3,"kind":"mc","stem":"구강 청결제를 알리는 자료의 제목으로 필요성이 가장 잘 드러나는 것은 어느 것인가요?","options":[{"t":"「구강 청결제가 없다면? 입안을 깨끗하게 지키기 어려워요」","correct":true},{"t":"「구강 청결제」","mis":"SC5-1-u3-X37"},{"t":"「반짝반짝 가장 화려한 자료」","mis":"SC5-1-u3-X36"},{"t":"「다른 모둠보다 우리가 최고」","mis":"SC5-1-u3-X38"}],"explanation":["없을 때의 불편함이에요.","제목에 필요성이 있나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#7','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',3,'mc','auto','그림 도구로 종이에 만든 자료를 공유하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X39','SC5-1-u3-X35']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C24","difficulty":3,"kind":"mc","stem":"그림 도구로 종이에 만든 자료를 공유하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"스마트 기기의 사진 기능으로 찍어 공유 플랫폼에 올린다","correct":true},{"t":"종이 자료는 공유하지 않는다","mis":"SC5-1-u3-X39"},{"t":"다른 모둠 자료에 우리 이름을 써서 올린다","mis":"SC5-1-u3-X35"},{"t":"댓글부터 달고 자료는 나중에 만든다","mis":"SC5-1-u3-X39"}],"explanation":["종이도 나눌 수 있어요.","사진을 찍어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#8','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',4,'mc','auto','링거액의 필요성을 알리는 자료에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X34','SC5-1-u3-X36']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C24","difficulty":4,"kind":"mc","stem":"링거액의 필요성을 알리는 자료에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"링거액이 없다면 병원에서 아픈 사람을 치료하기 어려워질 수 있다는 내용","correct":true},{"t":"링거액 상자의 색깔","mis":"SC5-1-u3-X37"},{"t":"링거액은 누구나 마셔도 된다는 내용","mis":"SC5-1-u3-X34"},{"t":"반짝이 효과만 가득한 화면","mis":"SC5-1-u3-X36"}],"explanation":["없을 때의 불편함이에요.","병원에서 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#9','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C25',4,'mc','auto','해양학 연구원이 바닷물의 온도나 염분을 조사하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X34','SC5-1-u3-X40','SC5-1-u3-X41']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C25","difficulty":4,"kind":"mc","stem":"해양학 연구원이 바닷물의 온도나 염분을 조사하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"해양 생태계에 미치는 영향을 알아보려고","correct":true},{"t":"바닷물을 마실 수 있는지 맛보려고","mis":"SC5-1-u3-X34"},{"t":"바닷물은 용액이 아니라는 것을 밝히려고","mis":"SC5-1-u3-X40"},{"t":"바다는 우리 생활과 관계없다는 것을 보이려고","mis":"SC5-1-u3-X41"}],"explanation":["바다 생물을 떠올려요.","바닷물이 바뀌면 영향을 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_L08_challenge#10','sci',5,1,'u3','L08','g5_1_sci_u3_L08_challenge','lesson_challenge','SC5-1-u3-C24',4,'essay','teacher','모둠에서 소개할 용액 하나를 골라, 그 용액의 필요성을 알리는 디지털 자료 계획을 쓰세요. 용액이 없을 때 불편한 점, 자료에 담을 내용, 자료를 나눌 때 지킬 점을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C24","difficulty":4,"kind":"essay","stem":"모둠에서 소개할 용액 하나를 골라, 그 용액의 필요성을 알리는 디지털 자료 계획을 쓰세요. 용액이 없을 때 불편한 점, 자료에 담을 내용, 자료를 나눌 때 지킬 점을 넣으세요.","answer_guide":{"answer":"예: 손 소독제를 고른다. 손 소독제가 없다면 밖에 나갔다 온 뒤 손에 묻은 세균을 쉽게 없애기 어렵고 세균이 옮겨질 수 있다. 「손 소독제가 사라진다면?」이라는 제목의 포스터에 이 불편함을 그림과 짧은 글로 요약해 담는다. 다른 모둠 자료에는 잘한 점을 바르고 고운 말로 댓글로 단다.","scoring_points":["없을 때의 불편한 점을 썼는가","필요성이 드러나는 내용과 종류를 썼는가","바른 댓글 등 지킬 점을 썼는가"]},"explanation":["용액 하나를 골라요.","없을 때를 떠올려요.","나눌 때의 약속을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#1','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C5',1,'mc','auto','이슬반이 배운 낱말 가운데 「물질이 다른 물질에 녹아 골고루 섞이는 현상」을 가리키는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X06']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C5","difficulty":1,"kind":"mc","stem":"이슬반이 배운 낱말 가운데 「물질이 다른 물질에 녹아 골고루 섞이는 현상」을 가리키는 것은 어느 것인가요?","options":[{"t":"용해","correct":true},{"t":"용액","mis":"SC5-1-u3-X06"},{"t":"용질","mis":"SC5-1-u3-X06"},{"t":"용매","mis":"SC5-1-u3-X06"}],"explanation":["현상의 이름이에요.","일어나는 일이에요.","용해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#2','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C5',1,'sa','auto','「설탕물에서 물처럼 다른 물질을 녹이는 물질을 □□라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C5","difficulty":1,"kind":"sa","stem":"「설탕물에서 물처럼 다른 물질을 녹이는 물질을 □□라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["용매"],"explanation":["녹이는 쪽이에요.","두 글자예요.","용매예요."],"mis":"SC5-1-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#3','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C3',1,'ox','auto','실험에 쓰는 물질은 맛보아서 확인해요.',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C3","difficulty":1,"kind":"ox","stem":"실험에 쓰는 물질은 맛보아서 확인해요.","answer":"X","reason_options":[{"t":"실험에 쓰는 물질은 몸에 해로울 수 있어 맛보지 않기 때문에","correct":true},{"t":"맛을 보아야 정확히 알 수 있기 때문에","mis":"SC5-1-u3-X03"}],"mis":"SC5-1-u3-X03","explanation":["실험 약속이에요.","맛보지 않아요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#4','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C8',1,'mc','auto','각설탕이 물에 녹는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X13','SC5-1-u3-X11']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C8","difficulty":1,"kind":"mc","stem":"각설탕이 물에 녹는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"크기가 점점 작아져 보이지 않게 된다","correct":true},{"t":"크기 그대로 바닥에 가라앉는다","mis":"SC5-1-u3-X13"},{"t":"크기가 점점 커진다","mis":"SC5-1-u3-X13"},{"t":"넣자마자 사라진다","mis":"SC5-1-u3-X11"}],"explanation":["녹는 모습을 떠올려요.","점점 작아져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#5','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C1',1,'mc','auto','이슬반 일지 ①로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C1","difficulty":1,"kind":"mc","stem":"이슬반 일지 ①로 알 수 있는 것은 어느 것인가요?","options":[{"t":"물질마다 물에서 변하는 모습이 다르다","correct":true},{"t":"모든 물질이 똑같이 거품을 낸다","mis":"SC5-1-u3-X01"},{"t":"물질은 물에서 변하지 않는다","mis":"SC5-1-u3-X01"},{"t":"거품을 내는 물질만 물에서 변한다","mis":"SC5-1-u3-X01"}],"explanation":["두 모둠을 견줘요.","거품과 풀어짐이에요.","서로 달라요."],"asset":{"type":"passage","lines":["1모둠 발포 바이타민 — 거품을 많이 내며 빠르게 작아졌다.","2모둠 고체 치약 — 천천히 풀어지며 뿌옇게 퍼졌다.","3모둠 — 한 친구가 알약의 맛이 궁금하다며 맛보려다 주의를 받았다.","영상에 제목과 자막을 넣어 함께 보았다."],"title":"이슬반 탐구 일지 ① 물질의 변신"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#6','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C2',1,'blank','auto','「물질이 변하는 모습은 스마트 기기로 (    )을 찍어 남깁니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C2","difficulty":1,"kind":"blank","stem":"「물질이 변하는 모습은 스마트 기기로 (    )을 찍어 남깁니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"동영상","correct":true},{"t":"그림자","mis":"SC5-1-u3-X02"},{"t":"소리만","mis":"SC5-1-u3-X02"},{"t":"무게","mis":"SC5-1-u3-X02"}],"explanation":["움직이는 모습이에요.","영상이에요.","동영상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#7','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C11',1,'mc','auto','무게 비교 실험에서 각설탕을 집어 물에 넣을 때 쓰는 도구는 어느 것인가요?',ARRAY['SC5-1-u3-X14']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C11","difficulty":1,"kind":"mc","stem":"무게 비교 실험에서 각설탕을 집어 물에 넣을 때 쓰는 도구는 어느 것인가요?","options":[{"t":"핀셋","correct":true},{"t":"눈금실린더","mis":"SC5-1-u3-X14"},{"t":"전자저울","mis":"SC5-1-u3-X14"},{"t":"페트리 접시","mis":"SC5-1-u3-X14"}],"explanation":["집는 도구예요.","손으로 넣지 않아요.","핀셋이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#8','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C6',1,'mc','auto','설탕물이나 소금물 같은 용액의 성질로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X09','SC5-1-u3-X08']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C6","difficulty":1,"kind":"mc","stem":"설탕물이나 소금물 같은 용액의 성질로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 부분이나 색깔이나 맛 등의 성질이 같다","correct":true},{"t":"아래쪽으로 갈수록 색깔이 진하다","mis":"SC5-1-u3-X09"},{"t":"시간이 지나면 가라앉는 것이 생긴다","mis":"SC5-1-u3-X09"},{"t":"섞여 있기만 하면 용액이다","mis":"SC5-1-u3-X08"}],"explanation":["설탕물을 떠올려요.","어디나 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#9','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C5',2,'mc','auto','이슬반 일지 ②의 설탕물에서 용질은 어느 것인가요?',ARRAY['SC5-1-u3-X07','SC5-1-u3-X06']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C5","difficulty":2,"kind":"mc","stem":"이슬반 일지 ②의 설탕물에서 용질은 어느 것인가요?","options":[{"t":"설탕","correct":true},{"t":"물","mis":"SC5-1-u3-X07"},{"t":"설탕물","mis":"SC5-1-u3-X06"},{"t":"유리병","mis":"SC5-1-u3-X06"}],"explanation":["녹는 쪽이에요.","물에 녹은 것이에요.","설탕이에요."],"asset":{"type":"passage","lines":["설탕 — 저으니 보이지 않게 되었다.","가루 바이타민 — 저으니 보이지 않게 되었다.","탄산 칼슘 — 뿌옇다가 바닥에 가라앉았다.","후춧가루 — 저어도 그대로 떠다녔다.","흙 — 흙탕물이 되었다가 시간이 지나자 흙이 가라앉았다."],"title":"이슬반 탐구 일지 ② 물에 넣어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#10','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C12',2,'sa','auto','이슬반 일지 ④에서 소금은 몇 숟가락까지 모두 용해되었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C12","difficulty":2,"kind":"sa","stem":"이슬반 일지 ④에서 소금은 몇 숟가락까지 모두 용해되었는지 쓰세요.","answer":["5","5숟가락","5 숟가락","다섯 숟가락","다섯"],"explanation":["여섯째부터 남았어요.","그 앞까지예요.","다섯 숟가락이에요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"},"mis":"SC5-1-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#11','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C4',2,'ox','auto','물에 넣은 물질은 오래 저으면 무엇이든 다 녹아요.',ARRAY['SC5-1-u3-X05']::text[],false,'{"seq":11,"concept":"SC5-1-u3-C4","difficulty":2,"kind":"ox","stem":"물에 넣은 물질은 오래 저으면 무엇이든 다 녹아요.","answer":"X","reason_options":[{"t":"탄산 칼슘이나 후춧가루처럼 물에 녹지 않는 물질이 있기 때문에","correct":true},{"t":"녹지 않는 것은 모두 덜 저었기 때문이므로","mis":"SC5-1-u3-X05"}],"mis":"SC5-1-u3-X05","explanation":["이슬반 일지 ②를 떠올려요.","녹지 않는 것이 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#12','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C7',2,'mc','auto','세 물질 실험에서 약숟가락을 구분해 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X10','SC5-1-u3-X03']::text[],false,'{"seq":12,"concept":"SC5-1-u3-C7","difficulty":2,"kind":"mc","stem":"세 물질 실험에서 약숟가락을 구분해 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물질이 서로 섞이지 않게 하려고","correct":true},{"t":"물질을 더 빨리 녹이려고","mis":"SC5-1-u3-X10"},{"t":"물질의 무게를 재려고","mis":"SC5-1-u3-X10"},{"t":"물질을 맛보려고","mis":"SC5-1-u3-X03"}],"explanation":["같은 숟가락이면 어떨까요?","섞여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#13','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C5',2,'match','auto','설탕물을 보고 낱말과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u3-C5","difficulty":2,"kind":"match","stem":"설탕물을 보고 낱말과 알맞은 것을 이으세요.","pairs":[{"l":"용매","r":"물"},{"l":"용질","r":"설탕"},{"l":"용액","r":"설탕물"},{"l":"용해","r":"설탕이 물에 녹아 골고루 섞이는 일"}],"mis":"SC5-1-u3-X07","explanation":["설탕물에서 찾아요.","녹이는 것과 녹는 것이에요.","용해는 일어나는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#14','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C8',2,'mc','auto','각설탕이 물에 용해되는 과정을 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u3-X13','SC5-1-u3-X12']::text[],false,'{"seq":14,"concept":"SC5-1-u3-C8","difficulty":2,"kind":"mc","stem":"각설탕이 물에 용해되는 과정을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"작아짐 → 보이지 않을 만큼 작아짐 → 골고루 섞여 용액이 됨","correct":true},{"t":"골고루 섞임 → 작아짐 → 보이지 않음","mis":"SC5-1-u3-X13"},{"t":"그대로 가라앉음 → 물로 변함 → 사라짐","mis":"SC5-1-u3-X13"},{"t":"보이지 않음 → 사라짐 → 가벼워짐","mis":"SC5-1-u3-X12"}],"explanation":["녹는 차례를 떠올려요.","작아지고 안 보이고 섞여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#15','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C6',2,'error','auto','용액에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X08','SC5-1-u3-X09']::text[],false,'{"seq":15,"concept":"SC5-1-u3-C6","difficulty":2,"kind":"error","stem":"용액에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세린 — 「후춧가루를 넣은 물도 섞여 있으니 용액이야.」","correct":true,"mis_target":"SC5-1-u3-X08"},{"t":"유찬 — 「소금물은 어느 부분이나 맛이 같아.」","mis":"SC5-1-u3-X09"},{"t":"하윤 — 「설탕물에는 가라앉는 것이 없어.」","mis":"SC5-1-u3-X09"}],"explanation":["후춧가루는 녹았나요?","떠다녀요.","세린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#16','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C3',2,'mc','auto','이슬반 일지 ①의 3모둠 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":16,"concept":"SC5-1-u3-C3","difficulty":2,"kind":"mc","stem":"이슬반 일지 ①의 3모둠 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"실험에 쓰는 물질은 맛보지 않아야 해","correct":true},{"t":"조금만 맛보는 것은 괜찮아","mis":"SC5-1-u3-X03"},{"t":"맛을 봐야 변한 모습을 알 수 있어","mis":"SC5-1-u3-X03"},{"t":"물에 넣은 뒤에 맛보면 돼","mis":"SC5-1-u3-X03"}],"explanation":["실험 약속이에요.","맛보지 않아요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 발포 바이타민 — 거품을 많이 내며 빠르게 작아졌다.","2모둠 고체 치약 — 천천히 풀어지며 뿌옇게 퍼졌다.","3모둠 — 한 친구가 알약의 맛이 궁금하다며 맛보려다 주의를 받았다.","영상에 제목과 자막을 넣어 함께 보았다."],"title":"이슬반 탐구 일지 ① 물질의 변신"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#17','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C6',3,'mc','auto','이슬반 일지 ②의 다섯 가지 가운데 용액이 된 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X08','SC5-1-u3-X04']::text[],false,'{"seq":17,"concept":"SC5-1-u3-C6","difficulty":3,"kind":"mc","stem":"이슬반 일지 ②의 다섯 가지 가운데 용액이 된 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"설탕을 넣은 물, 가루 바이타민을 넣은 물","correct":true},{"t":"흙탕물, 후춧가루를 넣은 물","mis":"SC5-1-u3-X08"},{"t":"설탕을 넣은 물, 탄산 칼슘을 넣은 물","mis":"SC5-1-u3-X04"},{"t":"다섯 가지 모두","mis":"SC5-1-u3-X04"}],"explanation":["녹아 골고루 섞였나요?","가라앉거나 뜨는 것이 없어요.","첫 번째예요."],"asset":{"type":"passage","lines":["설탕 — 저으니 보이지 않게 되었다.","가루 바이타민 — 저으니 보이지 않게 되었다.","탄산 칼슘 — 뿌옇다가 바닥에 가라앉았다.","후춧가루 — 저어도 그대로 떠다녔다.","흙 — 흙탕물이 되었다가 시간이 지나자 흙이 가라앉았다."],"title":"이슬반 탐구 일지 ② 물에 넣어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#18','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C5',3,'mc','auto','물에 가루 바이타민을 녹였어요. 용매, 용질, 용액을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X07','SC5-1-u3-X06']::text[],false,'{"seq":18,"concept":"SC5-1-u3-C5","difficulty":3,"kind":"mc","stem":"물에 가루 바이타민을 녹였어요. 용매, 용질, 용액을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"용매 — 물, 용질 — 가루 바이타민, 용액 — 가루 바이타민을 녹인 물","correct":true},{"t":"용매 — 가루 바이타민, 용질 — 물, 용액 — 가루 바이타민을 녹인 물","mis":"SC5-1-u3-X07"},{"t":"용매 — 물, 용질 — 가루 바이타민을 녹인 물, 용액 — 가루 바이타민","mis":"SC5-1-u3-X06"},{"t":"용매 — 가루 바이타민을 녹인 물, 용질 — 물, 용액 — 가루 바이타민","mis":"SC5-1-u3-X06"}],"explanation":["녹이는 것은 물이에요.","녹는 것은 가루예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#19','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C9',3,'ox','auto','같은 양의 물에 각설탕 세 개를 녹인 용액은 한 개를 녹인 용액보다 무거워요.',ARRAY['SC5-1-u3-X15']::text[],false,'{"seq":19,"concept":"SC5-1-u3-C9","difficulty":3,"kind":"ox","stem":"같은 양의 물에 각설탕 세 개를 녹인 용액은 한 개를 녹인 용액보다 무거워요.","answer":"O","reason_options":[{"t":"녹인 용질은 용액 속에 그대로 있어 많이 녹일수록 무게가 늘기 때문에","correct":true},{"t":"녹으면 없어지므로 두 용액의 무게는 같기 때문에","mis":"SC5-1-u3-X15"}],"mis":"SC5-1-u3-X15","explanation":["녹은 설탕은 어디 있나요?","용액 속이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#20','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C10',3,'mc','auto','이슬반 일지 ⑧에서 하람의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X13','SC5-1-u3-X12']::text[],false,'{"seq":20,"concept":"SC5-1-u3-C10","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑧에서 하람의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「녹은 설탕은 용액 속에 그대로 있어서 무게도 같아.」","correct":true},{"t":"「맞아, 안 보이면 없어진 거야.」","mis":"SC5-1-u3-X11"},{"t":"「설탕은 물로 변한 거야.」","mis":"SC5-1-u3-X13"},{"t":"「녹으면 가벼워질 뿐 없어지지는 않아.」","mis":"SC5-1-u3-X12"}],"explanation":["무게 실험을 떠올려요.","그대로 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「녹아서 안 보이면 설탕은 없어진 거야.」","도윤 — 「바닥에 남는 건 언제나 물이 부족해서야.」","서아 — 「물이 차가울수록 더 많이 녹아.」","민호 — 「진한 용액일수록 방울토마토가 가라앉아.」","지우 — 「용액은 과학실에만 있어.」","다온 — 「디지털 자료는 화려할수록 좋아.」"],"title":"이슬반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#21','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C2',3,'mc','auto','막대에 매달지 않고 물질을 비커에 그냥 떨어뜨려 촬영하면 어떤 점이 불편할까요?',ARRAY['SC5-1-u3-X01','SC5-1-u3-X02']::text[],false,'{"seq":21,"concept":"SC5-1-u3-C2","difficulty":3,"kind":"mc","stem":"막대에 매달지 않고 물질을 비커에 그냥 떨어뜨려 촬영하면 어떤 점이 불편할까요?","options":[{"t":"물질이 움직이거나 가라앉아 변하는 모습을 한자리에서 찍기 어렵다","correct":true},{"t":"물질이 물에서 전혀 변하지 않는다","mis":"SC5-1-u3-X01"},{"t":"스마트 기기로 동영상을 찍을 수 없게 된다","mis":"SC5-1-u3-X02"},{"t":"물이 모두 사라진다","mis":"SC5-1-u3-X02"}],"explanation":["막대의 쓰임을 떠올려요.","한자리에 두려고 했어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#22','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C7',3,'mc','auto','친구가 세 물질 실험을 「유리병마다 물의 양을 다르게 하고, 설탕은 두 숟가락, 탄산 칼슘은 한 숟가락 넣는다」로 계획했어요. 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u3-X10','SC5-1-u3-X05','SC5-1-u3-X03']::text[],false,'{"seq":22,"concept":"SC5-1-u3-C7","difficulty":3,"kind":"mc","stem":"친구가 세 물질 실험을 「유리병마다 물의 양을 다르게 하고, 설탕은 두 숟가락, 탄산 칼슘은 한 숟가락 넣는다」로 계획했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"물의 양과 넣는 물질의 양을 모두 같게 한다","correct":true},{"t":"그대로 해도 된다","mis":"SC5-1-u3-X10"},{"t":"탄산 칼슘을 더 많이 넣어 녹게 한다","mis":"SC5-1-u3-X05"},{"t":"맛을 보고 넣을 양을 정한다","mis":"SC5-1-u3-X03"}],"explanation":["공정하게 견줘요.","양을 같게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#23','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C9',4,'mc','auto','이슬반 일지 ③에서 한 모둠이 용해된 뒤 함께 잰 무게를 146 g이라고 적었어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['SC5-1-u3-X12','SC5-1-u3-X14','SC5-1-u3-X11']::text[],false,'{"seq":23,"concept":"SC5-1-u3-C9","difficulty":4,"kind":"mc","stem":"이슬반 일지 ③에서 한 모둠이 용해된 뒤 함께 잰 무게를 146 g이라고 적었어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"용해 전과 후의 무게는 같아야 하므로 빠뜨린 것(빈 접시 등)이 없는지 살피고 다시 잰다","correct":true},{"t":"녹으면 가벼워지므로 맞는 결과다","mis":"SC5-1-u3-X12"},{"t":"결과를 150 g으로 고쳐 적고 넘어간다","mis":"SC5-1-u3-X14"},{"t":"설탕 4 g이 사라졌다고 적는다","mis":"SC5-1-u3-X11"}],"explanation":["무게는 같아야 해요.","10 g이 모자라요.","다시 확인해요."],"asset":{"type":"passage","lines":["용해되기 전: 물이 든 유리병 + 각설탕을 담은 접시 = 150 g","각설탕 한 개 = 4 g, 빈 페트리 접시 = 10 g","각설탕이 모두 용해된 뒤: 설탕물 유리병 + 빈 접시 = ( ? )"],"title":"이슬반 탐구 일지 ③ 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#24','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C6',4,'essay','teacher','이슬반 일지 ②의 다섯 가지를 용액인 것과 용액이 아닌 것으로 나누고, 그렇게 나눈 까닭을 용액의 성질과 이어서 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u3-C6","difficulty":4,"kind":"essay","stem":"이슬반 일지 ②의 다섯 가지를 용액인 것과 용액이 아닌 것으로 나누고, 그렇게 나눈 까닭을 용액의 성질과 이어서 쓰세요.","answer_guide":{"answer":"예: 설탕을 넣은 물과 가루 바이타민을 넣은 물은 용액이다. 물질이 물에 녹아 골고루 섞여 있어 뜨거나 가라앉는 것이 없기 때문이다. 탄산 칼슘을 넣은 물, 후춧가루를 넣은 물, 흙탕물은 용액이 아니다. 탄산 칼슘과 흙은 녹지 않고 가라앉았고 후춧가루는 떠다녔기 때문이다.","scoring_points":["용액인 것 두 가지를 바르게 골랐는가","용액이 아닌 것 세 가지를 바르게 골랐는가","뜨거나 가라앉는 것이 없다는 성질로 까닭을 썼는가"]},"explanation":["녹았는지부터 봐요.","떠 있거나 가라앉은 것을 찾아요.","성질과 이어요."],"asset":{"type":"passage","lines":["설탕 — 저으니 보이지 않게 되었다.","가루 바이타민 — 저으니 보이지 않게 되었다.","탄산 칼슘 — 뿌옇다가 바닥에 가라앉았다.","후춧가루 — 저어도 그대로 떠다녔다.","흙 — 흙탕물이 되었다가 시간이 지나자 흙이 가라앉았다."],"title":"이슬반 탐구 일지 ② 물에 넣어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_a#25','sci',5,1,'u3','','g5_1_sci_u3_review_a','unit_review','SC5-1-u3-C16',4,'essay','teacher','이슬반 일지 ⑤의 결과로 알게 된 점과 남은 백반이 녹은 까닭을 쓰고, 이것을 생활에 이용하는 예를 하나 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u3-C16","difficulty":4,"kind":"essay","stem":"이슬반 일지 ⑤의 결과로 알게 된 점과 남은 백반이 녹은 까닭을 쓰고, 이것을 생활에 이용하는 예를 하나 쓰세요.","answer_guide":{"answer":"예: 물의 양이 같을 때 따뜻한 물에서 백반이 더 많이 용해되었으므로 물의 온도가 높을수록 용질이 더 많이 용해된다는 것을 알 수 있다. 차가운 물 비커를 데우자 물의 온도가 높아져 남은 백반이 녹았다. 생활에서는 옷에 가루 세제가 남으면 헹구는 물의 온도를 높여 녹인다.","scoring_points":["온도가 높을수록 더 많이 녹는다고 썼는가","데워서 녹은 까닭을 온도와 이었는가","생활 속 예를 썼는가"]},"explanation":["두 비커를 견줘요.","데운 까닭이에요.","생활과 이어요."],"asset":{"type":"passage","lines":["같은 양의 물에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 둘째 숟가락부터 바닥에 남았다.","따뜻한 물 — 넷째 숟가락까지 모두 용해되었다.","백반이 남은 차가운 물 비커를 데우니 남은 백반이 녹았다."],"title":"이슬반 탐구 일지 ⑤ 물의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#1','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C4',1,'mc','auto','이슬반 일지 ②에서 물에 녹지 않은 물질끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X04']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C4","difficulty":1,"kind":"mc","stem":"이슬반 일지 ②에서 물에 녹지 않은 물질끼리 묶은 것은 어느 것인가요?","options":[{"t":"탄산 칼슘, 후춧가루","correct":true},{"t":"설탕, 가루 바이타민","mis":"SC5-1-u3-X04"},{"t":"설탕, 탄산 칼슘","mis":"SC5-1-u3-X04"},{"t":"가루 바이타민, 후춧가루","mis":"SC5-1-u3-X04"}],"explanation":["보이지 않게 된 것은 녹았어요.","가라앉거나 떠다닌 것을 찾아요.","탄산 칼슘과 후춧가루예요."],"asset":{"type":"passage","lines":["설탕 — 저으니 보이지 않게 되었다.","가루 바이타민 — 저으니 보이지 않게 되었다.","탄산 칼슘 — 뿌옇다가 바닥에 가라앉았다.","후춧가루 — 저어도 그대로 떠다녔다.","흙 — 흙탕물이 되었다가 시간이 지나자 흙이 가라앉았다."],"title":"이슬반 탐구 일지 ② 물에 넣어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#2','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C9',1,'sa','auto','이슬반 일지 ③에서 각설탕이 모두 용해된 뒤 설탕물 유리병과 빈 접시를 함께 잰 무게는 몇 g일까요?','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C9","difficulty":1,"kind":"sa","stem":"이슬반 일지 ③에서 각설탕이 모두 용해된 뒤 설탕물 유리병과 빈 접시를 함께 잰 무게는 몇 g일까요?","answer":["150","150 g","150g"],"explanation":["무게가 변할까요?","용해 전과 같아요.","150 g이에요."],"asset":{"type":"passage","lines":["용해되기 전: 물이 든 유리병 + 각설탕을 담은 접시 = 150 g","각설탕 한 개 = 4 g, 빈 페트리 접시 = 10 g","각설탕이 모두 용해된 뒤: 설탕물 유리병 + 빈 접시 = ( ? )"],"title":"이슬반 탐구 일지 ③ 무게 재기"},"mis":"SC5-1-u3-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#3','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C6',1,'ox','auto','흙탕물은 용액이에요.',ARRAY['SC5-1-u3-X08']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C6","difficulty":1,"kind":"ox","stem":"흙탕물은 용액이에요.","answer":"X","reason_options":[{"t":"흙이 녹지 않고 가라앉기 때문에","correct":true},{"t":"흙과 물이 섞여 있기 때문에","mis":"SC5-1-u3-X08"}],"mis":"SC5-1-u3-X08","explanation":["오래 두면 어떤가요?","흙이 가라앉아요.","용액이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#4','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C14',1,'mc','auto','이슬반 일지 ④에서 비커마다 물 50 mL를 똑같이 맞출 때 쓴 도구로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X19']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C14","difficulty":1,"kind":"mc","stem":"이슬반 일지 ④에서 비커마다 물 50 mL를 똑같이 맞출 때 쓴 도구로 알맞은 것은 어느 것인가요?","options":[{"t":"눈금실린더","correct":true},{"t":"전자저울","mis":"SC5-1-u3-X19"},{"t":"유리 막대","mis":"SC5-1-u3-X19"},{"t":"핀셋","mis":"SC5-1-u3-X19"}],"explanation":["물의 양을 재요.","눈금이 있어요.","눈금실린더예요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#5','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C10',1,'mc','auto','설탕물에서 단맛이 나는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X13','SC5-1-u3-X11']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C10","difficulty":1,"kind":"mc","stem":"설탕물에서 단맛이 나는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"녹은 설탕이 용액 속에 그대로 있기 때문에","correct":true},{"t":"물이 설탕으로 변했기 때문에","mis":"SC5-1-u3-X13"},{"t":"설탕이 사라지면서 맛만 남겼기 때문에","mis":"SC5-1-u3-X11"},{"t":"유리병에서 단맛이 나왔기 때문에","mis":"SC5-1-u3-X11"}],"explanation":["설탕은 어디 있나요?","용액 속이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#6','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C7',1,'blank','auto','「세 물질을 넣고 흔든 뒤 평평한 곳에 내려놓고 (    ) 정도 지나 관찰합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X10']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C7","difficulty":1,"kind":"blank","stem":"「세 물질을 넣고 흔든 뒤 평평한 곳에 내려놓고 (    ) 정도 지나 관찰합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"5분","correct":true},{"t":"1초","mis":"SC5-1-u3-X10"},{"t":"하루","mis":"SC5-1-u3-X10"},{"t":"한 달","mis":"SC5-1-u3-X10"}],"explanation":["조금 기다려요.","몇 분이에요.","5분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#7','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C12',1,'mc','auto','이슬반 일지 ④에서 설탕과 소금을 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X16']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C12","difficulty":1,"kind":"mc","stem":"이슬반 일지 ④에서 설탕과 소금을 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 조건에서 설탕이 소금보다 더 많이 용해되었다","correct":true},{"t":"소금이 설탕보다 더 많이 용해되었다","mis":"SC5-1-u3-X16"},{"t":"설탕과 소금이 같은 양만큼 용해되었다","mis":"SC5-1-u3-X16"},{"t":"소금은 한 숟가락도 녹지 않았다","mis":"SC5-1-u3-X16"}],"explanation":["어느 것이 먼저 남았나요?","소금이 먼저 남았어요.","설탕이 더 많이 녹았어요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#8','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C17',1,'mc','auto','이슬반 일지 ⑤에서 다르게 한 조건은 어느 것인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C17","difficulty":1,"kind":"mc","stem":"이슬반 일지 ⑤에서 다르게 한 조건은 어느 것인가요?","options":[{"t":"물의 온도","correct":true},{"t":"물의 양","mis":"SC5-1-u3-X24"},{"t":"용질의 종류","mis":"SC5-1-u3-X24"},{"t":"약숟가락의 크기","mis":"SC5-1-u3-X24"}],"explanation":["두 비커가 무엇이 달랐나요?","차가운 물과 따뜻한 물이에요.","물의 온도예요."],"asset":{"type":"passage","lines":["같은 양의 물에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 둘째 숟가락부터 바닥에 남았다.","따뜻한 물 — 넷째 숟가락까지 모두 용해되었다.","백반이 남은 차가운 물 비커를 데우니 남은 백반이 녹았다."],"title":"이슬반 탐구 일지 ⑤ 물의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#9','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C9',2,'mc','auto','이슬반 일지 ③에서 각설탕이 모두 용해된 뒤 설탕물 유리병만의 무게는 몇 g일까요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X14','SC5-1-u3-X12']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C9","difficulty":2,"kind":"mc","stem":"이슬반 일지 ③에서 각설탕이 모두 용해된 뒤 설탕물 유리병만의 무게는 몇 g일까요?","options":[{"t":"140 g","correct":true},{"t":"136 g","mis":"SC5-1-u3-X11"},{"t":"150 g","mis":"SC5-1-u3-X14"},{"t":"146 g","mis":"SC5-1-u3-X12"}],"explanation":["함께 잰 무게는 150 g이에요.","빈 접시 10 g을 빼요.","140 g이에요."],"asset":{"type":"passage","lines":["용해되기 전: 물이 든 유리병 + 각설탕을 담은 접시 = 150 g","각설탕 한 개 = 4 g, 빈 페트리 접시 = 10 g","각설탕이 모두 용해된 뒤: 설탕물 유리병 + 빈 접시 = ( ? )"],"title":"이슬반 탐구 일지 ③ 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#10','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C15',2,'sa','auto','이슬반 일지 ⑤에서 따뜻한 물에 모두 용해된 백반은 몇 숟가락인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C15","difficulty":2,"kind":"sa","stem":"이슬반 일지 ⑤에서 따뜻한 물에 모두 용해된 백반은 몇 숟가락인지 쓰세요.","answer":["4","4숟가락","4 숟가락","네 숟가락","넷"],"explanation":["넷째까지 녹았어요.","숟가락을 세어요.","네 숟가락이에요."],"asset":{"type":"passage","lines":["같은 양의 물에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 둘째 숟가락부터 바닥에 남았다.","따뜻한 물 — 넷째 숟가락까지 모두 용해되었다.","백반이 남은 차가운 물 비커를 데우니 남은 백반이 녹았다."],"title":"이슬반 탐구 일지 ⑤ 물의 온도"},"mis":"SC5-1-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#11','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C10',2,'ox','auto','각설탕이 다 녹은 설탕물에는 설탕이 남아 있지 않아요.',ARRAY['SC5-1-u3-X11']::text[],false,'{"seq":11,"concept":"SC5-1-u3-C10","difficulty":2,"kind":"ox","stem":"각설탕이 다 녹은 설탕물에는 설탕이 남아 있지 않아요.","answer":"X","reason_options":[{"t":"녹은 설탕은 사라지지 않고 용액 속에 그대로 있기 때문에","correct":true},{"t":"눈에 보이지 않으면 없어진 것이기 때문에","mis":"SC5-1-u3-X11"}],"mis":"SC5-1-u3-X11","explanation":["무게와 맛을 떠올려요.","그대로 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#12','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C11',2,'mc','auto','무게 비교 실험의 결과를 기록하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X14']::text[],false,'{"seq":12,"concept":"SC5-1-u3-C11","difficulty":2,"kind":"mc","stem":"무게 비교 실험의 결과를 기록하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"예상과 달라도 탐구 결과를 사실대로 기록한다","correct":true},{"t":"예상에 맞게 고쳐 적는다","mis":"SC5-1-u3-X14"},{"t":"다른 모둠의 결과를 그대로 베낀다","mis":"SC5-1-u3-X14"},{"t":"기록하지 않고 기억해 둔다","mis":"SC5-1-u3-X14"}],"explanation":["결과는 고치지 않아요.","있는 그대로예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#13','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C14',2,'match','auto','도구와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u3-C14","difficulty":2,"kind":"match","stem":"도구와 하는 일을 알맞게 이으세요.","pairs":[{"l":"비커","r":"용질을 녹이는 그릇이다"},{"l":"눈금실린더","r":"물의 양을 잰다"},{"l":"유리 막대","r":"용액을 젓는다"},{"l":"전자저울","r":"무게를 잰다"}],"mis":"SC5-1-u3-X19","explanation":["하나씩 떠올려요.","담고, 재고, 젓고, 재요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#14','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C16',2,'mc','auto','이슬반 일지 ⑤에서 차가운 물 비커에 남은 백반을 녹인 방법은 어느 것인가요?',ARRAY['SC5-1-u3-X23','SC5-1-u3-X22']::text[],false,'{"seq":14,"concept":"SC5-1-u3-C16","difficulty":2,"kind":"mc","stem":"이슬반 일지 ⑤에서 차가운 물 비커에 남은 백반을 녹인 방법은 어느 것인가요?","options":[{"t":"비커를 데워 물의 온도를 높였다","correct":true},{"t":"백반을 더 넣었다","mis":"SC5-1-u3-X23"},{"t":"비커를 얼음물에 담갔다","mis":"SC5-1-u3-X22"},{"t":"물을 조금 덜어 냈다","mis":"SC5-1-u3-X23"}],"explanation":["④번 줄을 읽어요.","데웠어요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 양의 물에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 둘째 숟가락부터 바닥에 남았다.","따뜻한 물 — 넷째 숟가락까지 모두 용해되었다.","백반이 남은 차가운 물 비커를 데우니 남은 백반이 녹았다."],"title":"이슬반 탐구 일지 ⑤ 물의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#15','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C12',2,'error','auto','이슬반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X17','SC5-1-u3-X16']::text[],false,'{"seq":15,"concept":"SC5-1-u3-C12","difficulty":2,"kind":"error","stem":"이슬반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태준 — 「소금이 남은 건 실험을 잘못해서야.」","correct":true,"mis_target":"SC5-1-u3-X17"},{"t":"나린 — 「같은 조건에서도 녹는 양은 용질마다 달라.」","mis":"SC5-1-u3-X16"},{"t":"은호 — 「백반은 가장 적게 녹았어.」","mis":"SC5-1-u3-X16"}],"explanation":["조건은 같았어요.","용질마다 달라요.","태준이 잘못 말했어요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#16','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C13',2,'mc','auto','이슬반 일지 ④에서 소금 비커에만 물을 더 부으려던 친구가 멈춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X18']::text[],false,'{"seq":16,"concept":"SC5-1-u3-C13","difficulty":2,"kind":"mc","stem":"이슬반 일지 ④에서 소금 비커에만 물을 더 부으려던 친구가 멈춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물의 양이 달라지면 용질의 종류 때문인지 알 수 없기 때문에","correct":true},{"t":"물을 부으면 소금이 사라지기 때문에","mis":"SC5-1-u3-X11"},{"t":"물의 양은 녹는 양과 관계없기 때문에","mis":"SC5-1-u3-X18"},{"t":"물을 부으면 실험이 너무 빨리 끝나기 때문에","mis":"SC5-1-u3-X18"}],"explanation":["공정한 비교예요.","물의 양은 같아야 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#17','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C9',3,'mc','auto','이슬반 일지 ③의 설탕물 유리병에 4 g인 각설탕 하나를 더 넣어 모두 녹이면 설탕물 유리병의 무게는 몇 g이 될까요?',ARRAY['SC5-1-u3-X11','SC5-1-u3-X12','SC5-1-u3-X14']::text[],false,'{"seq":17,"concept":"SC5-1-u3-C9","difficulty":3,"kind":"mc","stem":"이슬반 일지 ③의 설탕물 유리병에 4 g인 각설탕 하나를 더 넣어 모두 녹이면 설탕물 유리병의 무게는 몇 g이 될까요?","options":[{"t":"144 g","correct":true},{"t":"140 g","mis":"SC5-1-u3-X11"},{"t":"136 g","mis":"SC5-1-u3-X12"},{"t":"154 g","mis":"SC5-1-u3-X14"}],"explanation":["설탕물 유리병은 140 g이에요.","녹은 각설탕도 그대로 있어요.","144 g이에요."],"asset":{"type":"passage","lines":["용해되기 전: 물이 든 유리병 + 각설탕을 담은 접시 = 150 g","각설탕 한 개 = 4 g, 빈 페트리 접시 = 10 g","각설탕이 모두 용해된 뒤: 설탕물 유리병 + 빈 접시 = ( ? )"],"title":"이슬반 탐구 일지 ③ 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#18','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C12',3,'mc','auto','이슬반 일지 ④의 결과를 바르게 해석한 것은 어느 것인가요?',ARRAY['SC5-1-u3-X05','SC5-1-u3-X17','SC5-1-u3-X16']::text[],false,'{"seq":18,"concept":"SC5-1-u3-C12","difficulty":3,"kind":"mc","stem":"이슬반 일지 ④의 결과를 바르게 해석한 것은 어느 것인가요?","options":[{"t":"같은 온도, 같은 양의 물에 녹는 양은 용질의 종류에 따라 다르다","correct":true},{"t":"소금과 백반은 물이 부족해서 남았을 뿐 조건과 관계없다","mis":"SC5-1-u3-X05"},{"t":"더 오래 저었다면 셋 다 끝없이 녹았을 것이다","mis":"SC5-1-u3-X17"},{"t":"모든 용질은 같은 양만큼 녹는다","mis":"SC5-1-u3-X16"}],"explanation":["조건은 같았어요.","용질만 달랐어요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#19','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C15',3,'ox','auto','물의 온도는 용질이 용해되는 양과 관계없어요.',ARRAY['SC5-1-u3-X21']::text[],false,'{"seq":19,"concept":"SC5-1-u3-C15","difficulty":3,"kind":"ox","stem":"물의 온도는 용질이 용해되는 양과 관계없어요.","answer":"X","reason_options":[{"t":"물의 양이 같을 때 물의 온도가 높을수록 더 많이 용해되기 때문에","correct":true},{"t":"용해되는 양은 용질의 종류로만 정해지기 때문에","mis":"SC5-1-u3-X21"}],"mis":"SC5-1-u3-X21","explanation":["이슬반 일지 ⑤를 떠올려요.","따뜻한 물에서 더 녹았어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#20','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C12',3,'mc','auto','이슬반 일지 ⑧에서 도윤의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X05','SC5-1-u3-X17','SC5-1-u3-X16']::text[],false,'{"seq":20,"concept":"SC5-1-u3-C12","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑧에서 도윤의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「같은 양의 물이라도 녹는 양은 용질의 종류에 따라 달라서 바닥에 남을 수 있어.」","correct":true},{"t":"「맞아, 물이 부족해서 남는 거야.」","mis":"SC5-1-u3-X05"},{"t":"「더 오래 저으면 다 녹아.」","mis":"SC5-1-u3-X17"},{"t":"「모든 용질은 똑같이 녹아.」","mis":"SC5-1-u3-X16"}],"explanation":["일지 ④를 떠올려요.","용질마다 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「녹아서 안 보이면 설탕은 없어진 거야.」","도윤 — 「바닥에 남는 건 언제나 물이 부족해서야.」","서아 — 「물이 차가울수록 더 많이 녹아.」","민호 — 「진한 용액일수록 방울토마토가 가라앉아.」","지우 — 「용액은 과학실에만 있어.」","다온 — 「디지털 자료는 화려할수록 좋아.」"],"title":"이슬반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#21','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C17',3,'mc','auto','「용질의 종류에 따라 녹는 양 비교」 계획에서 다르게 할 조건에 「용질의 종류, 물의 온도」를, 같게 할 조건에 「물의 양」을 적었어요. 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":21,"concept":"SC5-1-u3-C17","difficulty":3,"kind":"mc","stem":"「용질의 종류에 따라 녹는 양 비교」 계획에서 다르게 할 조건에 「용질의 종류, 물의 온도」를, 같게 할 조건에 「물의 양」을 적었어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"물의 온도를 같게 할 조건으로 옮긴다","correct":true},{"t":"물의 양을 다르게 할 조건으로 옮긴다","mis":"SC5-1-u3-X24"},{"t":"다르게 할 조건에 약숟가락 크기를 더한다","mis":"SC5-1-u3-X24"},{"t":"고칠 것이 없다","mis":"SC5-1-u3-X24"}],"explanation":["무엇을 알아보나요?","용질의 종류예요.","온도는 같게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#22','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C16',3,'mc','auto','추운 날 찬물로 설거지를 하는데 가루 세제가 잘 녹지 않아요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u3-X23','SC5-1-u3-X22']::text[],false,'{"seq":22,"concept":"SC5-1-u3-C16","difficulty":3,"kind":"mc","stem":"추운 날 찬물로 설거지를 하는데 가루 세제가 잘 녹지 않아요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"따뜻한 물을 쓴다","correct":true},{"t":"가루 세제를 더 넣는다","mis":"SC5-1-u3-X23"},{"t":"더 차가운 물을 쓴다","mis":"SC5-1-u3-X22"},{"t":"물의 양을 줄인다","mis":"SC5-1-u3-X23"}],"explanation":["온도를 떠올려요.","높이면 더 녹아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#23','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C17',4,'mc','auto','용질의 종류와 물의 온도가 녹는 양에 주는 영향을 모두 알아보려고 해요. 가장 알맞은 계획은 어느 것인가요?',ARRAY['SC5-1-u3-X24','SC5-1-u3-X18','SC5-1-u3-X21']::text[],false,'{"seq":23,"concept":"SC5-1-u3-C17","difficulty":4,"kind":"mc","stem":"용질의 종류와 물의 온도가 녹는 양에 주는 영향을 모두 알아보려고 해요. 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"한 번에 하나씩 — 먼저 온도는 같게 하고 용질만 바꾸고, 다음에는 용질은 같게 하고 온도만 바꾼다","correct":true},{"t":"한 번의 실험에서 용질과 온도를 함께 바꾼다","mis":"SC5-1-u3-X24"},{"t":"용질과 온도에 물의 양까지 함께 바꾼다","mis":"SC5-1-u3-X18"},{"t":"온도는 관계없으니 용질만 알아본다","mis":"SC5-1-u3-X21"}],"explanation":["다르게 할 것은 하나씩이에요.","두 번 나누어 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#24','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C10',4,'essay','teacher','이슬반 일지 ③의 ( ? )에 들어갈 무게와 그렇게 생각한 까닭을 쓰고, 일지 ⑧의 하람이 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u3-C10","difficulty":4,"kind":"essay","stem":"이슬반 일지 ③의 ( ? )에 들어갈 무게와 그렇게 생각한 까닭을 쓰고, 일지 ⑧의 하람이 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: ( ? )에 들어갈 무게는 150 g이다. 각설탕은 크기가 점점 작아져 눈에 보이지 않게 되었을 뿐, 사라진 것이 아니라 용액 속에 그대로 있기 때문에 용해되기 전과 후의 무게가 같다. 하람아, 설탕은 없어진 것이 아니야. 설탕물에서 단맛이 나고 무게도 그대로인 것이 그 증거야.","scoring_points":["150 g이라고 썼는가","용액 속에 그대로 있다는 까닭을 썼는가","증거를 들어 하람의 생각을 바로잡았는가"]},"explanation":["무게부터 써요.","까닭을 이어요.","하람에게 말해 줘요."],"asset":{"type":"passage","lines":["용해되기 전: 물이 든 유리병 + 각설탕을 담은 접시 = 150 g","각설탕 한 개 = 4 g, 빈 페트리 접시 = 10 g","각설탕이 모두 용해된 뒤: 설탕물 유리병 + 빈 접시 = ( ? )"],"title":"이슬반 탐구 일지 ③ 무게 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_b#25','sci',5,1,'u3','','g5_1_sci_u3_review_b','unit_review','SC5-1-u3-C23',4,'essay','teacher','이슬반 일지 ⑦의 조사표에서 용액 두 가지를 골라 쓰임을 설명하고, 조사표에서 고쳐야 할 점과 일지 ⑧의 지우에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u3-C23","difficulty":4,"kind":"essay","stem":"이슬반 일지 ⑦의 조사표에서 용액 두 가지를 골라 쓰임을 설명하고, 조사표에서 고쳐야 할 점과 일지 ⑧의 지우에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 손 소독제는 손에 묻은 세균을 없앨 때, 식초는 음식에 신맛을 더할 때 쓴다. 조사표에는 자료의 출처가 모두 비어 있으므로 어디에서 찾은 자료인지 출처를 밝혀 적어야 한다. 지우야, 손 소독제와 식초처럼 우리 집과 학교에도 용액이 많아. 용액은 과학실에만 있는 것이 아니야.","scoring_points":["용액 두 가지의 쓰임을 바르게 썼는가","출처를 밝혀야 한다고 썼는가","생활 속 용액을 들어 지우의 생각을 바로잡았는가"]},"explanation":["조사표를 읽어요.","빈칸을 찾아요.","지우에게 말해 줘요."],"asset":{"type":"passage","lines":["손 소독제 — 손에 묻은 세균을 없앤다.","식초 — 음식에 신맛을 더한다.","식물 영양제 — 양분이 녹아 있어 식물 성장을 돕는다.","구강 청결제 — 입안을 청결하게 한다.","자료의 출처 — 네 칸 모두 비어 있음"],"title":"이슬반 탐구 일지 ⑦ 생활 속 용액 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#1','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C12',1,'mc','auto','이슬반 일지 ④에서 가장 적게 용해된 용질은 어느 것인가요?',ARRAY['SC5-1-u3-X16']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C12","difficulty":1,"kind":"mc","stem":"이슬반 일지 ④에서 가장 적게 용해된 용질은 어느 것인가요?","options":[{"t":"백반","correct":true},{"t":"설탕","mis":"SC5-1-u3-X16"},{"t":"소금","mis":"SC5-1-u3-X16"},{"t":"셋 다 같다","mis":"SC5-1-u3-X16"}],"explanation":["가장 먼저 남은 것이에요.","둘째 숟가락부터 남았어요.","백반이에요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#2','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C15',1,'sa','auto','「물의 양이 같을 때 물의 온도가 □□수록 용질이 더 많이 용해됩니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C15","difficulty":1,"kind":"sa","stem":"「물의 양이 같을 때 물의 온도가 □□수록 용질이 더 많이 용해됩니다.」 □□에 알맞은 말을 쓰세요.","answer":["높을"],"explanation":["따뜻한 물을 떠올려요.","두 글자예요.","높을수록이에요."],"mis":"SC5-1-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#3','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C20',1,'ox','auto','흰 종이를 비커 뒤에 대면 색깔이 있는 용액의 진하기를 더 정확하게 볼 수 있어요.',ARRAY['SC5-1-u3-X29']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C20","difficulty":1,"kind":"ox","stem":"흰 종이를 비커 뒤에 대면 색깔이 있는 용액의 진하기를 더 정확하게 볼 수 있어요.","answer":"O","reason_options":[{"t":"흰 바탕에서 색깔의 차이가 잘 보이기 때문에","correct":true},{"t":"흰 종이가 용액을 더 진하게 만들기 때문에","mis":"SC5-1-u3-X29"}],"mis":"SC5-1-u3-X29","explanation":["흰 바탕을 떠올려요.","색이 잘 보여요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#4','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C21',1,'mc','auto','이슬반 일지 ⑥에서 가장 진한 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X26','SC5-1-u3-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C21","difficulty":1,"kind":"mc","stem":"이슬반 일지 ⑥에서 가장 진한 용액은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"SC5-1-u3-X28"},{"t":"㉯","mis":"SC5-1-u3-X26"},{"t":"뜨는 정도로는 알 수 없다","mis":"SC5-1-u3-X27"}],"explanation":["가장 높이 뜬 것이에요.","진할수록 높이 떠요.","㉰예요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#5','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C16',1,'mc','auto','바닥에 남은 백반을 녹이는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X23','SC5-1-u3-X22','SC5-1-u3-X21']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C16","difficulty":1,"kind":"mc","stem":"바닥에 남은 백반을 녹이는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"물의 온도를 높인다","correct":true},{"t":"백반을 더 넣는다","mis":"SC5-1-u3-X23"},{"t":"물을 차갑게 한다","mis":"SC5-1-u3-X22"},{"t":"그대로 두고 지켜본다","mis":"SC5-1-u3-X21"}],"explanation":["온도를 떠올려요.","높이면 더 녹아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#6','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C13',1,'blank','auto','「공정하게 비교하려면 (    )만 다르게 하고 나머지는 모두 같게 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X18','SC5-1-u3-X24']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C13","difficulty":1,"kind":"blank","stem":"「공정하게 비교하려면 (    )만 다르게 하고 나머지는 모두 같게 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"알아보려는 조건 하나","correct":true},{"t":"모든 조건","mis":"SC5-1-u3-X18"},{"t":"두 가지 이상의 조건","mis":"SC5-1-u3-X24"},{"t":"아무 조건","mis":"SC5-1-u3-X18"}],"explanation":["공정한 비교예요.","하나만 달라요.","알아보려는 조건 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#7','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C22',1,'mc','auto','화분의 식물 성장을 도우려고 쓰는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X33']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C22","difficulty":1,"kind":"mc","stem":"화분의 식물 성장을 도우려고 쓰는 용액은 어느 것인가요?","options":[{"t":"식물 영양제","correct":true},{"t":"구강 청결제","mis":"SC5-1-u3-X33"},{"t":"손 소독제","mis":"SC5-1-u3-X33"},{"t":"식초","mis":"SC5-1-u3-X33"}],"explanation":["식물에 양분이 필요해요.","화분에 꽂아요.","식물 영양제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#8','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C21',1,'mc','auto','크기와 무게가 같은 방울토마토는 용액이 진할수록 어떻게 되나요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X27','SC5-1-u3-X11']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C21","difficulty":1,"kind":"mc","stem":"크기와 무게가 같은 방울토마토는 용액이 진할수록 어떻게 되나요?","options":[{"t":"더 높이 떠오른다","correct":true},{"t":"더 깊이 가라앉는다","mis":"SC5-1-u3-X28"},{"t":"진하기와 관계없이 높이가 같다","mis":"SC5-1-u3-X27"},{"t":"녹아서 없어진다","mis":"SC5-1-u3-X11"}],"explanation":["㉰를 떠올려요.","높이 떠요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#9','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C15',2,'mc','auto','이슬반 일지 ⑤로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X21']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C15","difficulty":2,"kind":"mc","stem":"이슬반 일지 ⑤로 알 수 있는 것은 어느 것인가요?","options":[{"t":"물의 양이 같을 때 물의 온도가 높을수록 백반이 더 많이 용해된다","correct":true},{"t":"물의 온도가 낮을수록 더 많이 용해된다","mis":"SC5-1-u3-X22"},{"t":"물의 온도는 녹는 양과 관계없다","mis":"SC5-1-u3-X21"},{"t":"백반은 차가운 물에 한 숟가락도 녹지 않는다","mis":"SC5-1-u3-X21"}],"explanation":["두 비커를 견줘요.","따뜻한 물에서 더 녹았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 양의 물에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 둘째 숟가락부터 바닥에 남았다.","따뜻한 물 — 넷째 숟가락까지 모두 용해되었다.","백반이 남은 차가운 물 비커를 데우니 남은 백반이 녹았다."],"title":"이슬반 탐구 일지 ⑤ 물의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#10','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C19',2,'sa','auto','이슬반 일지 ⑥의 ㉮와 ㉯ 가운데 더 묽은 용액의 기호를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C19","difficulty":2,"kind":"sa","stem":"이슬반 일지 ⑥의 ㉮와 ㉯ 가운데 더 묽은 용액의 기호를 쓰세요.","answer":["㉮","가"],"explanation":["물의 양이 같아요.","용질이 적은 쪽이에요.","㉮예요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"},"mis":"SC5-1-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#11','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C13',2,'ox','auto','세 용질을 비교할 때 물의 양을 비커마다 다르게 해도 돼요.',ARRAY['SC5-1-u3-X18']::text[],false,'{"seq":11,"concept":"SC5-1-u3-C13","difficulty":2,"kind":"ox","stem":"세 용질을 비교할 때 물의 양을 비커마다 다르게 해도 돼요.","answer":"X","reason_options":[{"t":"물의 양이 다르면 용질의 종류 때문인지 알 수 없기 때문에","correct":true},{"t":"물의 양은 녹는 양과 관계없기 때문에","mis":"SC5-1-u3-X18"}],"mis":"SC5-1-u3-X18","explanation":["하나만 달라야 해요.","물의 양은 같게 해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#12','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C20',2,'mc','auto','이슬반 일지 ⑥의 세 용액을 색깔로 가리기 어려웠던 까닭은 어느 것인가요?',ARRAY['SC5-1-u3-X25','SC5-1-u3-X29','SC5-1-u3-X27']::text[],false,'{"seq":12,"concept":"SC5-1-u3-C20","difficulty":2,"kind":"mc","stem":"이슬반 일지 ⑥의 세 용액을 색깔로 가리기 어려웠던 까닭은 어느 것인가요?","options":[{"t":"백설탕 용액은 색깔이 거의 같기 때문에","correct":true},{"t":"세 용액의 진하기가 모두 같기 때문에","mis":"SC5-1-u3-X25"},{"t":"방울토마토가 색깔을 가리기 때문에","mis":"SC5-1-u3-X29"},{"t":"진하기는 어떤 방법으로도 가릴 수 없기 때문에","mis":"SC5-1-u3-X27"}],"explanation":["어떤 설탕을 썼나요?","백설탕이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#13','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C21',2,'match','auto','진하기를 비교하는 방법과 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u3-C21","difficulty":2,"kind":"match","stem":"진하기를 비교하는 방법과 예를 알맞게 이으세요.","pairs":[{"l":"색깔로 비교하기","r":"황설탕 용액 뒤에 흰 종이를 대고 본다"},{"l":"뜨는 정도로 비교하기","r":"백설탕 용액에 방울토마토를 넣는다"},{"l":"수치로 비교하기","r":"디지털 염도계를 쓴다"}],"mis":"SC5-1-u3-X29","explanation":["방법을 하나씩 떠올려요.","색깔, 높이, 수치예요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#14','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C19',2,'mc','auto','이슬반 일지 ⑥의 ㉯와 ㉰를 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X25','SC5-1-u3-X27']::text[],false,'{"seq":14,"concept":"SC5-1-u3-C19","difficulty":2,"kind":"mc","stem":"이슬반 일지 ⑥의 ㉯와 ㉰를 바르게 견준 것은 어느 것인가요?","options":[{"t":"㉰가 더 진하다 — 같은 양의 설탕이 더 적은 물에 녹아 있기 때문에","correct":true},{"t":"㉯가 더 진하다 — 물이 더 많기 때문에","mis":"SC5-1-u3-X26"},{"t":"진하기가 같다 — 설탕의 양이 같기 때문에","mis":"SC5-1-u3-X25"},{"t":"알 수 없다 — 색깔이 같기 때문에","mis":"SC5-1-u3-X27"}],"explanation":["설탕 양은 같아요.","물의 양이 달라요.","㉰가 더 진해요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#15','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C17',2,'error','auto','온도 요인 탐구를 계획하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X24']::text[],false,'{"seq":15,"concept":"SC5-1-u3-C17","difficulty":2,"kind":"error","stem":"온도 요인 탐구를 계획하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「다르게 할 조건은 많을수록 좋아.」","correct":true,"mis_target":"SC5-1-u3-X24"},{"t":"선우 — 「다르게 할 조건은 물의 온도 하나야.」","mis":"SC5-1-u3-X24"},{"t":"윤슬 — 「물의 양과 용질의 종류는 같게 해.」","mis":"SC5-1-u3-X24"}],"explanation":["몇 개를 다르게 하나요?","하나예요.","지아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#16','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C18',2,'mc','auto','같은 양의 물에 황설탕을 한 숟가락 녹인 용액과 다섯 숟가락 녹인 용액의 진하기를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X25','SC5-1-u3-X29']::text[],false,'{"seq":16,"concept":"SC5-1-u3-C18","difficulty":2,"kind":"mc","stem":"같은 양의 물에 황설탕을 한 숟가락 녹인 용액과 다섯 숟가락 녹인 용액의 진하기를 바르게 말한 것은 어느 것인가요?","options":[{"t":"다섯 숟가락을 녹인 용액이 더 진하다","correct":true},{"t":"한 숟가락을 녹인 용액이 더 진하다","mis":"SC5-1-u3-X26"},{"t":"물의 양이 같으니 진하기도 같다","mis":"SC5-1-u3-X25"},{"t":"맛을 보아야만 알 수 있다","mis":"SC5-1-u3-X29"}],"explanation":["용매의 양이 같아요.","용질이 많은 쪽이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#17','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C15',3,'mc','auto','이슬반 일지 ⑤의 결과를 생활에 이용한 예로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X23']::text[],false,'{"seq":17,"concept":"SC5-1-u3-C15","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑤의 결과를 생활에 이용한 예로 알맞은 것은 어느 것인가요?","options":[{"t":"분말주스를 많이 녹이려고 따뜻한 물에 녹인다","correct":true},{"t":"분말주스를 많이 녹이려고 얼음물에 녹인다","mis":"SC5-1-u3-X22"},{"t":"남은 가루를 녹이려고 가루를 계속 더 넣는다","mis":"SC5-1-u3-X23"},{"t":"물의 양을 줄이고 더 차갑게 한다","mis":"SC5-1-u3-X22"}],"explanation":["온도가 높을수록 많이 녹아요.","따뜻한 물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 양의 물에 백반을 한 숟가락씩 넣으며 저음","차가운 물 — 둘째 숟가락부터 바닥에 남았다.","따뜻한 물 — 넷째 숟가락까지 모두 용해되었다.","백반이 남은 차가운 물 비커를 데우니 남은 백반이 녹았다."],"title":"이슬반 탐구 일지 ⑤ 물의 온도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#18','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C21',3,'mc','auto','진하기를 비교하는 실험 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X29']::text[],false,'{"seq":18,"concept":"SC5-1-u3-C21","difficulty":3,"kind":"mc","stem":"진하기를 비교하는 실험 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"크기와 무게가 같은 방울토마토를 골라 쓴다","correct":true},{"t":"크기가 서로 다른 방울토마토를 쓴다","mis":"SC5-1-u3-X29"},{"t":"용액을 맛보고 더 단 쪽을 고른다","mis":"SC5-1-u3-X29"},{"t":"쓴 방울토마토를 닦지 않고 다른 용액에 넣는다","mis":"SC5-1-u3-X29"}],"explanation":["공정하게 견줘요.","같은 물체를 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#19','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C19',3,'ox','auto','같은 양의 백설탕을 더 많은 물에 녹이면 더 진한 용액이 돼요.',ARRAY['SC5-1-u3-X26']::text[],false,'{"seq":19,"concept":"SC5-1-u3-C19","difficulty":3,"kind":"ox","stem":"같은 양의 백설탕을 더 많은 물에 녹이면 더 진한 용액이 돼요.","answer":"X","reason_options":[{"t":"용질의 양이 같을 때 용매가 많을수록 묽은 용액이 되기 때문에","correct":true},{"t":"물이 많을수록 용액이 더 진해지기 때문에","mis":"SC5-1-u3-X26"}],"mis":"SC5-1-u3-X26","explanation":["㉯와 ㉰를 떠올려요.","물이 많으면 묽어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#20','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C15',3,'mc','auto','이슬반 일지 ⑧에서 서아의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X22','SC5-1-u3-X21']::text[],false,'{"seq":20,"concept":"SC5-1-u3-C15","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑧에서 서아의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「물의 양이 같을 때 온도가 높을수록 더 많이 녹아.」","correct":true},{"t":"「맞아, 차가울수록 더 녹아.」","mis":"SC5-1-u3-X22"},{"t":"「온도는 녹는 양과 관계없어.」","mis":"SC5-1-u3-X21"},{"t":"「차가운 물에는 아무것도 녹지 않아.」","mis":"SC5-1-u3-X21"}],"explanation":["일지 ⑤를 떠올려요.","따뜻한 물에서 더 녹았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「녹아서 안 보이면 설탕은 없어진 거야.」","도윤 — 「바닥에 남는 건 언제나 물이 부족해서야.」","서아 — 「물이 차가울수록 더 많이 녹아.」","민호 — 「진한 용액일수록 방울토마토가 가라앉아.」","지우 — 「용액은 과학실에만 있어.」","다온 — 「디지털 자료는 화려할수록 좋아.」"],"title":"이슬반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#21','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C20',3,'mc','auto','같은 양의 물에 황설탕을 ㉠ 한 숟가락, ㉡ 네 숟가락 녹이고 흰 종이 앞에 두었어요. 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X27','SC5-1-u3-X29']::text[],false,'{"seq":21,"concept":"SC5-1-u3-C20","difficulty":3,"kind":"mc","stem":"같은 양의 물에 황설탕을 ㉠ 한 숟가락, ㉡ 네 숟가락 녹이고 흰 종이 앞에 두었어요. 알맞은 것은 어느 것인가요?","options":[{"t":"㉡의 색깔이 더 진하다","correct":true},{"t":"㉠의 색깔이 더 진하다","mis":"SC5-1-u3-X26"},{"t":"두 용액의 색깔은 똑같아 가릴 수 없다","mis":"SC5-1-u3-X27"},{"t":"흰 종이를 대면 둘 다 하얗게 보인다","mis":"SC5-1-u3-X29"}],"explanation":["황설탕 용액이에요.","많이 녹인 쪽이 진해요.","㉡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#22','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C19',3,'mc','auto','다음 소금물 가운데 가장 묽은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X26']::text[],false,'{"seq":22,"concept":"SC5-1-u3-C19","difficulty":3,"kind":"mc","stem":"다음 소금물 가운데 가장 묽은 것은 어느 것인가요?","options":[{"t":"물 100 mL에 소금 두 숟가락을 녹인 것","correct":true},{"t":"물 100 mL에 소금 다섯 숟가락을 녹인 것","mis":"SC5-1-u3-X26"},{"t":"물 50 mL에 소금 다섯 숟가락을 녹인 것","mis":"SC5-1-u3-X26"},{"t":"물 50 mL에 소금 두 숟가락을 녹인 것","mis":"SC5-1-u3-X26"}],"explanation":["물은 많고 소금은 적은 것이에요.","하나씩 견줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#23','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C21',4,'mc','auto','이슬반 일지 ⑥의 ㉰에 물 50 mL를 더 부으면 방울토마토는 어떻게 될까요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X25','SC5-1-u3-X11']::text[],false,'{"seq":23,"concept":"SC5-1-u3-C21","difficulty":4,"kind":"mc","stem":"이슬반 일지 ⑥의 ㉰에 물 50 mL를 더 부으면 방울토마토는 어떻게 될까요?","options":[{"t":"더 묽어져서 ㉯와 비슷한 높이로 내려간다","correct":true},{"t":"더 진해져서 더 높이 떠오른다","mis":"SC5-1-u3-X26"},{"t":"물만 더했으니 진하기도 높이도 그대로다","mis":"SC5-1-u3-X25"},{"t":"방울토마토가 녹아 없어진다","mis":"SC5-1-u3-X11"}],"explanation":["㉰는 물 50 mL였어요.","물 100 mL에 여섯 숟가락이 돼요.","㉯와 같아져요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#24','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C12',4,'essay','teacher','이슬반 일지 ④의 결과로 알게 된 점을 쓰고, 이 실험에서 같게 한 조건과 다르게 한 조건을 들어 소금 비커에만 물을 더 부으면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u3-C12","difficulty":4,"kind":"essay","stem":"이슬반 일지 ④의 결과로 알게 된 점을 쓰고, 이 실험에서 같게 한 조건과 다르게 한 조건을 들어 소금 비커에만 물을 더 부으면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 같은 온도, 같은 양의 물에 설탕은 여덟 숟가락이 모두 녹았지만 소금은 다섯 숟가락, 백반은 한 숟가락까지만 녹았다. 그래서 용해되는 양은 용질의 종류에 따라 다르다는 것을 알 수 있다. 이 실험은 물의 온도, 물의 양, 숟가락에 담는 양은 같게 하고 용질의 종류만 다르게 했다. 소금 비커에만 물을 더 부으면 물의 양까지 달라져 결과가 용질의 종류 때문인지 알 수 없다.","scoring_points":["용질의 종류에 따라 녹는 양이 다르다고 썼는가","같게 한 조건과 다르게 한 조건을 썼는가","물을 더 부으면 안 되는 까닭을 썼는가"]},"explanation":["결과부터 써요.","조건을 나눠요.","공정한 비교와 이어요."],"asset":{"type":"passage","lines":["같은 온도의 물 50 mL씩, 같은 양을 한 숟가락씩 넣고 충분히 저음","설탕 — 여덟 숟가락을 넣을 때까지 모두 용해되었다.","소금 — 다섯 숟가락까지 용해, 여섯째 숟가락부터 바닥에 남았다.","백반 — 한 숟가락까지 용해, 둘째 숟가락부터 바닥에 남았다.","한 친구가 소금 비커에만 물을 더 부으려다 멈추었다."],"title":"이슬반 탐구 일지 ④ 용질 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_c#25','sci',5,1,'u3','','g5_1_sci_u3_review_c','unit_review','SC5-1-u3-C24',4,'essay','teacher','이슬반 일지 ⑧의 다온에게 해 줄 말을 쓰고, 용액 하나를 골라 그 필요성이 드러나는 디지털 자료의 제목과 담을 내용을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u3-C24","difficulty":4,"kind":"essay","stem":"이슬반 일지 ⑧의 다온에게 해 줄 말을 쓰고, 용액 하나를 골라 그 필요성이 드러나는 디지털 자료의 제목과 담을 내용을 쓰세요.","answer_guide":{"answer":"예: 다온아, 자료를 화려하게 꾸미는 것보다 용액이 왜 필요한지를 옳게 설명하는 것이 더 중요해. 나는 비눗물을 골라 「비눗물이 사라진다면?」이라는 포스터를 만들겠다. 비눗물이 없으면 손을 깨끗이 씻을 수 없고 세균이 옮겨지기 쉽다는 불편함을 그림과 짧은 글로 담는다.","scoring_points":["다온의 생각을 필요성으로 바로잡았는가","필요성이 드러나는 제목을 썼는가","없을 때의 불편함을 내용으로 썼는가"]},"explanation":["다온부터 바로잡아요.","용액 하나를 골라요.","없을 때를 떠올려요."],"asset":{"type":"passage","lines":["하람 — 「녹아서 안 보이면 설탕은 없어진 거야.」","도윤 — 「바닥에 남는 건 언제나 물이 부족해서야.」","서아 — 「물이 차가울수록 더 많이 녹아.」","민호 — 「진한 용액일수록 방울토마토가 가라앉아.」","지우 — 「용액은 과학실에만 있어.」","다온 — 「디지털 자료는 화려할수록 좋아.」"],"title":"이슬반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#1','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C18',1,'mc','auto','용액의 진하기의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X25']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C18","difficulty":1,"kind":"mc","stem":"용액의 진하기의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 양의 용매에 용해된 용질의 양이 많고 적은 정도","correct":true},{"t":"용액의 무게","mis":"SC5-1-u3-X25"},{"t":"물이 얼마나 차가운지","mis":"SC5-1-u3-X25"},{"t":"용질이 녹는 데 걸린 시간","mis":"SC5-1-u3-X25"}],"explanation":["많고 적은 정도예요.","같은 양의 용매예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#2','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C22',1,'sa','auto','「음식에 신맛을 더할 때 쓰는 용액은 □□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u3-C22","difficulty":1,"kind":"sa","stem":"「음식에 신맛을 더할 때 쓰는 용액은 □□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["식초"],"explanation":["신맛이에요.","두 글자예요.","식초예요."],"mis":"SC5-1-u3-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#3','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C23',1,'ox','auto','조사한 자료는 출처를 밝혀 공유해요.',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":3,"concept":"SC5-1-u3-C23","difficulty":1,"kind":"ox","stem":"조사한 자료는 출처를 밝혀 공유해요.","answer":"O","reason_options":[{"t":"자료가 어디에서 나왔는지 알려 믿을 수 있는지 확인할 수 있기 때문에","correct":true},{"t":"출처를 밝히면 다른 사람의 자료를 베껴도 되기 때문에","mis":"SC5-1-u3-X35"}],"mis":"SC5-1-u3-X35","explanation":["자료가 나온 곳이에요.","밝혀야 해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#4','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C25',1,'mc','auto','바닷물의 온도나 염분을 조사하는 직업은 어느 것인가요?',ARRAY['SC5-1-u3-X40','SC5-1-u3-X41']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C25","difficulty":1,"kind":"mc","stem":"바닷물의 온도나 염분을 조사하는 직업은 어느 것인가요?","options":[{"t":"해양학 연구원","correct":true},{"t":"도시 농업 관리사","mis":"SC5-1-u3-X40"},{"t":"식품 공학 기술자","mis":"SC5-1-u3-X40"},{"t":"용액을 연구하는 직업은 없다","mis":"SC5-1-u3-X41"}],"explanation":["바다예요.","해양이에요.","해양학 연구원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#5','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C24',1,'mc','auto','용액의 필요성이 드러나는 자료를 만들려고 할 때 먼저 떠올리면 좋은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X36','SC5-1-u3-X37']::text[],false,'{"seq":5,"concept":"SC5-1-u3-C24","difficulty":1,"kind":"mc","stem":"용액의 필요성이 드러나는 자료를 만들려고 할 때 먼저 떠올리면 좋은 것은 어느 것인가요?","options":[{"t":"용액이 없을 경우 불편한 점","correct":true},{"t":"가장 화려한 글꼴","mis":"SC5-1-u3-X36"},{"t":"다른 모둠보다 큰 화면","mis":"SC5-1-u3-X36"},{"t":"용액의 값","mis":"SC5-1-u3-X37"}],"explanation":["필요성이에요.","없다면 어떨까요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#6','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C19',1,'blank','auto','「용질의 양이 같을 때 용매가 (    ) 진한 용액입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u3-X26','SC5-1-u3-X25']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C19","difficulty":1,"kind":"blank","stem":"「용질의 양이 같을 때 용매가 (    ) 진한 용액입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"적을수록","correct":true},{"t":"많을수록","mis":"SC5-1-u3-X26"},{"t":"차가울수록","mis":"SC5-1-u3-X25"},{"t":"무거울수록","mis":"SC5-1-u3-X25"}],"explanation":["㉯와 ㉰를 견줘요.","물이 적은 쪽이 진해요.","적을수록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#7','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C25',1,'mc','auto','수경 재배에 쓰는 배양액을 개발하는 직업은 어느 것인가요?',ARRAY['SC5-1-u3-X40','SC5-1-u3-X41']::text[],false,'{"seq":7,"concept":"SC5-1-u3-C25","difficulty":1,"kind":"mc","stem":"수경 재배에 쓰는 배양액을 개발하는 직업은 어느 것인가요?","options":[{"t":"도시 농업 관리사","correct":true},{"t":"해양학 연구원","mis":"SC5-1-u3-X40"},{"t":"식품 공학 기술자","mis":"SC5-1-u3-X40"},{"t":"아무도 개발하지 않는다","mis":"SC5-1-u3-X41"}],"explanation":["농업이에요.","식물을 키워요.","도시 농업 관리사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#8','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C23',1,'mc','auto','조사하던 스마트 기기에서 냄새가 나요. 어떻게 해야 하나요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":8,"concept":"SC5-1-u3-C23","difficulty":1,"kind":"mc","stem":"조사하던 스마트 기기에서 냄새가 나요. 어떻게 해야 하나요?","options":[{"t":"즉시 사용을 멈추고 선생님께 알린다","correct":true},{"t":"끝까지 계속 쓴다","mis":"SC5-1-u3-X35"},{"t":"세게 흔들어 본다","mis":"SC5-1-u3-X35"},{"t":"물을 부어 본다","mis":"SC5-1-u3-X35"}],"explanation":["안전이 먼저예요.","멈추고 알려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#9','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C22',2,'mc','auto','이슬반 일지 ⑦에서 세균을 없애는 데 쓰는 용액은 어느 것인가요?',ARRAY['SC5-1-u3-X33']::text[],false,'{"seq":9,"concept":"SC5-1-u3-C22","difficulty":2,"kind":"mc","stem":"이슬반 일지 ⑦에서 세균을 없애는 데 쓰는 용액은 어느 것인가요?","options":[{"t":"손 소독제","correct":true},{"t":"식초","mis":"SC5-1-u3-X33"},{"t":"식물 영양제","mis":"SC5-1-u3-X33"},{"t":"구강 청결제","mis":"SC5-1-u3-X33"}],"explanation":["세균을 찾아요.","손을 소독해요.","손 소독제예요."],"asset":{"type":"passage","lines":["손 소독제 — 손에 묻은 세균을 없앤다.","식초 — 음식에 신맛을 더한다.","식물 영양제 — 양분이 녹아 있어 식물 성장을 돕는다.","구강 청결제 — 입안을 청결하게 한다.","자료의 출처 — 네 칸 모두 비어 있음"],"title":"이슬반 탐구 일지 ⑦ 생활 속 용액 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#10','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C25',2,'sa','auto','「식물을 흙 대신 물에서 키우는 □□ 재배에는 배양액이 쓰입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u3-C25","difficulty":2,"kind":"sa","stem":"「식물을 흙 대신 물에서 키우는 □□ 재배에는 배양액이 쓰입니다.」 □□에 알맞은 말을 쓰세요.","answer":["수경"],"explanation":["물에서 키워요.","두 글자예요.","수경 재배예요."],"mis":"SC5-1-u3-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#11','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C24',2,'ox','auto','다른 모둠 자료에는 잘한 점이나 새롭게 알게 된 점을 댓글로 달아요.',ARRAY['SC5-1-u3-X38']::text[],false,'{"seq":11,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"ox","stem":"다른 모둠 자료에는 잘한 점이나 새롭게 알게 된 점을 댓글로 달아요.","answer":"O","reason_options":[{"t":"바르고 고운 말로 생각을 나누면 서로에게 도움이 되기 때문에","correct":true},{"t":"다른 모둠 자료를 깎아내려야 우리 자료가 돋보이기 때문에","mis":"SC5-1-u3-X38"}],"mis":"SC5-1-u3-X38","explanation":["댓글 약속이에요.","잘한 점을 전해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#12','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C23',2,'mc','auto','이슬반 일지 ⑦의 조사표에서 고쳐야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X35','SC5-1-u3-X34']::text[],false,'{"seq":12,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"mc","stem":"이슬반 일지 ⑦의 조사표에서 고쳐야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료의 출처를 밝혀 적는다","correct":true},{"t":"성질 칸을 지운다","mis":"SC5-1-u3-X35"},{"t":"맛을 보고 느낌을 적는다","mis":"SC5-1-u3-X34"},{"t":"친구 표를 그대로 베낀다","mis":"SC5-1-u3-X35"}],"explanation":["빈칸을 찾아요.","출처가 비었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["손 소독제 — 손에 묻은 세균을 없앤다.","식초 — 음식에 신맛을 더한다.","식물 영양제 — 양분이 녹아 있어 식물 성장을 돕는다.","구강 청결제 — 입안을 청결하게 한다.","자료의 출처 — 네 칸 모두 비어 있음"],"title":"이슬반 탐구 일지 ⑦ 생활 속 용액 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#13','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C22',2,'match','auto','용액과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u3-C22","difficulty":2,"kind":"match","stem":"용액과 쓰임을 알맞게 이으세요.","pairs":[{"l":"간장","r":"음식의 간을 맞춘다"},{"l":"구강 청결제","r":"입안을 청결하게 한다"},{"l":"링거액","r":"병을 치료하는 데 쓴다"},{"l":"식물 영양제","r":"식물의 성장을 돕는다"}],"mis":"SC5-1-u3-X33","explanation":["하나씩 떠올려요.","부엌, 입안, 병원, 화분이에요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#14','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C24',2,'mc','auto','손 소독제의 필요성을 알리는 자료의 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X36','SC5-1-u3-X38']::text[],false,'{"seq":14,"concept":"SC5-1-u3-C24","difficulty":2,"kind":"mc","stem":"손 소독제의 필요성을 알리는 자료의 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「손 소독제가 사라진다면? 세균이 쉽게 옮겨요」","correct":true},{"t":"「손 소독제」","mis":"SC5-1-u3-X37"},{"t":"「반짝반짝 최고의 화면」","mis":"SC5-1-u3-X36"},{"t":"「다른 모둠 자료는 따라 하지 마」","mis":"SC5-1-u3-X38"}],"explanation":["필요성이 드러나야 해요.","없을 때의 불편함이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#15','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C25',2,'error','auto','바닷물과 용액을 연구하는 일에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u3-X40']::text[],false,'{"seq":15,"concept":"SC5-1-u3-C25","difficulty":2,"kind":"error","stem":"바닷물과 용액을 연구하는 일에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정우 — 「바닷물은 용액과 관계없어.」","correct":true,"mis_target":"SC5-1-u3-X40"},{"t":"소은 — 「바다는 여러 물질이 녹아 있는 용액이야.」","mis":"SC5-1-u3-X40"},{"t":"이준 — 「식품 공학 기술자는 용액의 진하기를 확인해.」","mis":"SC5-1-u3-X40"}],"explanation":["바닷물을 떠올려요.","여러 물질이 녹아 있어요.","정우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#16','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C23',2,'mc','auto','공유 플랫폼에 올릴 사진으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X35']::text[],false,'{"seq":16,"concept":"SC5-1-u3-C23","difficulty":2,"kind":"mc","stem":"공유 플랫폼에 올릴 사진으로 알맞은 것은 어느 것인가요?","options":[{"t":"허락을 받은 사진이나 직접 그린 그림","correct":true},{"t":"친구 얼굴이 나온 사진을 몰래 올린 것","mis":"SC5-1-u3-X35"},{"t":"남이 만든 사진을 출처 없이 올린 것","mis":"SC5-1-u3-X35"},{"t":"다른 모둠 자료를 우리 것처럼 올린 것","mis":"SC5-1-u3-X35"}],"explanation":["허락과 출처예요.","직접 만든 것도 좋아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#17','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C21',3,'mc','auto','이슬반 일지 ⑥의 ㉮에 든 방울토마토를 ㉯와 같은 높이로 떠오르게 하려면 어떻게 해야 하나요?',ARRAY['SC5-1-u3-X31','SC5-1-u3-X29']::text[],false,'{"seq":17,"concept":"SC5-1-u3-C21","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑥의 ㉮에 든 방울토마토를 ㉯와 같은 높이로 떠오르게 하려면 어떻게 해야 하나요?","options":[{"t":"㉮에 백설탕 네 숟가락을 더 녹인다","correct":true},{"t":"㉮에 물을 더 붓는다","mis":"SC5-1-u3-X31"},{"t":"더 큰 방울토마토로 바꾼다","mis":"SC5-1-u3-X29"},{"t":"㉮ 용액을 맛보며 조금씩 덜어 낸다","mis":"SC5-1-u3-X29"}],"explanation":["㉮와 ㉯는 물의 양이 같아요.","설탕이 네 숟가락 적어요.","네 숟가락을 더 녹여요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#18','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C24',3,'mc','auto','이슬반 일지 ⑧에서 다온의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X36','SC5-1-u3-X37','SC5-1-u3-X38']::text[],false,'{"seq":18,"concept":"SC5-1-u3-C24","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑧에서 다온의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「꾸미기보다 용액의 필요성을 옳게 설명하는 것이 더 중요해.」","correct":true},{"t":"「맞아, 화려할수록 좋은 자료야.」","mis":"SC5-1-u3-X36"},{"t":"「용액 이름만 크게 쓰면 충분해.」","mis":"SC5-1-u3-X37"},{"t":"「다른 모둠 자료를 깎아내리면 돋보여.」","mis":"SC5-1-u3-X38"}],"explanation":["무엇이 중요한가요?","필요성이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「녹아서 안 보이면 설탕은 없어진 거야.」","도윤 — 「바닥에 남는 건 언제나 물이 부족해서야.」","서아 — 「물이 차가울수록 더 많이 녹아.」","민호 — 「진한 용액일수록 방울토마토가 가라앉아.」","지우 — 「용액은 과학실에만 있어.」","다온 — 「디지털 자료는 화려할수록 좋아.」"],"title":"이슬반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#19','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C22',3,'ox','auto','손 소독제, 식초, 식물 영양제는 모두 용액이에요.',ARRAY['SC5-1-u3-X08']::text[],false,'{"seq":19,"concept":"SC5-1-u3-C22","difficulty":3,"kind":"ox","stem":"손 소독제, 식초, 식물 영양제는 모두 용액이에요.","answer":"O","reason_options":[{"t":"여러 물질이 골고루 섞여 있어 뜨거나 가라앉는 것이 없기 때문에","correct":true},{"t":"병에 담겨 섞여 있기만 하면 모두 용액이기 때문에","mis":"SC5-1-u3-X08"}],"mis":"SC5-1-u3-X08","explanation":["용액의 성질을 떠올려요.","골고루 섞여 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#20','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C21',3,'mc','auto','이슬반 일지 ⑧에서 민호의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X28','SC5-1-u3-X27']::text[],false,'{"seq":20,"concept":"SC5-1-u3-C21","difficulty":3,"kind":"mc","stem":"이슬반 일지 ⑧에서 민호의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「진한 용액일수록 방울토마토가 더 높이 떠올라.」","correct":true},{"t":"「맞아, 진할수록 가라앉아.」","mis":"SC5-1-u3-X28"},{"t":"「진하기와 뜨는 높이는 관계없어.」","mis":"SC5-1-u3-X27"},{"t":"「묽을수록 더 높이 떠올라.」","mis":"SC5-1-u3-X28"}],"explanation":["일지 ⑥을 떠올려요.","㉰가 가장 높이 떴어요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「녹아서 안 보이면 설탕은 없어진 거야.」","도윤 — 「바닥에 남는 건 언제나 물이 부족해서야.」","서아 — 「물이 차가울수록 더 많이 녹아.」","민호 — 「진한 용액일수록 방울토마토가 가라앉아.」","지우 — 「용액은 과학실에만 있어.」","다온 — 「디지털 자료는 화려할수록 좋아.」"],"title":"이슬반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#21','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C23',3,'mc','auto','구강 청결제를 조사할 때 검색어로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X35','SC5-1-u3-X34']::text[],false,'{"seq":21,"concept":"SC5-1-u3-C23","difficulty":3,"kind":"mc","stem":"구강 청결제를 조사할 때 검색어로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"구강 청결제 쓰임새와 성질","correct":true},{"t":"가장 비싼 구강 청결제","mis":"SC5-1-u3-X35"},{"t":"구강 청결제를 마셔 본 맛","mis":"SC5-1-u3-X34"},{"t":"구강 청결제 광고 모델","mis":"SC5-1-u3-X35"}],"explanation":["무엇을 알고 싶나요?","쓰임새와 성질이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#22','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C25',3,'mc','auto','식품 공학 기술자가 새 음료를 만들 때 확인하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X40','SC5-1-u3-X41']::text[],false,'{"seq":22,"concept":"SC5-1-u3-C25","difficulty":3,"kind":"mc","stem":"식품 공학 기술자가 새 음료를 만들 때 확인하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"녹이는 물질의 종류와 순서, 물의 온도, 용액의 진하기","correct":true},{"t":"바다 생물의 수","mis":"SC5-1-u3-X40"},{"t":"화분에 줄 배양액만","mis":"SC5-1-u3-X40"},{"t":"확인할 것이 없다","mis":"SC5-1-u3-X41"}],"explanation":["음료도 용액이에요.","녹이는 것을 확인해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#23','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C24',4,'mc','auto','「우리 곁의 고마운 식초」 자료에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X37','SC5-1-u3-X34','SC5-1-u3-X36']::text[],false,'{"seq":23,"concept":"SC5-1-u3-C24","difficulty":4,"kind":"mc","stem":"「우리 곁의 고마운 식초」 자료에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"식초가 없다면 음식에 신맛을 더하거나 맛을 조절하기 어렵다는 내용","correct":true},{"t":"식초 병의 색깔과 모양만","mis":"SC5-1-u3-X37"},{"t":"식초는 얼마든지 마셔도 된다는 내용","mis":"SC5-1-u3-X34"},{"t":"반짝이 효과만 가득한 화면","mis":"SC5-1-u3-X36"}],"explanation":["필요성이 드러나야 해요.","없을 때를 떠올려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#24','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C19',4,'essay','teacher','이슬반 일지 ⑥의 세 용액을 진한 것부터 차례대로 쓰고, 그렇게 판단한 까닭을 용매와 용질의 양, 방울토마토가 뜬 높이와 이어서 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u3-C19","difficulty":4,"kind":"essay","stem":"이슬반 일지 ⑥의 세 용액을 진한 것부터 차례대로 쓰고, 그렇게 판단한 까닭을 용매와 용질의 양, 방울토마토가 뜬 높이와 이어서 쓰세요.","answer_guide":{"answer":"예: 진한 것부터 ㉰, ㉯, ㉮의 차례이다. ㉮와 ㉯는 물의 양이 같은데 ㉯에 백설탕이 더 많이 녹아 있으므로 ㉯가 더 진하다. ㉯와 ㉰는 백설탕의 양이 같은데 ㉰의 물이 더 적으므로 ㉰가 더 진하다. 방울토마토도 ㉰에서 가장 높이, ㉮에서 가장 낮게 떠서 진할수록 높이 떠오른다는 것과 맞는다.","scoring_points":["㉰, ㉯, ㉮의 차례를 바르게 썼는가","용매·용질의 양을 견주어 까닭을 썼는가","방울토마토의 높이와 이었는가"]},"explanation":["둘씩 견줘요.","물의 양과 설탕의 양을 봐요.","뜬 높이와 이어요."],"asset":{"type":"passage","lines":["㉮ 물 100 mL + 백설탕 두 숟가락 — 방울토마토가 바닥에 가라앉음","㉯ 물 100 mL + 백설탕 여섯 숟가락 — 방울토마토가 가운데쯤 뜸","㉰ 물 50 mL + 백설탕 여섯 숟가락 — 방울토마토가 가장 높이 뜸","세 용액 모두 색깔로는 가리기 어려웠다.","방울토마토는 크기와 무게가 같은 것을 썼다."],"title":"이슬반 탐구 일지 ⑥ 진하기 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u3_review_d#25','sci',5,1,'u3','','g5_1_sci_u3_review_d','unit_review','SC5-1-u3-C5',4,'essay','teacher','「용해와 용액」 단원에서 배운 것을 「용해와 용액 → 녹기 전후의 무게 → 녹는 양을 바꾸는 두 요인 → 용액의 진하기 → 생활 속 용액」의 차례로 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u3-C5","difficulty":4,"kind":"essay","stem":"「용해와 용액」 단원에서 배운 것을 「용해와 용액 → 녹기 전후의 무게 → 녹는 양을 바꾸는 두 요인 → 용액의 진하기 → 생활 속 용액」의 차례로 정리해 쓰세요.","answer_guide":{"answer":"예: 어떤 물질이 다른 물질에 녹아 골고루 섞이는 현상을 용해라고 하고, 녹이는 물질은 용매, 녹는 물질은 용질, 둘이 골고루 섞인 물질은 용액이다. 용질이 용해되기 전과 후의 무게는 같다. 같은 양의 물에 녹는 용질의 양은 용질의 종류와 물의 온도에 따라 다르며, 물의 온도가 높을수록 더 많이 녹는다. 용액의 진하기는 색깔이나 물체가 뜨는 정도로 비교할 수 있다. 손 소독제·식초처럼 우리는 생활에서 여러 용액을 이용한다.","scoring_points":["네 낱말과 무게 보존을 썼는가","두 요인을 바르게 썼는가","진하기 비교 방법과 생활 속 용액을 썼는가"]},"explanation":["처음부터 떠올려요.","두 요인을 넣어요.","진하기와 생활로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
